<script setup lang="ts">
import { ref } from 'vue'

const pickupLocation = ref('')
const dropoffLocation = ref('')
const items = ref([{ name: '', quantity: 1, size: 'medium' }])
const calculatedPrice = ref(0)

const addItem = () => {
  items.value.push({ name: '', quantity: 1, size: 'medium' })
}

const removeItem = (index: number) => {
  items.value.splice(index, 1)
}

const calculatePrice = () => {
  const basePrice = 50
  const sizeMultiplier = {
    small: 1,
    medium: 1.5,
    large: 2,
    xlarge: 3
  }

  calculatedPrice.value = items.value.reduce((total, item) => {
    return total + (basePrice * sizeMultiplier[item.size as keyof typeof sizeMultiplier] * item.quantity)
  }, 0)
}

const submitOrder = () => {
  alert(`Order submitted! Total price: $${calculatedPrice.value}`)
}
</script>

<template>
  <div class="order-form">
    <h2>Create Moving Order</h2>

    <div class="form-group">
      <label>Pickup Location</label>
      <input v-model="pickupLocation" placeholder="Enter pickup address">
    </div>

    <div class="form-group">
      <label>Dropoff Location</label>
      <input v-model="dropoffLocation" placeholder="Enter dropoff address">
    </div>

    <h3>Items to Move</h3>
    <div v-for="(item, index) in items" :key="index" class="item-row">
      <input v-model="item.name" placeholder="Item name">
      <select v-model="item.size">
        <option value="small">Small</option>
        <option value="medium">Medium</option>
        <option value="large">Large</option>
        <option value="xlarge">Extra Large</option>
      </select>
      <input type="number" v-model.number="item.quantity" min="1">
      <button @click="removeItem(index)" class="remove-btn">Remove</button>
    </div>

    <button @click="addItem" class="add-btn">Add Item</button>
    <button @click="calculatePrice" class="calc-btn">Calculate Price</button>

    <div v-if="calculatedPrice > 0" class="price-display">
      <h3>Estimated Price: ${{ calculatedPrice }}</h3>
      <button @click="submitOrder" class="submit-btn">Submit Order</button>
    </div>
  </div>
</template>

