<script setup lang="ts">
import { ref } from 'vue'

const users = ref([
  { id: 1, username: 'student1', name: 'Student One', role: 'user' },
  { id: 2, username: 'student2', name: 'Student Two', role: 'user' },
  { id: 3, username: 'admin1', name: 'Admin One', role: 'admin' }
])

const newUser = ref({
  username: '',
  name: '',
  role: 'user'
})

function addUser() {
  if (!newUser.value.username || !newUser.value.name) return

  users.value.push({
    id: Date.now(),
    ...newUser.value
  })

  newUser.value = {
    username: '',
    name: '',
    role: 'user'
  }
}

function removeUser(id: number) {
  users.value = users.value.filter(user => user.id !== id)
}
</script>

