  <boltAction type="file" filePath="src/composables/useLottery.ts">
import { ref } from 'vue'

interface Prize {
  id: number
  name: string
  image: string
  probability: number
}

export function useLottery() {
  const prizes = ref<Prize[]>([
    { id: 1, name: 'Special Gift', image: '', probability: 0.1 },
    { id: 2, name: 'Discount Coupon', image: '', probability: 0.3 },
    { id: 3, name: 'Free Product', image: '', probability: 0.2 },
    { id: 4, name: 'Thank You', image: '', probability: 0.4 }
  ])

  const currentPrize = ref<Prize>({ id: 0, name: '', image: '', probability: 0 })
  const showResult = ref(false)

  const drawLottery = async () => {
    // Simulate API call delay
    await new Promise(resolve => setTimeout(resolve, 1000))

    const random = Math.random()
    let cumulativeProbability = 0

    for (const prize of prizes.value) {
      cumulativeProbability += prize.probability
      if (random <= cumulativeProbability) {
        currentPrize.value = prize
        showResult.value = true
        break
      }
    }

    // Hide result after 5 seconds
    setTimeout(() => {
      showResult.value = false
    }, 5000)
  }

  return {
    drawLottery,
    currentPrize,
    showResult
  }
}
