<script setup lang="ts">
import { ref } from 'vue'
import PaymentGateway from './components/PaymentGateway.vue'
import OrderSummary from './components/OrderSummary.vue'
import PaymentMethods from './components/PaymentMethods.vue'

const currentStep = ref(1)
const order = ref({
  items: [],
  total: 0,
  status: 'pending'
})
const paymentMethod = ref('')

function addToCart(item: any) {
  order.value.items.push(item)
  order.value.total += item.price
}

function proceedToPayment(method: string) {
  paymentMethod.value = method
  currentStep.value = 2
}

function processPayment() {
  order.value.status = 'paid'
  currentStep.value = 3
}

function issueRefund() {
  order.value.status = 'refunded'
}
</script>

<template>
  <div class="app-container">
    <h1>Online Store Payment System</h1>

    <PaymentGateway 
      v-if="currentStep === 1" 
      @add-to-cart="addToCart"
      @proceed-to-checkout="currentStep = 2"
    />

    <PaymentMethods 
      v-if="currentStep === 2" 
      :order="order"
      @select-method="proceedToPayment"
      @go-back="currentStep = 1"
    />

    <OrderSummary 
      v-if="currentStep === 3" 
      :order="order"
      :paymentMethod="paymentMethod"
      @issue-refund="issueRefund"
