        size: file.size
      }))
      setFiles([...files, ...newFiles])
    }
  }

  const mergeFiles = () => {
    // Simulate merging files
    const mockContent = files.map(f => `/* ${f.name} */\nMock content for ${f.name}\n`).join('\n')
    setMergedContent(mockContent)
    setIsCompressed(false)
  }

  const compressContent = () => {
    // Simulate compression by removing whitespace
    setMergedContent(mergedContent.replace(/\s+/g, ' '))
    setIsCompressed(true)
  }

  const clearAll = () => {
