// Utility functions for the optimization tool

export function mergeFiles(files: File[]): Promise<string> {
  return new Promise((resolve) => {
    const readerPromises = Array.from(files).map(file => {
      return new Promise<string>((resolveReader) => {
        const reader = new FileReader()
        reader.onload = (e) => resolveReader(e.target?.result as string)
        reader.readAsText(file)
      })
    })

    Promise.all(readerPromises).then(contents => {
      const merged = contents.map((content, i) => 
        `/* ${files[i].name} */\n${content}\n`
      ).join('\n')
      resolve(merged)
    })
  })
}

export function compressCss(content: string): string {
  // Remove comments
  let compressed = content.replace(/\/\*[\s\S]*?\*\//g, '')
  // Remove whitespace
  compressed = compressed.replace(/\s+/g, ' ')
  // Remove unnecessary semicolons
  compressed = compressed.replace(/;\s*}/g, '}')
  return compressed.trim()
}

export function compressJs(content: string): string {
  // Simple minification (in a real app, use a proper minifier)
  let compressed = content
    .replace(/\/\/.*$/gm, '') // Remove single-line comments
    .replace(/\/\*[\s\S]*?\*\//g, '') // Remove multi-line comments
    .replace(/\s+/g, ' ') // Collapse whitespace
    .replace(/\s?([\{\}()\[\];,=\+\-\*\/%])\s?/g, '$1') // Remove spaces around operators
    .trim()
  return compressed
}

export function generateCacheKey(content: string): string {
  // Simple hash for cache key (in a real app, use a proper hashing algorithm)
  let hash = 0
  for (let i = 0; i < content.length; i++) {
    hash = ((hash << 5) - hash) + content.charCodeAt(i)
    hash |= 0 // Convert to 32bit integer
  }
  return 'cache_' + Math.abs(hash).toString(16)
}
