<script setup lang="ts">
import { ref } from 'vue'
import InventoryList from './InventoryList.vue'
import TransactionForm from './TransactionForm.vue'
import InventoryQuery from './InventoryQuery.vue'

defineProps<{
  username: string
}>()

const emit = defineEmits(['logout'])

const activeTab = ref('inventory')
const inventory = ref([
  { id: 1, name: 'Frozen Fish', quantity: 100, temperature: '-18°C' },
  { id: 2, name: 'Ice Cream', quantity: 50, temperature: '-25°C' },
  { id: 3, name: 'Vaccines', quantity: 30, temperature: '2-8°C' },
  { id: 4, name: 'Fresh Produce', quantity: 80, temperature: '4°C' }
])

const transactions = ref<Array<{
  id: number
  type: string
  itemId: number
  itemName: string
  quantity: number
  date: string
}>>([])

const handleTransaction = (type: string, itemId: number, quantity: number) => {
  const item = inventory.value.find(i => i.id === itemId)
  if (!item) return

  if (type === 'out') {
    if (item.quantity < quantity) {
      alert('Not enough stock!')
      return
    }
    item.quantity -= quantity
  } else {
    item.quantity += quantity
  }

  transactions.value.push({
    id: Date.now(),
    type,
    itemId,
    itemName: item.name,
    quantity,
    date: new Date().toLocaleString()
  })
}
</script>

