import { ref, computed } from 'vue'

interface DatabaseItem {
  value: any
  expiresAt: number | null
  type: string
}

export const useDatabase = (username: string) => {
  const structures = ref(['string', 'hash', 'list', 'set', 'sorted set'])
  const currentStructure = ref('string')
  const keys = ref<Record<string, DatabaseItem>>({})
  const selectedKey = ref('')
  const keyValue = ref('')
  const ttl = ref(0)
  const searchTerm = ref('')
  const newKey = ref('')

  // Initialize with some sample data
  if (Object.keys(keys.value).length === 0) {
    keys.value = {
      'user:1': { value: JSON.stringify({ name: 'John Doe', email: 'john@example.com' }), expiresAt: null, type: 'hash' },
      'session:abc123': { value: 'active', expiresAt: Date.now() + 3600000, type: 'string' },
      'tasks:incomplete': { value: JSON.stringify(['task1', 'task2', 'task3']), expiresAt: null, type: 'list' },
      'tags:article': { value: JSON.stringify(['tech', 'programming', 'web']), expiresAt: null, type: 'set' },
      'leaderboard': { value: JSON.stringify([{name: 'Alice', score: 100}, {name: 'Bob', score: 85}]), expiresAt: null, type: 'sorted set' }
    }
  }

  const filteredKeys = computed(() => {
    return Object.keys(keys.value)
      .filter(key => key.includes(searchTerm.value))
      .filter(key => keys.value[key].type === currentStructure.value)
  })

  const changeStructure = () => {
    selectedKey.value = ''
    keyValue.value = ''
  }

  const addKey = () => {
    if (newKey.value.trim() && !keys.value[newKey.value]) {
      keys.value[newKey.value] = { 
        value: '', 
        expiresAt: null, 
        type: currentStructure.value 
      }
      selectedKey.value = newKey.value
      keyValue.value = ''
      newKey.value = ''
    }
  }

  const getValue = (key: string) => {
    selectedKey.value = key
    const item = keys.value[key]
    keyValue.value = typeof item.value === 'string' ? item.value : JSON.stringify(item.value, null, 2)
    ttl.value = item.expiresAt ? Math.floor((item.expiresAt - Date.now()) / 1000) : 0
  }

  const setValue = () => {
    if (selectedKey.value) {
      try {
        keys.value[selectedKey.value].value = JSON.parse(keyValue.value)
      } catch {
        keys.value[selectedKey.value].value = keyValue.value
      }
    }
  }

  const deleteKey = () => {
    if (selectedKey.value) {
      delete keys.value[selectedKey.value]
      selectedKey.value = ''
      keyValue.value = ''
    }
  }

  const setTTL = () => {
    if (selectedKey.value) {
      keys.value[selectedKey.value].expiresAt = ttl.value > 0 ? Date.now() + (ttl.value * 1000) : null
    }
  }

  // Garbage collection simulation
  setInterval(() => {
    const now = Date.now()
    for (const key in keys.value) {
      if (keys.value[key].expiresAt && keys.value[key].expiresAt <= now) {
        delete keys.value[key]
        if (selectedKey.value === key) {
          selectedKey.value = ''
          keyValue.value = ''
        }
      }
    }
  }, 60000) // Run every minute

  return {
    currentStructure,
    structures,
    keys,
    selectedKey,
    keyValue,
    ttl,
    searchTerm,
    newKey,
    filteredKeys,
    changeStructure,
    addKey,
    getValue,
    setValue,
    deleteKey,
    setTTL
  }
}
