      'De-registration certificate'
    ]
  }
])

const newProcess = ref<Omit<Process, 'id'>>({
  name: '',
  description: '',
  steps: [],
  requiredDocuments: []
})

const newStep = ref('')
const newDocument = ref('')

const addProcess = () => {
  processes.value.push({
    id: processes.value.length + 1,
    ...newProcess.value
  })
  newProcess.value = { name: '', description: '', steps: [], requiredDocuments: [] }
}

const addStep = () => {
  if (newStep.value.trim()) {
    newProcess.value.steps.push(newStep.value)
    newStep.value = ''
  }
}

const addDocument = () => {
  if (newDocument.value.trim()) {
    newProcess.value.requiredDocuments.push(newDocument.value)
    newDocument.value = ''
  }
}
</script>

