<script setup lang="ts">
import { ref, watch } from 'vue'

const props = defineProps<{
  currentChat: string | null
  username: string
}>()

const messages = ref<Array<{
  id: string
  sender: string
  content: string
  timestamp: Date
  type: 'text' | 'image' | 'video'
}>>([])

const newMessage = ref('')

const sendMessage = () => {
  if (newMessage.value.trim() && props.currentChat) {
    messages.value.push({
      id: Date.now().toString(),
      sender: props.username,
      content: newMessage.value.trim(),
      timestamp: new Date(),
      type: 'text'
    })
    newMessage.value = ''
  }
}

watch(() => props.currentChat, () => {
  // Simulate loading messages for the chat
  messages.value = []
  if (props.currentChat) {
    // Add some sample messages
    messages.value.push({
      id: '1',
      sender: 'System',
      content: `Welcome to ${props.currentChat} chat!`,
      timestamp: new Date(Date.now() - 3600000),
      type: 'text'
    })
    messages.value.push({
      id: '2',
      sender: props.currentChat === 'general' ? 'John' : 'Jane',
      content: 'Hello everyone! How are you doing today?',
      timestamp: new Date(Date.now() - 1800000),
      type: 'text'
    })
  }
}, { immediate: true })
</script>

