<script setup lang="ts">
import { ref } from 'vue'

const orders = ref([
  { id: 1001, status: 'in-transit', origin: 'Shenzhen', destination: 'Shanghai', estimatedDelivery: '2023-12-15' },
  { id: 1002, status: 'delivered', origin: 'Beijing', destination: 'Guangzhou', estimatedDelivery: '2023-12-10' }
])

