})

const modules = ref([
  { name: 'Authentication', enabled: true, version: '1.2.0' },
  { name: 'Database', enabled: true, version: '2.1.3' },
  { name: 'API', enabled: false, version: '1.0.0' }
])

const logs = ref([
  { id: 1, level: 'INFO', message: 'Framework initialized', timestamp: '2023-11-15 10:30:22' },
  { id: 2, level: 'WARNING', message: 'Cache directory not writable', timestamp: '2023-11-15 10:30:25' },
  { id: 3, level: 'ERROR', message: 'Database connection failed', timestamp: '2023-11-15 10:30:30' }
])

const activeTab = ref('config')
const newModuleName = ref('')

const toggleModule = (index: number) => {
  modules.value[index].enabled = !modules.value[index].enabled
}

const addModule = () => {
  if (newModuleName.value.trim()) {
    modules.value.push({
      name: newModuleName.value.trim(),
      enabled: true,
      version: '1.0.0'
    })
    newModuleName.value = ''
  }
}
