    anime.id !== selectedAnime.value.id && 
    (filterGenre.value === 'all' || anime.genres.includes(filterGenre.value))
  )
})

const submitReview = () => {
  const review: Review = {
    id: Date.now(),
    username: newReview.value.username,
    rating: newReview.value.rating,
    content: newReview.value.content,
    date: new Date().toISOString().split('T')[0]
  }

  selectedAnime.value.reviews.push(review)
  newReview.value = { username: '', rating: 0, content: '' }

  // Update anime rating
  const totalRating = selectedAnime.value.reviews.reduce((sum, review) => sum + review.rating, 0)
  selectedAnime.value.rating = parseFloat((totalRating / selectedAnime.value.reviews.length).toFixed(1))
}

const selectAnime = (anime: Anime) => {
  selectedAnime.value = anime
}
</script>

