<script setup lang="ts">
import { ref, onMounted } from 'vue'
import ReminderList from './components/ReminderList.vue'
import AddReminder from './components/AddReminder.vue'

type Reminder = {
  id: string
  title: string
  type: 'birthday' | 'anniversary' | 'holiday' | 'event' | 'weather'
  date: string
  time: string
  notes: string
  notified: boolean
}

const reminders = ref<Reminder[]>([])
const showAddForm = ref(false)

// Load reminders from localStorage
onMounted(() => {
  const saved = localStorage.getItem('reminders')
  if (saved) {
    reminders.value = JSON.parse(saved)
    checkReminders()
  }
})

// Check for due reminders
function checkReminders() {
  const now = new Date()
  reminders.value.forEach(reminder => {
    const reminderDate = new Date(`${reminder.date}T${reminder.time}`)
    if (reminderDate <= now && !reminder.notified) {
      showNotification(reminder)
      reminder.notified = true
      saveReminders()
    }
  })
}

function showNotification(reminder: Reminder) {
  if ('Notification' in window && Notification.permission === 'granted') {
    new Notification(`Reminder: ${reminder.title}`, {
      body: reminder.notes || 'Time for your reminder!',
      icon: '/vite.svg'
    })
  }
}

function requestNotificationPermission() {
  if ('Notification' in window) {
    Notification.requestPermission()
  }
}

function saveReminders() {
  localStorage.setItem('reminders', JSON.stringify(reminders.value))
}

function addReminder(newReminder: Omit<Reminder, 'id' | 'notified'>) {
  reminders.value.push({
    ...newReminder,
    id: Date.now().toString(),
    notified: false
  })
  saveReminders()
  showAddForm.value = false
}

function deleteReminder(id: string) {
  reminders.value = reminders.value.filter(r => r.id !== id)
  saveReminders()
}
</script>

