<script setup lang="ts">
import { ref } from 'vue'

const formTitle = ref('')
const formFields = ref([{ id: 1, type: 'text', label: '', required: false }])
const formData = ref({})

const addField = () => {
  formFields.value.push({
    id: Date.now(),
    type: 'text',
    label: '',
    required: false
  })
}

const removeField = (id: number) => {
  formFields.value = formFields.value.filter(field => field.id !== id)
}

const generateDocument = () => {
  // In a real app, this would generate a PDF or Word doc
  const docContent = `
    Document generated from form: ${formTitle.value}
    Fields:
    ${Object.entries(formData.value).map(([key, val]) => `${key}: ${val}`).join('\n')}
  `
  return docContent
}

const downloadDocument = () => {
  const content = generateDocument()
  const blob = new Blob([content], { type: 'text/plain' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `${formTitle.value || 'document'}.txt`
  a.click()
  URL.revokeObjectURL(url)
}
</script>

