<script setup lang="ts">
import { ref } from 'vue'

const canvasRef = ref<HTMLCanvasElement | null>(null)
const selectedTool = ref('rectangle')
const color = ref('#4682B4')
const isDrawing = ref(false)
const startPos = ref({ x: 0, y: 0 })
const shapes = ref<Array<{
  type: string
  x: number
  y: number
  width: number
  height: number
  color: string
}>>([])

const startDrawing = (e: MouseEvent) => {
  if (!canvasRef.value) return

  isDrawing.value = true
  const rect = canvasRef.value.getBoundingClientRect()
  startPos.value = {
    x: e.clientX - rect.left,
    y: e.clientY - rect.top
  }
}

const draw = (e: MouseEvent) => {
  if (!isDrawing.value || !canvasRef.value) return

  const ctx = canvasRef.value.getContext('2d')
  if (!ctx) return

  const rect = canvasRef.value.getBoundingClientRect()
  const currentX = e.clientX - rect.left
  const currentY = e.clientY - rect.top

  // Clear canvas
  ctx.clearRect(0, 0, canvasRef.value.width, canvasRef.value.height)

  // Redraw all shapes
  shapes.value.forEach(shape => {
    ctx.fillStyle = shape.color
    if (shape.type === 'rectangle') {
      ctx.fillRect(shape.x, shape.y, shape.width, shape.height)
    } else if (shape.type === 'circle') {
      ctx.beginPath()
      ctx.arc(
        shape.x + shape.width / 2,
        shape.y + shape.height / 2,
        Math.max(shape.width, shape.height) / 2,
        0,
        Math.PI * 2
      )
      ctx.fill()
    }
  })

  // Draw current shape
  ctx.fillStyle = color.value
  const width = currentX - startPos.value.x
  const height = currentY - startPos.value.y

  if (selectedTool.value === 'rectangle') {
    ctx.fillRect(startPos.value.x, startPos.value.y, width, height)
  } else if (selectedTool.value === 'circle') {
    ctx.beginPath()
    ctx.arc(
      startPos.value.x + width / 2,
      startPos.value.y + height / 2,
      Math.max(Math.abs(width), Math.abs(height)) / 2,
      0,
      Math.PI * 2
    )
    ctx.fill()
  }
}

const endDrawing = (e: MouseEvent) => {
  if (!isDrawing.value || !canvasRef.value) return

  const rect = canvasRef.value.getBoundingClientRect()
  const currentX = e.clientX - rect.left
  const currentY = e.clientY - rect.top

  shapes.value.push({
    type: selectedTool.value,
    x: startPos.value.x,
    y: startPos.value.y,
    width: currentX - startPos.value.x,
    height: currentY - startPos.value.y,
    color: color.value
  })

  isDrawing.value = false
}

const clearCanvas = () => {
  if (!canvasRef.value) return

  const ctx = canvasRef.value.getContext('2d')
  if (!ctx) return

  ctx.clearRect(0, 0, canvasRef.value.width, canvasRef.value.height)
  shapes.value = []
}

const downloadCanvas = () => {
  if (!canvasRef.value) return

  const dataURL = canvasRef.value.toDataURL('image/png')
  const link = document.createElement('a')
  link.download = 'design.png'
  link.href = dataURL
  link.click()
}
</script>

<template>
  <div class="design-container">
    <h1>Graphic Design</h1>

    <div class="design-toolbar">
      <div class="tool-options">
        <label>
          <input
            type="radio"
            v-model="selectedTool"
            value="rectangle"
            checked
          />
          Rectangle
        </label>
        <label>
          <input
            type="radio"
            v-model="selectedTool"
            value="circle"
          />
          Circle
        </label>
      </div>

      <div class="color-picker">
        <label>Color:</label>
        <input type="color" v-model="color" />
      </div>

      <div class="action-buttons">
        <button @click="clearCanvas" class="clear-btn">Clear</button>
        <button @click="downloadCanvas" class="download-btn">Download</button>
      </div>
    </div>

    <div class="canvas-container">
      <canvas
        ref="canvasRef"
        width="800"
        height="500"
        @mousedown="startDrawing"
        @mousemove="draw"
        @mouseup="endDrawing"
        @mouseleave="endDrawing"
      ></canvas>
    </div>
  </div>
</template>

