<script setup lang="ts">
import { ref, computed } from 'vue'

const rows = ref(20)
const cols = ref(10)
const activeCell = ref({ row: 0, col: 0 })
const spreadsheetData = ref(
  Array(rows.value).fill().map(() => 
    Array(cols.value).fill('')
  )
)

const handleCellClick = (row: number, col: number) => {
  activeCell.value = { row, col }
}

const handleCellChange = (value: string, row: number, col: number) => {
  spreadsheetData.value[row][col] = value
}

const exportCSV = () => {
  const csvContent = spreadsheetData.value
    .map(row => row.join(','))
    .join('\n')

  const blob = new Blob([csvContent], { type: 'text/csv' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = 'spreadsheet.csv'
  link.click()
}

const exportJSON = () => {
  const jsonContent = JSON.stringify(spreadsheetData.value)
  const blob = new Blob([jsonContent], { type: 'application/json' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = 'spreadsheet.json'
  link.click()
}

const saveSpreadsheet = () => {
  localStorage.setItem('currentSpreadsheet', JSON.stringify(spreadsheetData.value))
  alert('Spreadsheet saved!')
}

const loadSpreadsheet = () => {
  const savedData = localStorage.getItem('currentSpreadsheet')
  if (savedData) {
    spreadsheetData.value = JSON.parse(savedData)
  }
}
</script>

<template>
  <div class="spreadsheet-container">
