<script setup lang="ts">
import { ref, computed } from 'vue'
import NoteList from './components/NoteList.vue'
import NoteEditor from './components/NoteEditor.vue'
import FolderNav from './components/FolderNav.vue'
import SearchBar from './components/SearchBar.vue'

interface Note {
  id: string
  title: string
  content: string
  folderId: string
  createdAt: Date
  updatedAt: Date
}

interface Folder {
  id: string
  name: string
}

const notes = ref<Note[]>([])
const folders = ref<Folder[]>([{ id: 'default', name: 'Default' }])
const currentFolderId = ref('default')
const currentNoteId = ref<string | null>(null)
const searchQuery = ref('')

const currentNotes = computed(() => {
  return notes.value
    .filter(note => note.folderId === currentFolderId.value)
    .filter(note => 
      note.title.toLowerCase().includes(searchQuery.value.toLowerCase()) ||
      note.content.toLowerCase().includes(searchQuery.value.toLowerCase())
    )
})

function createNote() {
  const newNote: Note = {
    id: Date.now().toString(),
    title: 'New Note',
    content: '',
    folderId: currentFolderId.value,
    createdAt: new Date(),
    updatedAt: new Date()
  }
  notes.value.push(newNote)
  currentNoteId.value = newNote.id
}

function updateNote(updatedNote: Note) {
  const index = notes.value.findIndex(n => n.id === updatedNote.id)
  if (index !== -1) {
    notes.value[index] = {
      ...updatedNote,
      updatedAt: new Date()
    }
  }
}

function deleteNote(id: string) {
  notes.value = notes.value.filter(note => note.id !== id)
  if (currentNoteId.value === id) {
    currentNoteId.value = null
  }
}

function createFolder(name: string) {
  const newFolder: Folder = {
    id: Date.now().toString(),
    name
  }
  folders.value.push(newFolder)
}

function updateFolder(updatedFolder: Folder) {
  const index = folders.value.findIndex(f => f.id === updatedFolder.id)
  if (index !== -1) {
    folders.value[index] = updatedFolder
  }
}

function deleteFolder(id: string) {
  if (id === 'default') return

  // Move notes to default folder
  notes.value = notes.value.map(note => 
    note.folderId === id ? { ...note, folderId: 'default' } : note
  )

  folders.value = folders.value.filter(folder => folder.id !== id)
  if (currentFolderId.value === id) {
    currentFolderId.value = 'default'
  }
}
</script>

<template>
  <div class="app-container">
    <div class="sidebar">
      <SearchBar v-model="searchQuery" />
      <FolderNav 
        :folders="folders"
        :currentFolderId="currentFolderId"
        @create-folder="createFolder"
        @update-folder="updateFolder"
        @delete-folder="deleteFolder"
        @select-folder="currentFolderId = $event"
      />
    </div>
    <div class="main-content">
      <NoteList 
        :notes="currentNotes"
        :currentNoteId="currentNoteId"
        @create-note="createNote"
        @select-note="currentNoteId = $event"
        @delete-note="deleteNote"
      />
      <NoteEditor 
