<script setup lang="ts">
import { ref, onMounted } from 'vue'

const props = defineProps(['initialContent'])
const emit = defineEmits(['save', 'share'])

const content = ref(props.initialContent || '')
const isListening = ref(false)
const recognition = ref(null)

const startSpeechRecognition = () => {
  if ('webkitSpeechRecognition' in window) {
    recognition.value = new webkitSpeechRecognition()
    recognition.value.continuous = true
    recognition.value.interimResults = true

    recognition.value.onresult = (event) => {
      let interimTranscript = ''
      let finalTranscript = ''

      for (let i = event.resultIndex; i < event.results.length; i++) {
        const transcript = event.results[i][0].transcript
        if (event.results[i].isFinal) {
          finalTranscript += transcript + ' '
        } else {
          interimTranscript += transcript
        }
      }

      content.value += finalTranscript
    }

    recognition.value.start()
    isListening.value = true
  } else {
    alert('Speech recognition not supported in this browser')
  }
}

const stopSpeechRecognition = () => {
  if (recognition.value) {
    recognition.value.stop()
    isListening.value = false
  }
}

const generateText = () => {
  // In a real app, this would call an API
  content.value += "\n\nGenerated text: Lorem ipsum dolor sit amet, consectetur adipiscing elit."
}

const handleSave = () => {
  emit('save', content.value)
}

const handleShare = () => {
  emit('share', content.value)
}
</script>

<template>
  <div class="text-editor">
    <div class="editor-toolbar">
      <button @click="isListening ? stopSpeechRecognition() : startSpeechRecognition()">
        {{ isListening ? 'Stop Listening' : 'Start Speech Input' }}
      </button>
      <button @click="generateText">Generate Text</button>
      <button @click="handleSave">Save</button>
      <button @click="handleShare">Share</button>
    </div>

    <textarea v-model="content" class="editor-textarea"></textarea>
  </div>
</template>

