<boltAction type="file" filePath="src/App.vue">
<script setup lang="ts">
import { ref } from 'vue'

const formData = ref({
  fields: [
    { type: 'text', name: 'username', label: 'Username', value: '' },
    { type: 'email', name: 'email', label: 'Email', value: '' },
    { type: 'checkbox', name: 'subscribe', label: 'Subscribe', checked: false },
    { type: 'select', name: 'country', label: 'Country', options: ['USA', 'Canada', 'UK'], value: '' }
  ]
})

const jsonOutput = ref('')
const showOutput = ref(false)

const addField = (type: string) => {
  const fieldName = `field_${Date.now()}`
  const newField = {
    type,
    name: fieldName,
    label: fieldName.replace('_', ' '),
    value: '',
    ...(type === 'checkbox' ? { checked: false } : {}),
    ...(type === 'select' ? { options: ['Option 1', 'Option 2'] } : {})
  }
  formData.value.fields.push(newField)
}

const removeField = (index: number) => {
  formData.value.fields.splice(index, 1)
}

const convertToJson = () => {
  const result: Record<string, any> = {}
  formData.value.fields.forEach(field => {
    if (field.type === 'checkbox') {
      result[field.name] = field.checked
    } else {
      result[field.name] = field.value
    }
  })
  jsonOutput.value = JSON.stringify(result, null, 2)
  showOutput.value = true
}
</script>

<template>
  <div class="app-container">
    <h1>HTML Form to JSON Converter</h1>

    <div class="form-builder">
      <div class="form-controls">
        <h2>Add Fields</h2>
        <div class="field-buttons">
          <button @click="addField('text')">Add Text</button>
          <button @click="addField('email')">Add Email</button>
          <button @click="addField('checkbox')">Add Checkbox</button>
          <button @click="addField('select')">Add Dropdown</button>
        </div>
      </div>

      <div class="form-preview">
        <h2>Form Preview</h2>
        <form @submit.prevent="convertToJson">
          <div v-for="(field, index) in formData.fields" :key="index" class="form-field">
            <label v-if="field.type !== 'checkbox'">{{ field.label }}:</label>

            <input 
              v-if="['text', 'email'].includes(field.type)"
              v-model="field.value"
              :type="field.type"
              :name="field.name"
              :placeholder="field.label"
            />

            <input
              v-if="field.type === 'checkbox'"
              v-model="field.checked"
              type="checkbox"
              :name="field.name"
            />
            <label v-if="field.type === 'checkbox'">{{ field.label }}</label>

            <select 
              v-if="field.type === 'select'"
              v-model="field.value"
              :name="field.name"
            >
              <option value="" disabled>Select an option</option>
              <option v-for="(option, i) in field.options" :key="i" :value="option">
                {{ option }}
              </option>
            </select>

            <button type="button" @click="removeField(index)" class="remove-btn">×</button>
          </div>

          <button type="submit" class="convert-btn">Convert to JSON</button>
        </form>
      </div>

      <div v-if="showOutput" class="json-output">
        <h2>JSON Output</h2>
        <pre>{{ jsonOutput }}</pre>
      </div>
    </div>
  </div>
</template>

