<script setup lang="ts">
import { ref } from 'vue'
import * as pdfjsLib from 'pdfjs-dist'

const emit = defineEmits(['text-extracted'])
const isLoading = ref(false)
const error = ref('')

const handleFileUpload = async (event: Event) => {
  const input = event.target as HTMLInputElement
  if (!input.files?.length) return

  const file = input.files[0]
  if (file.type !== 'application/pdf') {
    error.value = 'Please upload a PDF file'
    return
  }

  isLoading.value = true
  error.value = ''

  try {
    const arrayBuffer = await file.arrayBuffer()
    const pdf = await pdfjsLib.getDocument(arrayBuffer).promise
    let fullText = ''

    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i)
      const textContent = await page.getTextContent()
      const textItems = textContent.items.map((item: any) => item.str)
      fullText += textItems.join(' ') + '\n\n'
    }

    emit('text-extracted', fullText)
  } catch (err) {
    error.value = 'Failed to extract text from PDF'
    console.error(err)
  } finally {
    isLoading.value = false
  }
}
</script>

<template>
  <div class="pdf-upload">
    <div class="upload-area">
      <input 
        type="file" 
        id="pdf-upload" 
        accept="application/pdf"
        @change="handleFileUpload"
        hidden
      />
      <label for="pdf-upload" class="upload-button">
        <span v-if="!isLoading">Choose PDF File</span>
        <span v-else>Processing...</span>
      </label>
      <p class="hint">or drag and drop PDF here</p>
    </div>

    <div v-if="error" class="error-message">
      {{ error }}
    </div>
  </div>
</template>

