<script setup lang="ts">
import { ref, computed } from 'vue'

const inputText = ref('')
const conversionType = ref('emojiToText')
const emojiMap = {
  ':)': '😊',
  ':D': '😃',
  ':(': '😞',
  ';)': '😉',
  ':P': '😛',
  ':*': '😘',
  ':|': '😐',
  ':\'(': '😢',
  '>:(': '😠',
  '<3': '❤️',
  '</3': '💔',
  ':*': '😗',
  ':-*': '😘',
  ':-)': '😊',
  ':-D': '😃',
  ':-(': '😞',
  ';-)': '😉',
  ':-P': '😛',
  ':-|': '😐',
  ':\'-(': '😢',
  '>:-(': '😠'
}

const textToEmojiMap = Object.fromEntries(
  Object.entries(emojiMap).map(([key, value]) => [value, key])
)

const convertedText = computed(() => {
  if (!inputText.value) return ''

  if (conversionType.value === 'emojiToText') {
    return Object.entries(textToEmojiMap).reduce(
      (text, [emoji, symbol]) => text.replaceAll(emoji, symbol),
      inputText.value
    )
  } else {
    return Object.entries(emojiMap).reduce(
      (text, [symbol, emoji]) => text.replaceAll(symbol, emoji),
      inputText.value
    )
  }
})

function copyToClipboard() {
  navigator.clipboard.writeText(convertedText.value)
}
