<script setup lang="ts">
import { ref, computed } from 'vue'
import DataTable from './DataTable.vue'

const data = ref<number[]>([])
const inputValue = ref('')
const error = ref('')

const isValidNumber = (value: string): boolean => {
  return !isNaN(Number(value)) && value.trim() !== ''
}

const addNumber = () => {
  if (isValidNumber(inputValue.value)) {
    data.value.push(Number(inputValue.value))
    inputValue.value = ''
    error.value = ''
  } else {
    error.value = 'Please enter a valid number'
  }
}

const handleFileUpload = (event: Event) => {
  const input = event.target as HTMLInputElement
  if (input.files?.length) {
    const file = input.files[0]
    const reader = new FileReader()
    reader.onload = (e) => {
      const content = e.target?.result as string
      const numbers = content.split(/[\n,]/).filter(n => n.trim() !== '')
      numbers.forEach(n => {
        if (isValidNumber(n)) {
          data.value.push(Number(n))
        }
      })
    }
    reader.readAsText(file)
  }
}

const exportData = (format: 'csv' | 'json') => {
  if (format === 'csv') {
    const csvContent = 'data:text/csv;charset=utf-8,' + data.value.join(',')
    const encodedUri = encodeURI(csvContent)
    const link = document.createElement('a')
    link.setAttribute('href', encodedUri)
    link.setAttribute('download', 'data.csv')
    document.body.appendChild(link)
    link.click()
  } else {
    const jsonContent = 'data:text/json;charset=utf-8,' + JSON.stringify(data.value)
    const encodedUri = encodeURI(jsonContent)
    const link = document.createElement('a')
    link.setAttribute('href', encodedUri)
    link.setAttribute('download', 'data.json')
    document.body.appendChild(link)
    link.click()
  }
}
</script>

