<script setup lang="ts">
import { ref } from 'vue'

const textInput = ref('')
const codeInput = ref('')

function textToCode(text: string): string {
  if (!text) return ''

  let code = 0
  for (let i = 0; i < text.length; i++) {
    code = (code * 31 + text.charCodeAt(i)) % 1000000
  }
  return code.toString().padStart(6, '0')
}

function codeToText(code: string): string {
  if (!code || code.length !== 6 || !/^\d+$/.test(code)) return ''

  const num = parseInt(code)
  let text = ''
  let remaining = num

  while (remaining > 0) {
    const charCode = remaining % 31
    text = String.fromCharCode(charCode + 64) + text
    remaining = Math.floor(remaining / 31)
  }

  return text || 'A' // Default to 'A' if empty
}
</script>

<template>
