        <img :src="previewUrl" alt="Preview" />
      </div>
      <div v-else class="upload-prompt">
        <p>Select an image file to extract text</p>
      </div>
    </div>

    <button 
      @click="extractText" 
      :disabled="!imageFile || isLoading"
      class="extract-btn"
    >
