import { useState, useEffect } from 'react'
import { Save } from 'lucide-react'

interface CodeEditorProps {
  code: string
  setCode: (code: string) => void
  isLoggedIn: boolean
}

export default function CodeEditor({ code, setCode, isLoggedIn }: CodeEditorProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [localCode, setLocalCode] = useState(code)

  useEffect(() => {
    setLocalCode(code)
  }, [code])

  const handleSave = () => {
    setCode(localCode)
    setIsEditing(false)
  }

  return (
    <div>
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-lg font-semibold">Code Editor</h2>
        {isLoggedIn && (
          <div className="flex space-x-2">
            {isEditing ? (
              <button
                onClick={handleSave}
                className="flex items-center space-x-1 bg-mediumblue text-white px-3 py-1 rounded hover:bg-blue-700"
              >
                <Save size={16} />
                <span>Save</span>
              </button>
            ) : (
              <button
                onClick={() => setIsEditing(true)}
                className="flex items-center space-x-1 bg-mediumblue text-white px-3 py-1 rounded hover:bg-blue-700"
              >
                <span>Edit</span>
              </button>
            )}
          </div>
        )}
      </div>
      <textarea
        value={localCode}
        onChange={(e) => setLocalCode(e.target.value)}
        readOnly={!isEditing}
        className={`w-full h-96 p-3 font-mono text-sm rounded border ${
          isEditing ? 'border-blue-500 bg-gray-50' : 'border-gray-300 bg-gray-100'
        }`}
      />
    </div>
  )
}
