import { useState } from 'react'
import { Plus } from 'lucide-react'

interface TemplateSelectorProps {
  selectedTemplate: string
  setSelectedTemplate: (template: string) => void
  setGeneratedCode: (code: string) => void
  customCollections: any[]
}

const templates = [
  {
    id: 'react-component',
    name: 'React Component',
    code: `import React from 'react'

function MyComponent() {
  return (
    <div>
      <h1>Hello World</h1>
    </div>
  )
}

export default MyComponent
`
  },
  {
    id: 'express-route',
    name: 'Express Route',
    code: `const express = require('express')
const router = express.Router()

router.get('/', (req, res) => {
  res.send('Hello World')
})

module.exports = router
`
  },
  {
    id: 'python-function',
    name: 'Python Function',
    code: `def calculate_average(numbers):
    """Calculate the average of a list of numbers"""
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)
`
  }
]

export default function TemplateSelector({
  selectedTemplate,
  setSelectedTemplate,
  setGeneratedCode,
  customCollections
}: TemplateSelectorProps) {
  const [showNewCollection, setShowNewCollection] = useState(false)
  const [newCollectionName, setNewCollectionName] = useState('')

  const handleTemplateSelect = (templateId: string) => {
    const template = templates.find(t => t.id === templateId)
    if (template) {
      setSelectedTemplate(templateId)
      setGeneratedCode(template.code)
    }
  }

  const handleAddCollection = () => {
    if (newCollectionName.trim()) {
      // In a real app, you would save this to a database
      setShowNewCollection(false)
      setNewCollectionName('')
    }
  }

  return (
    <div>
      <h2 className="text-lg font-semibold mb-4">Templates</h2>

      <div className="space-y-2 mb-6">
        {templates.map(template => (
          <div 
            key={template.id}
            onClick={() => handleTemplateSelect(template.id)}
            className={`p-3 rounded cursor-pointer ${
              selectedTemplate === template.id 
                ? 'bg-mediumblue text-white' 
                : 'bg-gray-100 hover:bg-gray-200'
            }`}
          >
            {template.name}
          </div>
        ))}
      </div>

      <div className="mb-6">
        <div className="flex justify-between items-center mb-2">
          <h3 className="font-medium">Custom Collections</h3>
          <button 
            onClick={() => setShowNewCollection(true)}
            className="text-mediumblue hover:text-blue-700"
          >
            <Plus size={16} />
          </button>
        </div>

        {showNewCollection && (
          <div className="mb-4 p-3 bg-gray-100 rounded">
            <input
              type="text"
              value={newCollectionName}
              onChange={(e) => setNewCollectionName(e.target.value)}
              placeholder="Collection name"
              className="w-full p-2 mb-2 border rounded"
            />
            <div className="flex space-x-2">
              <button
                onClick={handleAddCollection}
                className="bg-mediumblue text-white px-3 py-1 rounded hover:bg-blue-700"
              >
                Add
              </button>
              <button
                onClick={() => setShowNewCollection(false)}
                className="bg-gray-300 px-3 py-1 rounded hover:bg-gray-400"
              >
                Cancel
              </button>
            </div>
          </div>
        )}

        {customCollections.length === 0 ? (
          <p className="text-sm text-gray-500">No collections yet</p>
        ) : (
          <div className="space-y-2">
            {customCollections.map(collection => (
              <div key={collection.id} className="p-2 bg-gray-100 rounded">
                {collection.name}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
