<script setup lang="ts">
import { ref, watch } from 'vue'

const props = defineProps<{
  file1: File | null
  file2: File | null
}>()

const emit = defineEmits(['update:file1', 'update:file2'])

const image1Url = ref<string>('')
const image2Url = ref<string>('')
const similarityScore = ref<number | null>(null)

const handleFileChange = (event: Event, type: 'file1' | 'file2') => {
  const input = event.target as HTMLInputElement
  if (input.files && input.files[0]) {
    const file = input.files[0]
    emit(`update:${type}`, file)

    const reader = new FileReader()
    reader.onload = (e) => {
      if (type === 'file1') {
        image1Url.value = e.target?.result as string
      } else {
        image2Url.value = e.target?.result as string
      }
    }
    reader.readAsDataURL(file)
  }
}

const compareImages = () => {
  if (!image1Url.value || !image2Url.value) return

  // Simple comparison logic (can be enhanced)
  const img1 = document.createElement('img')
  const img2 = document.createElement('img')

  img1.onload = img2.onload = () => {
    const canvas = document.createElement('canvas')
    const ctx = canvas.getContext('2d')!

    canvas.width = Math.max(img1.width, img2.width)
    canvas.height = Math.max(img1.height, img2.height)

    // Draw first image
    ctx.drawImage(img1, 0, 0)
    const data1 = ctx.getImageData(0, 0, img1.width, img1.height).data

    // Draw second image
    ctx.clearRect(0, 0, canvas.width, canvas.height)
    ctx.drawImage(img2, 0, 0)
    const data2 = ctx.getImageData(0, 0, img2.width, img2.height).data

    // Calculate similarity
    let diff = 0
    for (let i = 0; i < data1.length; i += 4) {
      diff += Math.abs(data1[i] - data2[i]) / 255
      diff += Math.abs(data1[i+1] - data2[i+1]) / 255
      diff += Math.abs(data1[i+2] - data2[i+2]) / 255
    }

    similarityScore.value = 100 - (diff / (data1.length / 4 * 3)) * 100
  }

  img1.src = image1Url.value
  img2.src = image2Url.value
}

watch([image1Url, image2Url], () => {
  if (image1Url.value && image2Url.value) {
    compareImages()
  }
})
</script>

<template>
  <div class="comparison-container">
    <div class="file-selectors">
      <div class="file-selector">
        <label>Reference JPEG:</label>
        <input 
          type="file" 
          accept="image/jpeg" 
          @change="(e) => handleFileChange(e, 'file1')"
        />
      </div>

      <div class="file-selector">
        <label>Hand-drawn Image:</label>
        <input 
          type="file" 
          accept="image/*" 
          @change="(e) => handleFileChange(e, 'file2')"
        />
