<boltArtifact id="qr-code-generator" title="QR Code Generator from CSV">
<boltAction type="file" filePath="src/App.vue">
<script setup lang="ts">
import { ref } from 'vue'
import QRCode from 'qrcode'
import * as XLSX from 'xlsx'

const csvData = ref<string[][]>([])
const qrCodes = ref<string[]>([])
const fileName = ref('')
const activeTab = ref('csv')

const handleFileUpload = (event: Event) => {
  const input = event.target as HTMLInputElement
  if (!input.files?.length) return

  const file = input.files[0]
  fileName.value = file.name

  const reader = new FileReader()
  reader.onload = (e) => {
    const content = e.target?.result as string
    if (activeTab.value === 'csv') {
      processCSV(content)
    } else {
      processExcel(content)
    }
  }

  if (activeTab.value === 'csv') {
    reader.readAsText(file)
  } else {
    reader.readAsArrayBuffer(file)
  }
}

const processCSV = (content: string) => {
  const lines = content.split('\n')
  csvData.value = lines.map(line => line.split(','))
  generateQRCodes()
}

const processExcel = (content: ArrayBuffer) => {
  const workbook = XLSX.read(content, { type: 'array' })
  const firstSheet = workbook.Sheets[workbook.SheetNames[0]]
  const jsonData = XLSX.utils.sheet_to_json(firstSheet, { header: 1 })
  csvData.value = jsonData as string[][]
  generateQRCodes()
}

const generateQRCodes = async () => {
  qrCodes.value = []
  for (const row of csvData.value) {
    const text = row.join(',')
    try {
      const qrCode = await QRCode.toDataURL(text)
      qrCodes.value.push(qrCode)
    } catch (err) {
      console.error('Error generating QR code:', err)
    }
  }
}

const downloadAll = () => {
  qrCodes.value.forEach((qrCode, index) => {
    const link = document.createElement('a')
    link.href = qrCode
    link.download = `qr-code-${index}.png`
    link.click()
  })
}
</script>

<template>
  <div class="app-container">
    <h1>QR Code Generator</h1>

    <div class="tabs">
      <button 
        :class="{ active: activeTab === 'csv' }" 
        @click="activeTab = 'csv'"
      >
        CSV Upload
      </button>
      <button 
        :class="{ active: activeTab === 'excel' }" 
        @click="activeTab = 'excel'"
      >
        Excel Upload
      </button>
    </div>

    <div class="upload-section">
      <input 
        type="file" 
        :accept="activeTab === 'csv' ? '.csv' : '.xlsx,.xls'" 
        @change="handleFileUpload"
      />
      <p v-if="fileName">Loaded file: {{ fileName }}</p>
    </div>

    <div v-if="qrCodes.length" class="qr-display">
      <button @click="downloadAll" class="download-all">Download All QR Codes</button>
      <div class="qr-grid">
        <div v-for="(qrCode, index) in qrCodes" :key="index" class="qr-item">
          <img :src="qrCode" :alt="`QR Code ${index}`" />
          <p>Row {{ index + 1 }}</p>
          <a :href="qrCode" download :title="`Download QR Code ${index + 1}`">
            Download
          </a>
        </div>
      </div>
    </div>
  </div>
</template>

