<script setup lang="ts">
import { ref, computed } from 'vue'
import { saveAs } from 'file-saver'

interface Document {
  content: string
  images: string[]
  styles: {
    fontFamily: string
    fontSize: string
    lineHeight: string
  }
}

const doc = ref<Document>({
  content: '',
  images: [],
  styles: {
    fontFamily: 'Arial',
    fontSize: '16px',
    lineHeight: '1.5'
  }
})

const fontOptions = ['Arial', 'Times New Roman', 'Courier New', 'Verdana']
const fontSizeOptions = ['12px', '14px', '16px', '18px', '20px']
const lineHeightOptions = ['1.0', '1.2', '1.5', '2.0']

function handleImageUpload(e: Event) {
  const input = e.target as HTMLInputElement
  if (input.files?.length) {
    const reader = new FileReader()
    reader.onload = (event) => {
      const imageData = event.target?.result as string
      doc.value.images.push(imageData)
      doc.value.content += `<img src="${imageData}" style="max-width: 100%;"/>`
    }
    reader.readAsDataURL(input.files[0])
  }
}

function saveDocument() {
  const blob = new Blob([JSON.stringify(doc.value)], {type: 'application/json'})
  saveAs(blob, 'document.wp')
}

function loadDocument(e: Event) {
  const input = e.target as HTMLInputElement
  if (input.files?.length) {
    const reader = new FileReader()
    reader.onload = (event) => {
      const content = event.target?.result as string
      doc.value = JSON.parse(content)
    }
    reader.readAsText(input.files[0])
  }
}
</script>

