<script setup lang="ts">
import { ref, computed } from 'vue'

const text = ref('')
const encoding = ref('UTF-8')
const mode = ref('normal')
const customDict = ref('')
const segmentedText = computed(() => segmentChinese(text.value, mode.value))

function segmentChinese(text: string, mode: string): string {
  // Basic segmentation logic (can be enhanced)
  if (!text) return ''

  const dictWords = customDict.value.split(/[\n,]/).filter(Boolean)
  const result = []
  let i = 0

  while (i < text.length) {
    let found = false

    // Check custom dictionary first
    for (const word of dictWords) {
      if (text.startsWith(word, i)) {
        result.push(word)
        i += word.length
        found = true
        break
      }
    }

    if (!found) {
      // Default segmentation (character-based)
      result.push(text[i])
      i++
    }
  }

  return result.join(' | ')
}

