<boltAction type="file" filePath="src/components/ContentList.vue">
<script setup lang="ts">
defineProps<{
  items: Array<{
    id: number
    title: string
    body: string
  }>
  isLoading: boolean
  searchQuery: string
}>()

const filteredItems = (items, query) => {
  if (!query) return items
  return items.filter(item => 
    item.title.toLowerCase().includes(query.toLowerCase()) ||
    item.body.toLowerCase().includes(query.toLowerCase())
  )
}
</script>

<template>
  <div class="content-list">
    <div v-if="isLoading" class="loading">Loading content...</div>
    <div v-else class="grid">
      <article 
        v-for="item in filteredItems(items, searchQuery)" 
        :key="item.id"
        class="card"
      >
        <h3>{{ item.title }}</h3>
