import { FiSearch, FiFilter, FiChevronLeft, FiChevronRight } from 'react-icons/fi'

const App = () => {
  const [query, setQuery] = useState('')
  const [filters, setFilters] = useState({
    category: '',
    date: ''
  })
  const [currentPage, setCurrentPage] = useState(1)
  const [itemsPerPage] = useState(5)
  const [selectedItem, setSelectedItem] = useState(null)
  const [data, setData] = useState([])

  useEffect(() => {
    // Mock data - in a real app, this would come from an API
    const mockData = Array.from({ length: 20 }, (_, i) => ({
      id: i + 1,
      title: `Information Item ${i + 1}`,
      category: ['News', 'Event', 'Notice'][Math.floor(Math.random() * 3)],
      date: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      content: `This is detailed content for information item ${i + 1}. It contains all the relevant details that a user might need to know about this particular piece of information.`
    }))
    setData(mockData)
  }, [])

  const filteredData = data.filter(item => {
    const matchesQuery = item.title.toLowerCase().includes(query.toLowerCase()) || 
                         item.content.toLowerCase().includes(query.toLowerCase())
    const matchesCategory = !filters.category || item.category === filters.category
    const matchesDate = !filters.date || item.date === filters.date
    return matchesQuery && matchesCategory && matchesDate
  })

  const indexOfLastItem = currentPage * itemsPerPage
  const indexOfFirstItem = indexOfLastItem - itemsPerPage
  const currentItems = filteredData.slice(indexOfFirstItem, indexOfLastItem)
  const totalPages = Math.ceil(filteredData.length / itemsPerPage)

  const handleFilterChange = (e) => {
    const { name, value } = e.target
    setFilters(prev => ({ ...prev, [name]: value }))
    setCurrentPage(1)
  }

  const handleViewDetails = (item) => {
    setSelectedItem(item)
  }

  const handleBackToList = () => {
    setSelectedItem(null)
  }

  return (
    &lt;div className="app"&gt;
      {selectedItem ? (
        &lt;div className="detail-view" style={{ backgroundColor: 'var(--primary-color)', padding: '20px' }}&gt;
          &lt;button 
            onClick={handleBackToList}
            style={{ 
              backgroundColor: 'var(--secondary-color)', 
              color: 'white', 
              border: 'none', 
              padding: '8px 16px', 
              borderRadius: '4px',
              marginBottom: '16px',
              cursor: 'pointer'
            }}
          &gt;
            &lt;FiChevronLeft /&gt; Back
          &lt;/button&gt;
          &lt;h2 style={{ color: 'var(--secondary-color)' }}&gt;{selectedItem.title}&lt;/h2&gt;
          &lt;p&gt;&lt;strong&gt;Category:&lt;/strong&gt; {selectedItem.category}&lt;/p&gt;
          &lt;p&gt;&lt;strong&gt;Date:&lt;/strong&gt; {selectedItem.date}&lt;/p&gt;
          &lt;p style={{ marginTop: '16px' }}&gt;{selectedItem.content}&lt;/p&gt;
        &lt;/div&gt;
      ) : (
        &lt;&gt;
          &lt;div className="search-bar" style={{ padding: '16px', backgroundColor: 'var(--secondary-color)' }}&gt;
            &lt;div style={{ 
              display: 'flex', 
              backgroundColor: 'white', 
              borderRadius: '4px',
              padding: '8px'
            }}&gt;
              &lt;FiSearch style={{ marginRight: '8px', color: 'var(--secondary-color)' }} /&gt;
              &lt;input
                type="text"
                placeholder="Search information..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                style={{ 
                  border: 'none', 
                  outline: 'none', 
                  width: '100%',
                  fontSize: '16px'
                }}
              /&gt;
            &lt;/div&gt;
          &lt;/div&gt;

          &lt;div className="filters" style={{ padding: '16px', backgroundColor: 'white', margin: '16px', borderRadius: '8px' }}&gt;
            &lt;h3 style={{ color: 'var(--secondary-color)', marginTop: 0 }}&gt;&lt;FiFilter /&gt; Filters&lt;/h3&gt;
            &lt;div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap' }}&gt;
              &lt;div&gt;
                &lt;label style={{ display: 'block', marginBottom: '4px', color: 'var(--secondary-color)' }}&gt;Category&lt;/label&gt;
                &lt;select
                  name="category"
                  value={filters.category}
                  onChange={handleFilterChange}
                  style={{ 
                    padding: '8px', 
                    borderRadius: '4px', 
                    border: `1px solid var(--secondary-color)`,
                    backgroundColor: 'white'
                  }}
                &gt;
                  &lt;option value=""&gt;All Categories&lt;/option&gt;
                  &lt;option value="News"&gt;News&lt;/option&gt;
                  &lt;option value="Event"&gt;Event&lt;/option&gt;
                  &lt;option value="Notice"&gt;Notice&lt;/option&gt;
                &lt;/select&gt;
              &lt;/div&gt;
              &lt;div&gt;
                &lt;label style={{ display: 'block', marginBottom: '4px', color: 'var(--secondary-color)' }}&gt;Date&lt;/label&gt;
                &lt;input
                  type="date"
                  name="date"
                  value={filters.date}
                  onChange={handleFilterChange}
                  style={{ 
                    padding: '8px', 
                    borderRadius: '4px', 
                    border: `1px solid var(--secondary-color)`,
                    backgroundColor: 'white'
                  }}
                /&gt;
              &lt;/div&gt;
            &lt;/div&gt;
          &lt;/div&gt;

          &lt;div className="results" style={{ margin: '16px' }}&gt;
            {currentItems.length === 0 ? (
              &lt;p style={{ textAlign: 'center', padding: '32px', color: 'var(--secondary-color)' }}&gt;No results found&lt;/p&gt;
            ) : (
              &lt;&gt;
                {currentItems.map(item =&gt; (
                  &lt;div 
                    key={item.id} 
                    style={{ 
                      backgroundColor: 'white', 
                      padding: '16px', 
                      marginBottom: '16px', 
                      borderRadius: '8px',
                      cursor: 'pointer',
                      borderLeft: `4px solid var(--secondary-color)`
                    }}
                    onClick={() =&gt; handleViewDetails(item)}
                  &gt;
                    &lt;h3 style={{ color: 'var(--secondary-color)', marginTop: 0 }}&gt;{item.title}&lt;/h3&gt;
                    &lt;p style={{ margin: '8px 0', color: '#666' }}&gt;&lt;strong&gt;{item.category}&lt;/strong&gt; • {item.date}&lt;/p&gt;
                    &lt;p style={{ marginBottom: 0 }}&gt;{item.content.substring(0, 100)}...&lt;/p&gt;
                  &lt;/div&gt;
                ))}

                &lt;div style={{ display: 'flex', justifyContent: 'center', gap: '8px', marginTop: '24px' }}&gt;
                  &lt;button
                    onClick={() =&gt; setCurrentPage(prev =&gt; Math.max(prev - 1, 1))}
                    disabled={currentPage === 1}
                    style={{ 
                      backgroundColor: currentPage === 1 ? '#ccc' : 'var(--secondary-color)', 
                      color: 'white', 
                      border: 'none', 
                      padding: '8px 16px', 
                      borderRadius: '4px',
                      cursor: currentPage === 1 ? 'not-allowed' : 'pointer'
                    }}
                  &gt;
                    &lt;FiChevronLeft /&gt; Previous
                  &lt;/button&gt;
                  &lt;span style={{ 
                    display: 'inline-block', 
                    padding: '8px 16px', 
                    backgroundColor: 'white', 
                    borderRadius: '4px'
                  }}&gt;
                    Page {currentPage} of {totalPages}
                  &lt;/span&gt;
                  &lt;button
                    onClick={() =&gt; setCurrentPage(prev =&gt; Math.min(prev + 1, totalPages))}
                    disabled={currentPage === totalPages}
                    style={{ 
                      backgroundColor: currentPage === totalPages ? '#ccc' : 'var(--secondary-color)', 
                      color: 'white', 
                      border: 'none', 
                      padding: '8px 16px', 
                      borderRadius: '4px',
                      cursor: currentPage === totalPages ? 'not-allowed' : 'pointer'
                    }}
                  &gt;
                    Next &lt;FiChevronRight /&gt;
                  &lt;/button&gt;
                &lt;/div&gt;
              &lt;/&gt;
            )}
          &lt;/div&gt;
        &lt;/&gt;
      )}
    &lt;/div&gt;
  )
}

export default App</boltAction>

