<script setup lang="ts">
import { ref, computed } from 'vue'
import AuthView from './views/AuthView.vue'
import DashboardView from './views/DashboardView.vue'
import TaskView from './views/TaskView.vue'
import RewardsView from './views/RewardsView.vue'

type User = {
  id: string
  name: string
  email: string
  level: number
  balance: number
  invitedUsers: number
}

type Task = {
  id: string
  title: string
  description: string
  reward: number
  creatorId: string
  workerId: string | null
  completed: boolean
  createdAt: Date
}

const currentUser = ref<User | null>(null)
const tasks = ref<Task[]>([])
const currentView = ref<'auth' | 'dashboard' | 'tasks' | 'rewards'>('auth')

const handleLogin = (user: User) => {
  currentUser.value = user
  currentView.value = 'dashboard'
}

const handleLogout = () => {
  currentUser.value = null
  currentView.value = 'auth'
}

const createTask = (task: Omit<Task, 'id' | 'creatorId' | 'workerId' | 'completed' | 'createdAt'>) => {
  const newTask: Task = {
    ...task,
    id: Date.now().toString(),
    creatorId: currentUser.value!.id,
    workerId: null,
    completed: false,
    createdAt: new Date()
  }
  tasks.value.push(newTask)
}

const acceptTask = (taskId: string) => {
  const task = tasks.value.find(t => t.id === taskId)
  if (task && !task.workerId) {
    task.workerId = currentUser.value!.id
  }
}

const completeTask = (taskId: string) => {
  const task = tasks.value.find(t => t.id === taskId)
  if (task && task.workerId === currentUser.value!.id) {
    task.completed = true
    const commission = task.reward * 0.1 // 10% platform commission
    currentUser.value!.balance += task.reward - commission
  }
}

const inviteUser = () => {
  if (currentUser.value) {
    currentUser.value.invitedUsers += 1
    currentUser.value.balance += 5 // $5 reward per invite
  }
}
</script>

<template>
  <div class="app-container">
    <AuthView 
      v-if="currentView === 'auth' && !currentUser" 
      @login="handleLogin"
    />

    <div v-else class="platform-container">
      <header class="platform-header">
        <h1>Task Reward Platform</h1>
        <nav class="platform-nav">
          <button @click="currentView = 'dashboard'">Dashboard</button>
          <button @click="currentView = 'tasks'">Tasks</button>
          <button @click="currentView = 'rewards'">Rewards</button>
          <button @click="handleLogout">Logout</button>
        </nav>
      </header>

      <main class="platform-main">
        <DashboardView 
          v-if="currentView === 'dashboard'"
          :user="currentUser"
          :tasks="tasks"
          @invite="inviteUser"
        />

        <TaskView 
          v-if="currentView === 'tasks'"
          :user="currentUser"
          :tasks="tasks"
          @create="createTask"
          @accept="acceptTask"
          @complete="completeTask"
        />

        <RewardsView 
          v-if="currentView === 'rewards'"
          :user="currentUser"
          :tasks="tasks"
        />
