import axios from 'axios';

const api = axios.create({
  baseURL: '/api',
  withCredentials: true
});

export const authAPI = {
  login: (credentials: { email: string; password: string }) =>
    api.post('/auth/login', credentials),
  register: (user: { email: string; password: string; name: string }) =>
    api.post('/auth/register', user),
  logout: () => api.post('/auth/logout'),
  me: () => api.get('/auth/me')
};

export const serviceAPI = {
  create: (service: { name: string; config: object }) =>
    api.post('/services', service),
  list: () => api.get('/services'),
  get: (id: string) => api.get(`/services/${id}`),
  update: (id: string, updates: object) => api.patch(`/services/${id}`, updates),
  delete: (id: string) => api.delete(`/services/${id}`)
};

export const deploymentAPI = {
  deploy: (serviceId: string, env: string) =>
    api.post(`/deployments/${serviceId}/deploy`, { env }),
  list: (serviceId: string) => api.get(`/deployments/${serviceId}`),
  status: (deploymentId: string) => api.get(`/deployments/${deploymentId}/status`)
};
