import { useState, useEffect } from 'react';
import { ServiceCard } from '../components/Dashboard/ServiceCard';
import { serviceAPI } from '../api';

export function Dashboard() {
  const [services, setServices] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchServices = async () => {
      try {
        const response = await serviceAPI.list();
        setServices(response.data);
      } catch (error) {
        console.error('Failed to fetch services:', error);
      } finally {
        setLoading(false);
      }
    };
    fetchServices();
  }, []);

  const handleDeploy = async (serviceId: string) => {
    try {
      await deploymentAPI.deploy(serviceId, 'production');
      // Refresh services after deployment
      const response = await serviceAPI.list();
      setServices(response.data);
    } catch (error) {
      console.error('Deployment failed:', error);
    }
  };

  const handleConfigure = (serviceId: string) => {
    // Navigate to service configuration
    window.location.href = `/services/${serviceId}/configure`;
  };

  if (loading) {
    return <div className="text-center py-8">Loading services...</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-[#6b6b47]">My Services</h2>
        <button className="bg-[#6b6b47] text-white px-4 py-2 rounded hover:bg-[#5a5a3d]">
          + New Service
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {services.map((service) => (
          <ServiceCard
            key={service.id}
            id={service.id}
            name={service.name}
            status={service.status}
            lastDeployed={service.lastDeployed}
            onDeploy={handleDeploy}
            onConfigure={handleConfigure}
          />
        ))}
      </div>
    </div>
  );
}
</boltAction>

