import WorkLog from './WorkLog.vue'

const props = defineProps<{
  username: string
}>()

const activeTab = ref('tasks')
const members = ref(['Alice', 'Bob', 'Charlie', props.username])
const selectedMember = ref(props.username)
const tasks = ref([
  { id: 1, title: 'Design UI', assignedTo: props.username, dueDate: '2023-11-15', completed: false },
  { id: 2, title: 'Implement backend', assignedTo: 'Alice', dueDate: '2023-11-17', completed: false },
  { id: 3, title: 'Write documentation', assignedTo: 'Bob', dueDate: '2023-11-20', completed: true }
])

const workLogs = ref([
  { id: 1, taskId: 1, date: '2023-11-10', hours: 2, description: 'Created wireframes' },
  { id: 2, taskId: 1, date: '2023-11-11', hours: 3, description: 'Implemented color scheme' }
])

const filteredTasks = computed(() => {
  return tasks.value.filter(task => task.assignedTo === selectedMember.value)
})

const addTask = (task: { title: string, dueDate: string }) => {
  tasks.value.push({
    id: tasks.value.length + 1,
    title: task.title,
    assignedTo: selectedMember.value,
    dueDate: task.dueDate,
    completed: false
  })
}

const addWorkLog = (log: { taskId: number, hours: number, description: string }) => {
  workLogs.value.push({
    id: workLogs.value.length + 1,
    taskId: log.taskId,
    date: new Date().toISOString().split('T')[0],
    hours: log.hours,
    description: log.description
  })
}

const toggleTaskCompletion = (taskId: number) => {
  const task = tasks.value.find(t => t.id === taskId)
  if (task) {
    task.completed = !task.completed
  }
}
</script>

