    appointments.value = [
      { id: 1, date: '2023-11-15', time: '10:00 AM', status: 'Confirmed' },
      { id: 2, date: '2023-12-05', time: '02:30 PM', status: 'Pending' }
    ]
    isLoading.value = false
  }, 1000)
}

const fetchAvailableSlots = async () => {
  isLoading.value = true
  // Simulate API call
  setTimeout(() => {
    availableSlots.value = [
      { id: 1, date: '2023-11-20', time: '09:00 AM' },
      { id: 2, date: '2023-11-20', time: '11:00 AM' },
      { id: 3, date: '2023-11-21', time: '10:30 AM' },
      { id: 4, date: '2023-11-22', time: '03:00 PM' }
    ]
    isLoading.value = false
  }, 1000)
}

const handleBookAppointment = (slot: any) => {
  // In a real app, this would call an API
  appointments.value.push({
    id: Date.now(),
    date: slot.date,
    time: slot.time,
    status: 'Pending'
  })
  showForm.value = false
}

const handleCancelAppointment = (id: number) => {
  // In a real app, this would call an API
  appointments.value = appointments.value.filter(appt => appt.id !== id)
}

onMounted(() => {
  fetchAppointments()
  fetchAvailableSlots()
})
