  { id: 3, username: 'viewer', role: 'viewer' }
])

const apiPermissions = ref([
  { userId: 1, apiId: 1, canRead: true, canWrite: true },
  { userId: 2, apiId: 1, canRead: true, canWrite: false }
])

const newUser = ref({
  username: '',
  role: 'viewer'
})

const handleCreateUser = () => {
  users.value.push({
    id: Date.now(),
    ...newUser.value
  })
  newUser.value = { username: '', role: 'viewer' }
}

const handleDeleteUser = (id: number) => {
  users.value = users.value.filter(user => user.id !== id)
}

const handleUpdatePermission = (userId: number, apiId: number, field: string, value: boolean) => {
  const permission = apiPermissions.value.find(
    p => p.userId === userId && p.apiId === apiId
  )
  if (permission) {
    permission[field] = value
  } else {
    apiPermissions.value.push({
      userId,
      apiId,
      canRead: field === 'canRead' ? value : false,
      canWrite: field === 'canWrite' ? value : false
    })
  }
}
</script>

<template>
