I'll implement a real-time event push system with Server-Sent Events (SSE) using the requested color scheme. Here's the implementation:

<boltArtifact id="real-time-events" title="Real-time Event Push System">
<boltAction type="file" filePath="src/server.js">
import express from 'express';
import cors from 'cors';

const app = express();
app.use(cors());

const PORT = 3001;
let clients = [];

app.get('/events', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const clientId = Date.now();
  const newClient = {
    id: clientId,
    res,
    subscriptions: new Set()
  };
  clients.push(newClient);

  req.on('close', () => {
    clients = clients.filter(client => client.id !== clientId);
  });
});

function sendEventToClient(event, data) {
  clients.forEach(client => {
    if (client.subscriptions.has(event)) {
      client.res.write(`event: ${event}\n`);
      client.res.write(`data: ${JSON.stringify(data)}\n\n`);
    }
  });
}

// Simulate events
setInterval(() => {
  const events = ['news', 'weather', 'sports', 'stocks'];
  const randomEvent = events[Math.floor(Math.random() * events.length)];
  const eventData = {
    id: Date.now(),
    timestamp: new Date().toISOString(),
    message: `Update for ${randomEvent}`,
    content: `Details about ${randomEvent} update`
  };
  sendEventToClient(randomEvent, eventData);
}, 3000);

app.listen(PORT, () => {
  console.log(`Event server running on port ${PORT}`);
});
</boltAction>

