<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue';
import EventList from './components/EventList.vue';
import SubscriptionControls from './components/SubscriptionControls.vue';

const events = ref<Array<{type: string, data: any}>>([]);
const eventSource = ref<EventSource | null>(null);

const availableEvents = ['news', 'weather', 'sports', 'stocks'];
const subscribedEvents = ref<string[]>([]);

function handleEvent(event: MessageEvent) {
  events.value.unshift({
    type: event.type,
    data: JSON.parse(event.data)
  });
}

function subscribeToEvents() {
  if (eventSource.value) {
    eventSource.value.close();
  }

  const eventTypes = subscribedEvents.value.join(',');
  eventSource.value = new EventSource(`http://localhost:3001/events?types=${eventTypes}`);

  subscribedEvents.value.forEach(type => {
    eventSource.value?.addEventListener(type, handleEvent);
  });
}

onMounted(() => {
  subscribedEvents.value = ['news', 'weather'];
  subscribeToEvents();
});

onUnmounted(() => {
  if (eventSource.value) {
    eventSource.value.close();
  }
});
</script>

<template>
  <div class="app-container">
    <h1>Real-time Event Dashboard</h1>
    <SubscriptionControls 
      :availableEvents="availableEvents" 
      :subscribedEvents="subscribedEvents"
      @update-subscriptions="subscribeToEvents"
