<script setup lang="ts">
const props = defineProps<{
  availableEvents: string[],
  subscribedEvents: string[]
}>();

const emit = defineEmits(['update-subscriptions']);

function toggleSubscription(eventType: string) {
  const index = props.subscribedEvents.indexOf(eventType);
  if (index === -1) {
    props.subscribedEvents.push(eventType);
  } else {
    props.subscribedEvents.splice(index, 1);
  }
  emit('update-subscriptions');
}
</script>

