}

const audioItems = ref<AudioItem[]>([
  { id: '1', title: 'Sample Track 1', artist: 'Artist A', src: 'https://example.com/audio1.mp3', duration: 180 },
  { id: '2', title: 'Sample Track 2', artist: 'Artist B', src: 'https://example.com/audio2.mp3', duration: 210 },
  { id: '3', title: 'Sample Track 3', artist: 'Artist C', src: 'https://example.com/audio3.mp3', duration: 195 },
])

const searchQuery = ref('')
const selectedAudio = ref<AudioItem | null>(null)
const playlists = ref<{name: string, items: AudioItem[]}[]>([])
const newPlaylistName = ref('')

const filteredItems = computed(() => {
  return audioItems.value.filter(item => 
    item.title.toLowerCase().includes(searchQuery.value.toLowerCase()) ||
    item.artist.toLowerCase().includes(searchQuery.value.toLowerCase())
  )
})

function selectAudio(item: AudioItem) {
  selectedAudio.value = item
}

function createPlaylist() {
  if (newPlaylistName.value.trim() && selectedAudio.value) {
    playlists.value.push({
      name: newPlaylistName.value,
      items: [selectedAudio.value]
    })
    newPlaylistName.value = ''
  }
}

function addToPlaylist(playlistIndex: number) {
  if (selectedAudio.value) {
    playlists.value[playlistIndex].items.push(selectedAudio.value)
  }
}
</script>

<template>
  <div class="audio-browser">
    <div class="search-container">
      <input 
        v-model="searchQuery" 
        placeholder="Search audio..." 
        class="search-input"
      />
    </div>

    <div class="content">
      <div class="audio-list">
        <h3>Available Tracks</h3>
        <ul>
          <li 
            v-for="item in filteredItems" 
            :key="item.id"
            @click="selectAudio(item)"
            :class="{ selected: selectedAudio?.id === item.id }"
          >
            {{ item.title }} - {{ item.artist }} ({{ Math.floor(item.duration / 60) }}:{{ (item.duration % 60).toString().padStart(2, '0') }})
          </li>
        </ul>
      </div>

      <div class="player-section">
        <AudioPlayer v-if="selectedAudio" :audio-src="selectedAudio.src" />
        <div v-else class="no-selection">
          Select a track to play
        </div>

        <div class="playlist-controls" v-if="selectedAudio">
          <input v-model="newPlaylistName" placeholder="New playlist name" />
          <button @click="createPlaylist">Create Playlist</button>

          <div v-if="playlists.length">
            <h4>Add to Playlist:</h4>
            <button 
              v-for="(playlist, index) in playlists" 
              :key="index"
              @click="addToPlaylist(index)"
            >
              {{ playlist.name }}
            </button>
          </div>
        </div>
      </div>

      <div class="playlists" v-if="playlists.length">
        <h3>Your Playlists</h3>
        <div v-for="(playlist, index) in playlists" :key="index" class="playlist">
          <h4>{{ playlist.name }}</h4>
          <ul>
            <li 
              v-for="(item, itemIndex) in playlist.items" 
              :key="itemIndex"
              @click="selectAudio(item)"
            >
              {{ item.title }} - {{ item.artist }}
            </li>
          </ul>
        </div>
      </div>
    </div>
  </div>
</template>

