<script setup lang="ts">
import { ref, watch } from 'vue'

const props = defineProps<{
  src: string
}>()

const player = ref<HTMLVideoElement | HTMLAudioElement | null>(null)
const isPlaying = ref(false)
const currentTime = ref(0)
const duration = ref(0)
const volume = ref(1)
const mediaType = ref<'video' | 'audio' | null>(null)

const videoFormats = ['mp4', 'webm', 'ogg']
const audioFormats = ['mp3', 'wav', 'ogg']

function detectMediaType(url: string) {
  const extension = url.split('.').pop()?.toLowerCase()
  if (!extension) return null

  if (videoFormats.includes(extension)) return 'video'
  if (audioFormats.includes(extension)) return 'audio'
  return null
}

function togglePlay() {
  if (!player.value) return

  if (isPlaying.value) {
    player.value.pause()
  } else {
    player.value.play()
  }
  isPlaying.value = !isPlaying.value
}

function stop() {
  if (!player.value) return

  player.value.pause()
  player.value.currentTime = 0
  isPlaying.value = false
}

function updateTime() {
  if (!player.value) return
  currentTime.value = player.value.currentTime
}

function seek(e: MouseEvent) {
  if (!player.value) return

  const rect = (e.target as HTMLElement).getBoundingClientRect()
  const percent = (e.clientX - rect.left) / rect.width
  player.value.currentTime = percent * duration.value
}

watch(() => props.src, (newSrc) => {
  if (!newSrc) return

  mediaType.value = detectMediaType(newSrc)
  isPlaying.value = false
  currentTime.value = 0
}, { immediate: true })
</script>

<template>
  <div class="media-player">
    <video
      v-if="mediaType === 'video'"
      ref="player"
      :src="src"
      @timeupdate="updateTime"
      @loadedmetadata="duration = ($event.target as HTMLVideoElement).duration"
      @ended="isPlaying = false"
      class="media-element"
    ></video>

    <audio
      v-else-if="mediaType === 'audio'"
      ref="player"
      :src="src"
      @timeupdate="updateTime"
      @loadedmetadata="duration = ($event.target as HTMLAudioElement).duration"
      @ended="isPlaying = false"
      class="media-element"
    ></audio>

    <div v-else class="no-media">
      <p>No supported media selected</p>
    </div>

    <div class="controls" v-if="mediaType">
      <button @click="togglePlay">
        {{ isPlaying ? 'Pause' : 'Play' }}
      </button>
      <button @click="stop">Stop</button>

      <div class="progress" @click="seek">
        <div
          class="progress-bar"
          :style="{ width: `${(currentTime / duration) * 100}%` }"
        ></div>
      </div>

      <div class="volume">
        <label>Volume:</label>
        <input
          type="range"
          min="0"
          max="1"
          step="0.01"
          v-model="volume"
          @input="player && (player.volume = volume)"
        >
      </div>

      <div class="time">
        {{ new Date(currentTime * 1000).toISOString().substr(14, 5) }} /
        {{ new Date(duration * 1000).toISOString().substr(14, 5) }}
      </div>
    </div>
  </div>
</template>

