<boltAction type="file" filePath="src/components/MediaPlayer.vue">
<script setup lang="ts">
import { ref, computed } from 'vue'

const currentFile = ref<File | null>(null)
const playlist = ref<File[]>([])
const isPlaying = ref(false)
const currentTime = ref(0)
const duration = ref(0)
const volume = ref(0.7)
const mediaRef = ref<HTMLMediaElement | null>(null)

const supportedFormats = [
  'video/mp4', 'video/mpeg', 'video/avi', 'video/x-msvideo',
  'video/quicktime', 'video/x-ms-wmv', 'audio/mpeg', 'audio/wav'
]

const handleFileChange = (e: Event) => {
  const input = e.target as HTMLInputElement
  if (input.files?.length) {
    const file = input.files[0]
    if (supportedFormats.includes(file.type)) {
      currentFile.value = file
      if (!playlist.value.some(f => f.name === file.name)) {
        playlist.value.push(file)
      }
      playFile(file)
    }
  }
}

const playFile = (file: File) => {
  currentFile.value = file
  const url = URL.createObjectURL(file)
  if (mediaRef.value) {
    mediaRef.value.src = url
    mediaRef.value.play()
    isPlaying.value = true
  }
}

const togglePlay = () => {
  if (mediaRef.value) {
    if (isPlaying.value) {
      mediaRef.value.pause()
    } else {
      mediaRef.value.play()
    }
    isPlaying.value = !isPlaying.value
  }
}

const stopPlayback = () => {
  if (mediaRef.value) {
    mediaRef.value.pause()
    mediaRef.value.currentTime = 0
    isPlaying.value = false
  }
}

const updateTime = () => {
  if (mediaRef.value) {
    currentTime.value = mediaRef.value.currentTime
    duration.value = mediaRef.value.duration
  }
}

const seek = (time: number) => {
  if (mediaRef.value) {
    mediaRef.value.currentTime = time
  }
}

const setVolume = (vol: number) => {
  volume.value = vol
  if (mediaRef.value) {
    mediaRef.value.volume = vol
  }
}

const formatTime = (seconds: number) => {
  const mins = Math.floor(seconds / 60)
  const secs = Math.floor(seconds % 60)
  return `${mins}:${secs < 10 ? '0' : ''}${secs}`
}

const currentTimeFormatted = computed(() => formatTime(currentTime.value))
const durationFormatted = computed(() => formatTime(duration.value))
</script>

<template>
  <div class="media-player">
    <div class="player-container">
      <video
        v-if="currentFile?.type.includes('video')"
        ref="mediaRef"
        @timeupdate="updateTime"
        @loadedmetadata="updateTime"
        @ended="isPlaying = false"
      ></video>
      <audio
        v-else-if="currentFile?.type.includes('audio')"
        ref="mediaRef"
        @timeupdate="updateTime"
        @loadedmetadata="updateTime"
        @ended="isPlaying = false"
      ></audio>
      <div v-else class="no-media">
        <p>No media selected</p>
      </div>
    </div>

    <div class="controls">
      <div class="time-display">
        {{ currentTimeFormatted }} / {{ durationFormatted }}
      </div>
      <input
        type="range"
        min="0"
        :max="duration"
        :value="currentTime"
        @input="seek(Number(($event.target as HTMLInputElement).value))"
        class="seek-bar"
      />
      <div class="buttons">
        <button @click="stopPlayback">⏹</button>
        <button @click="togglePlay">{{ isPlaying ? '⏸' : '▶' }}</button>
        <button @click="seek(currentTime - 10)">⏪</button>
        <button @click="seek(currentTime + 10)">⏩</button>
        <input
          type="range"
          min="0"
          max="1"
          step="0.01"
          :value="volume"
          @input="setVolume(Number(($event.target as HTMLInputElement).value))"
          class="volume-control"
        />
      </div>
    </div>

    <div class="file-input">
      <input type="file" @change="handleFileChange" accept="video/*,audio/*" />
    </div>

    <div class="playlist" v-if="playlist.length">
      <h3>Playlist</h3>
      <ul>
        <li
          v-for="(file, index) in playlist"
          :key="index"
          @click="playFile(file)"
          :class="{ active: currentFile?.name === file.name }"
        >
          {{ file.name }}
        </li>
      </ul>
    </div>
  </div>
