import MusicLibrary from './components/MusicLibrary.vue'
import SearchBar from './components/SearchBar.vue'
import NowPlaying from './components/NowPlaying.vue'

// Sample music data
const musicLibrary = ref([
  { id: 1, title: 'Bohemian Rhapsody', artist: 'Queen', album: 'A Night at the Opera', genre: 'Rock', duration: '5:55', lyrics: 'Is this the real life? Is this just fantasy?', cover: 'queen.jpg' },
  { id: 2, title: 'Lemon', artist: 'Kenshi Yonezu', album: 'BOOTLEG', genre: 'J-Pop', duration: '4:15', lyrics: '夢ならばどれほどよかったでしょう', cover: 'yonezu.jpg' },
  { id: 3, title: 'Blinding Lights', artist: 'The Weeknd', album: 'After Hours', genre: 'Pop', duration: '3:20', lyrics: 'I been tryna call...', cover: 'weeknd.jpg' },
  { id: 4, title: '紅蓮華', artist: 'LiSA', album: '紅蓮華', genre: 'Anime', duration: '3:57', lyrics: '強くなれる理由を知った', cover: 'lisa.jpg' },
  { id: 5, title: 'Shape of You', artist: 'Ed Sheeran', album: '÷', genre: 'Pop', duration: '3:53', lyrics: 'The club isn\'t the best place...', cover: 'edsheeran.jpg' }
])

const currentTrack = ref(musicLibrary.value[0])
const isPlaying = ref(false)
const showLyrics = ref(false)
const searchQuery = ref('')

const filteredLibrary = computed(() => {
  if (!searchQuery.value) return musicLibrary.value
  const query = searchQuery.value.toLowerCase()
  return musicLibrary.value.filter(track => 
    track.title.toLowerCase().includes(query) || 
    track.artist.toLowerCase().includes(query) ||
    track.album.toLowerCase().includes(query)
  )
})

function playTrack(track: any) {
  currentTrack.value = track
  isPlaying.value = true
}

function togglePlay() {
  isPlaying.value = !isPlaying.value
}

function nextTrack() {
  const currentIndex = musicLibrary.value.findIndex(t => t.id === currentTrack.value.id)
  const nextIndex = (currentIndex + 1) % musicLibrary.value.length
  currentTrack.value = musicLibrary.value[nextIndex]
}

function prevTrack() {
  const currentIndex = musicLibrary.value.findIndex(t => t.id === currentTrack.value.id)
  const prevIndex = (currentIndex - 1 + musicLibrary.value.length) % musicLibrary.value.length
  currentTrack.value = musicLibrary.value[prevIndex]
}

function toggleLyrics() {
  showLyrics.value = !showLyrics.value
}
</script>

<template>
  <div class="app-container">
    <div class="sidebar">
      <h1>Platinum Player</h1>
      <SearchBar v-model="searchQuery" />
      <MusicLibrary 
        :tracks="filteredLibrary" 
        :currentTrack="currentTrack" 
        @play="playTrack"
      />
    </div>
    <div class="main-content">
      <NowPlaying 
        :track="currentTrack" 
        :showLyrics="showLyrics" 
        @toggle-lyrics="toggleLyrics"
      />
      <PlayerControls 
        :isPlaying="isPlaying" 
        @toggle-play="togglePlay"
        @next-track="nextTrack"
        @prev-track="prevTrack"
      />
    </div>
  </div>
</template>

