<script setup lang="ts">
import { ref } from 'vue'

const fileInput = ref<HTMLInputElement | null>(null)
const selectedFile = ref<File | null>(null)
const fileName = ref('')
const fileType = ref('')
const targetFormat = ref('')
const isConverting = ref(false)
const downloadUrl = ref('')
const errorMessage = ref('')

const formats = {
  video: ['mp4', 'webm', 'ogg', 'mov'],
  audio: ['mp3', 'wav', 'aac', 'ogg']
}

const handleFileChange = (e: Event) => {
  const target = e.target as HTMLInputElement
  if (target.files && target.files[0]) {
    selectedFile.value = target.files[0]
    fileName.value = selectedFile.value.name
    fileType.value = selectedFile.value.type.split('/')[0]
    targetFormat.value = ''
    downloadUrl.value = ''
    errorMessage.value = ''
  }
}

const convertFile = () => {
  if (!selectedFile.value || !targetFormat.value) {
    errorMessage.value = 'Please select a file and target format'
    return
  }

  isConverting.value = true
  errorMessage.value = ''

  // Simulate conversion process (in a real app, this would call an API)
  setTimeout(() => {
    const blob = new Blob([selectedFile.value!], { type: selectedFile.value!.type })
    downloadUrl.value = URL.createObjectURL(blob)
    isConverting.value = false
  }, 2000)
}

const resetForm = () => {
  if (fileInput.value) fileInput.value.value = ''
  selectedFile.value = null
  fileName.value = ''
  fileType.value = ''
  targetFormat.value = ''
  downloadUrl.value = ''
  errorMessage.value = ''
}
</script>

<template>
  <div class="converter-container">
    <h1>Multimedia Converter</h1>

    <div class="upload-section">
      <input 
        ref="fileInput"
        type="file" 
        accept="video/*,audio/*" 
        @change="handleFileChange"
        class="file-input"
      >
      <button @click="fileInput?.click()" class="upload-btn">
        {{ fileName || 'Select File' }}
      </button>
    </div>

    <div v-if="fileName" class="file-info">
      <p>Selected: {{ fileName }}</p>
      <p>Type: {{ fileType }}</p>
    </div>

    <div v-if="fileType" class="format-selection">
      <label>Convert to:</label>
      <select v-model="targetFormat" class="format-select">
        <option value="" disabled>Select format</option>
        <option v-for="format in formats[fileType]" :value="format" :key="format">
          {{ format.toUpperCase() }}
        </option>
      </select>
    </div>

    <div v-if="errorMessage" class="error-message">
      {{ errorMessage }}
    </div>

    <div class="action-buttons">
      <button 
        @click="convertFile" 
        :disabled="!selectedFile || !targetFormat || isConverting"
        class="action-btn convert-btn"
      >
        {{ isConverting ? 'Converting...' : 'Convert' }}
      </button>
      <button @click="resetForm" class="action-btn reset-btn">
        Reset
      </button>
    </div>

    <div v-if="downloadUrl" class="download-section">
      <a 
        :href="downloadUrl" 
        :download="`converted.${targetFormat}`"
        class="download-btn"
      >
        Download Converted File
      </a>
    </div>
  </div>
</template>

