I'll create a beautiful HTTP server application with the requested color scheme (lemon chiffon background, olive UI elements). Here's the implementation:

<boltArtifact id="http-server-app" title="HTTP Server Application with Custom UI">
  <boltAction type="file" filePath="src/App.tsx">
import React, { useState } from 'react'
import { Send, Server, Network, Home, FolderInput } from 'lucide-react'

function App() {
  const [method, setMethod] = useState('GET')
  const [url, setUrl] = useState('')
  const [response, setResponse] = useState('')
  const [requestBody, setRequestBody] = useState('')
  const [requests, setRequests] = useState<Array<{method: string, url: string}>>([])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    try {
      const res = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json'
        },
        body: method !== 'GET' ? requestBody : undefined
      })
      const data = await res.text()
      setResponse(data)
      setRequests([...requests, {method, url}])
    } catch (err) {
      setResponse(`Error: ${err instanceof Error ? err.message : String(err)}`)
    }
  }

  return (
    <div className="min-h-screen bg-lemon-chiffon flex">
      {/* Sidebar */}
      <div className="w-64 bg-olive p-4 text-white">
        <div className="flex items-center mb-8">
          <Server className="mr-2" />
          <h1 className="text-xl font-bold">HTTP Client</h1>
        </div>

        <nav>
          <ul className="space-y-2">
            <li>
              <button className="flex items-center w-full p-2 rounded hover:bg-olive-dark">
                <Home className="mr-2" size={16} />
                Dashboard
              </button>
            </li>
            <li>
              <button className="flex items-center w-full p-2 rounded hover:bg-olive-dark">
                <Network className="mr-2" size={16} />
                Requests
              </button>
            </li>
            <li>
              <button className="flex items-center w-full p-2 rounded hover:bg-olive-dark">
                <FolderInput className="mr-2" size={16} />
                History
              </button>
            </li>
          </ul>
        </nav>
      </div>

      {/* Main Content */}
      <div className="flex-1 p-8">
        <div className="max-w-4xl mx-auto">
          <div className="bg-white rounded-lg shadow-md p-6 mb-6">
            <form onSubmit={handleSubmit}>
              <div className="flex mb-4">
                <select 
                  value={method}
                  onChange={(e) => setMethod(e.target.value)}
                  className="bg-olive text-white px-4 py-2 rounded-l-md"
                >
                  <option value="GET">GET</option>
                  <option value="POST">POST</option>
                  <option value="PUT">PUT</option>
                  <option value="DELETE">DELETE</option>
                </select>
                <input
                  type="text"
                  value={url}
                  onChange={(e) => setUrl(e.target.value)}
                  placeholder="Enter URL"
                  className="flex-1 border border-gray-300 px-4 py-2"
                  required
                />
                <button 
                  type="submit"
                  className="bg-olive text-white px-4 py-2 rounded-r-md flex items-center"
                >
                  <Send className="mr-2" size={16} />
                  Send
                </button>
              </div>

              {method !== 'GET' && (
                <div className="mb-4">
                  <label className="block text-gray-700 mb-2">Request Body</label>
                  <textarea
                    value={requestBody}
                    onChange={(e) => setRequestBody(e.target.value)}
                    className="w-full border border-gray-300 rounded-md p-2 h-32"
                    placeholder="Enter JSON body"
                  />
                </div>
              )}
            </form>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <h2 className="text-lg font-semibold mb-4 text-olive">Response</h2>
            <pre className="bg-gray-100 p-4 rounded-md overflow-x-auto">
              {response || 'No response yet'}
            </pre>
          </div>
        </div>
      </div>
    </div>
  )
}

export default App
  </boltAction>

