<script setup lang="ts">
import { ref } from 'vue'
import DocumentList from './DocumentList.vue'
import EditorPanel from './EditorPanel.vue'

const props = defineProps(['user'])
const currentDocument = ref(null)
const documents = ref([])

const handleFileUpload = (file) => {
  const reader = new FileReader()
  reader.onload = (e) => {
    currentDocument.value = {
      original: e.target.result,
      modified: e.target.result,
      name: file.name,
      history: []
    }
  }
  reader.readAsText(file)
}

const updateDocument = (updates) => {
  currentDocument.value = {
    ...currentDocument.value,
    ...updates,
    history: [...currentDocument.value.history, {
      timestamp: new Date().toISOString(),
      changes: updates
    }]
  }
}
</script>

<template>
  <div class="editor-container">
    <DocumentList 
      :documents="documents" 
      @select="doc => currentDocument = doc"
    />
    <EditorPanel 
      v-if="currentDocument"
      :document="currentDocument"
      @update="updateDocument"
      @download="() => {}"
    />
    <div v-else class="upload-area">
      <input type="file" @change="(e) => handleFileUpload(e.target.files[0])" accept=".eml">
      <p>Or select from your existing documents</p>
    </div>
  </div>
</template>

