<script setup lang="ts">
import { ref } from 'vue'

defineProps({
  mailbox: {
    type: String,
    default: 'inbox'
  }
})

const emit = defineEmits(['compose', 'settings', 'logout'])

const emails = ref([
  { id: 1, from: 'john@example.com', subject: 'Meeting tomorrow', date: '10:30 AM', read: false },
  { id: 2, from: 'support@company.com', subject: 'Your subscription', date: 'Yesterday', read: true },
  { id: 3, from: 'newsletter@service.com', subject: 'Weekly digest', date: 'Mar 15', read: true }
])

const deleteEmail = (id: number) => {
  emails.value = emails.value.filter(email => email.id !== id)
}

const markAsRead = (id: number) => {
  const email = emails.value.find(e => e.id === id)
  if (email) email.read = true
}
</script>

