    from: 'support@partner.com',
    subject: 'Account Issue',
    content: 'Having trouble accessing my account. Need help resetting password.',
    date: '2023-11-14',
    status: 'responded',
    keywords: ['account', 'access', 'password']
  }
])

const templates = ref([
  {
    id: 1,
    name: 'Product Inquiry',
    content: 'Thank you for your interest in our products. Could you please specify which product you\'re interested in?',
    triggers: ['product', 'inquiry']
  },
  {
    id: 2,
    name: 'Account Support',
    content: 'We\'ve received your account access request. Please follow this link to reset your password: [reset link]',
    triggers: ['account', 'password']
  }
])

const selectEmail = (email) => {
  selectedEmail.value = email
  showTemplates.value = false
}

const analyzeEmail = (email) => {
  // Simple keyword matching for demo
  const matchedTemplate = templates.value.find(template => 
    template.triggers.some(trigger => 
      email.content.toLowerCase().includes(trigger)
    )
  )

  if (matchedTemplate) {
    email.status = 'auto-responded'
    return matchedTemplate.content
  }
  return null
}

const sendResponse = (response) => {
  const email = emails.value.find(e => e.id === selectedEmail.value.id)
  if (email) {
    email.status = 'responded'
    email.response = response
  }
  selectedEmail.value = null
}
</script>

