  const blacklist = ['spammer@example.com', 'bad@domain.com']

  const lines = emailContent.value.split('\n')
  const fromLine = lines.find(line => line.toLowerCase().startsWith('from:'))
  const subjectLine = lines.find(line => line.toLowerCase().startsWith('subject:'))

  const from = fromLine ? fromLine.split(':')[1].trim() : ''
  const subject = subjectLine ? subjectLine.split(':')[1].trim() : ''

  const isBlacklisted = blacklist.includes(from)
  const hasSpamKeywords = spamKeywords.some(keyword => 
    subject.toLowerCase().includes(keyword) || emailContent.value.toLowerCase().includes(keyword)
  )

  scanResult.value = {
    from,
    subject,
    isSpam: isBlacklisted || hasSpamKeywords,
    reasons: [
      ...(isBlacklisted ? ['Sender is blacklisted'] : []),
      ...(hasSpamKeywords ? ['Contains spam keywords'] : [])
    ]
  }
}
</script>

<template>
  <div class="scanner-container">
    <h2>Email Scanner</h2>
    <textarea v-model="emailContent" placeholder="Paste email content here..." rows="10"></textarea>
    <button @click="scanEmail" class="scan-button">Scan Email</button>

    <div v-if="scanResult" class="result-container">
      <h3>Scan Results</h3>
      <p><strong>From:</strong> {{ scanResult.from }}</p>
      <p><strong>Subject:</strong> {{ scanResult.subject }}</p>
      <p><strong>Status:</strong> <span :class="{ 'spam': scanResult.isSpam, 'ham': !scanResult.isSpam }">
        {{ scanResult.isSpam ? 'SPAM' : 'CLEAN' }}
      </span></p>

      <div v-if="scanResult.reasons.length" class="reasons">
        <h4>Reasons:</h4>
        <ul>
          <li v-for="reason in scanResult.reasons" :key="reason">{{ reason }}</li>
        </ul>
