<script setup lang="ts">
import { ref } from 'vue'

const context = ref('')
const tone = ref('neutral')
const style = ref('informative')
const sentiment = ref('neutral')
const generatedContent = ref('')
const isLoading = ref(false)

const tones = [
  { value: 'formal', label: 'Formal' },
  { value: 'casual', label: 'Casual' },
  { value: 'friendly', label: 'Friendly' },
  { value: 'professional', label: 'Professional' }
]

const styles = [
  { value: 'informative', label: 'Informative' },
  { value: 'persuasive', label: 'Persuasive' },
  { value: 'descriptive', label: 'Descriptive' },
  { value: 'narrative', label: 'Narrative' }
]

const sentiments = [
  { value: 'positive', label: 'Positive' },
  { value: 'neutral', label: 'Neutral' },
  { value: 'negative', label: 'Negative' }
]

const generateContent = () => {
  isLoading.value = true
  // Simulate API call
  setTimeout(() => {
    generatedContent.value = `Here is your ${tone.value} content in a ${style.value} style with ${sentiment.value} sentiment, based on the context: "${context.value}"`
    isLoading.value = false
  }, 1500)
}
</script>

<template>
  <div class="generator-container">
    <div class="input-section">
      <h2>AI Content Generator</h2>

      <div class="form-group">
        <label for="context">Context:</label>
        <textarea 
          id="context" 
          v-model="context" 
          placeholder="Enter your content context here..."
        ></textarea>
      </div>

      <div class="form-group">
        <label>Tone:</label>
        <div class="radio-group">
          <label v-for="t in tones" :key="t.value">
            <input type="radio" v-model="tone" :value="t.value">
            {{ t.label }}
          </label>
        </div>
      </div>

      <div class="form-group">
        <label>Style:</label>
        <div class="radio-group">
          <label v-for="s in styles" :key="s.value">
            <input type="radio" v-model="style" :value="s.value">
            {{ s.label }}
          </label>
        </div>
      </div>

      <div class="form-group">
        <label>Sentiment:</label>
        <div class="radio-group">
          <label v-for="s in sentiments" :key="s.value">
            <input type="radio" v-model="sentiment" :value="s.value">
            {{ s.label }}
          </label>
        </div>
      </div>

      <button @click="generateContent" :disabled="isLoading || !context">
        {{ isLoading ? 'Generating...' : 'Generate Content' }}
      </button>
    </div>

    <div class="output-section" v-if="generatedContent">
      <h3>Generated Content:</h3>
      <div class="content-output">
        {{ generatedContent }}
      </div>
    </div>
  </div>
</template>

