  <boltAction type="file" filePath="src/components/NovelList.vue">
<script setup lang="ts">
defineProps<{
  novels: any[]
  searchQuery: string
  selectedCategory: string
}>()

const emit = defineEmits(['select'])

function filteredNovels(novels: any[], searchQuery: string, selectedCategory: string) {
  return novels.filter(novel => {
    const matchesSearch = novel.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                         novel.author.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesCategory = selectedCategory === 'all' || novel.category === selectedCategory
    return matchesSearch && matchesCategory
  })
}
</script>

<template>
  <div class="novel-list">
    <div 
      v-for="novel in filteredNovels(novels, searchQuery, selectedCategory)" 
      :key="novel.id" 
      class="novel-card"
      @click="emit('select', novel)"
    >
      <h3>{{ novel.title }}</h3>
      <p class="author">By {{ novel.author }}</p>
      <p class="category">{{ novel.category }}</p>
      <p class="description">{{ novel.description }}</p>
