<script setup lang="ts">
import { ref, computed } from 'vue'

const inputText = ref('')
const selectedEngines = ref<string[]>(['Google', 'DeepL'])
const isLoading = ref(false)
const translations = ref<Record<string, string>>({})
const translationTime = ref<Record<string, number>>({})

const engines = [
  { name: 'Google', color: '#4285F4' },
  { name: 'DeepL', color: '#0D2B4E' },
  { name: 'Microsoft', color: '#7FBA00' },
  { name: 'Amazon', color: '#FF9900' }
]

const translate = async () => {
  if (!inputText.value.trim()) return

  isLoading.value = true
  translations.value = {}
  translationTime.value = {}

  for (const engine of selectedEngines.value) {
    const startTime = performance.now()

    // Simulate API call with timeout
    await new Promise(resolve => setTimeout(resolve, 500 + Math.random() * 1000))

    const endTime = performance.now()
    translationTime.value[engine] = endTime - startTime

    // Mock translation results
    translations.value[engine] = mockTranslate(inputText.value, engine)
  }

  isLoading.value = false
}

const mockTranslate = (text: string, engine: string): string => {
  const mockTranslations: Record<string, string> = {
    Google: `[Google] ${text} translated`,
    DeepL: `[DeepL] ${text} translated`,
    Microsoft: `[Microsoft] ${text} translated`,
    Amazon: `[Amazon] ${text} translated`
  }
  return mockTranslations[engine] || text
}

const averageTime = computed(() => {
  const times = Object.values(translationTime.value)
  if (times.length === 0) return 0
  return times.reduce((a, b) => a + b, 0) / times.length
})
</script>

<template>
  <div class="translation-tool">
    <h1>Translation Comparison Tool</h1>

    <div class="input-section">
      <textarea 
        v-model="inputText" 
        placeholder="Enter text to translate..."
        class="text-input"
      ></textarea>

      <div class="engine-selection">
        <h3>Select Translation Engines:</h3>
        <div class="engine-options">
          <label v-for="engine in engines" :key="engine.name" class="engine-option">
            <input 
              type="checkbox" 
              v-model="selectedEngines" 
              :value="engine.name"
            >
            <span :style="{ color: engine.color }">{{ engine.name }}</span>
          </label>
        </div>
      </div>

      <button 
        @click="translate" 
        :disabled="isLoading || !inputText.trim()"
        class="translate-button"
      >
        {{ isLoading ? 'Translating...' : 'Compare Translations' }}
      </button>
    </div>

    <div v-if="Object.keys(translations).length > 0" class="results-section">
      <h2>Translation Results</h2>

      <div class="stats">
        <p>Average translation time: {{ averageTime.toFixed(2) }}ms</p>
      </div>

      <div class="translation-results">
        <div 
          v-for="(translation, engine) in translations" 
          :key="engine"
          class="translation-card"
        >
          <h3 :style="{ color: engines.find(e => e.name === engine)?.color }">
            {{ engine }}
          </h3>
          <p>Time: {{ translationTime[engine].toFixed(2) }}ms</p>
          <div class="translation-text">{{ translation }}</div>
        </div>
      </div>
    </div>
  </div>
</template>

