<script setup lang="ts">
import { ref, computed } from 'vue'
import ContentEditor from './ContentEditor.vue'
import ContentList from './ContentList.vue'

const props = defineProps(['user'])
const emit = defineEmits(['logout'])

const contents = ref([
  { id: 1, title: 'First Post', category: 'News', content: 'This is the first post content', createdAt: new Date() },
  { id: 2, title: 'Second Post', category: 'Tutorial', content: 'This is the second post content', createdAt: new Date() }
])

const selectedContent = ref(null)
const searchQuery = ref('')
const selectedCategory = ref('All')

const categories = computed(() => {
  const cats = new Set(contents.value.map(c => c.category))
  return ['All', ...cats]
})

const filteredContents = computed(() => {
  return contents.value.filter(content => {
    const matchesSearch = content.title.toLowerCase().includes(searchQuery.value.toLowerCase()) || 
                         content.content.toLowerCase().includes(searchQuery.value.toLowerCase())
    const matchesCategory = selectedCategory.value === 'All' || 
                           content.category === selectedCategory.value
    return matchesSearch && matchesCategory
  })
})

const handleCreate = () => {
  selectedContent.value = { 
    id: null, 
    title: '', 
    category: '', 
    content: '' 
  }
}

const handleEdit = (content) => {
  selectedContent.value = { ...content }
}

const handleDelete = (id) => {
  contents.value = contents.value.filter(c => c.id !== id)
}

const handleSave = (content) => {
  if (content.id) {
    // Update existing
    const index = contents.value.findIndex(c => c.id === content.id)
    contents.value[index] = content
  } else {
    // Create new
    content.id = Date.now()
    content.createdAt = new Date()
    contents.value.push(content)
  }
  selectedContent.value = null
}
</script>

