<script setup lang="ts">
import { ref } from 'vue'
import TemplateList from './TemplateList.vue'
import TemplateEditor from './TemplateEditor.vue'
import TemplatePreview from './TemplatePreview.vue'

const props = defineProps<{
  username: string
}>()

const emit = defineEmits(['logout'])

const templates = ref([
  { id: 1, name: 'Default Template', content: '<div>Default content</div>' },
  { id: 2, name: 'Marketing Email', content: '<div>Marketing content</div>' }
])

const selectedTemplate = ref(null)
const isEditing = ref(false)
const isPreviewing = ref(false)

const handleLogout = () => {
  emit('logout')
}

const addTemplate = () => {
  const newId = templates.value.length ? Math.max(...templates.value.map(t => t.id)) + 1 : 1
  templates.value.push({
    id: newId,
    name: `New Template ${newId}`,
    content: '<div>New template content</div>'
  })
}

const editTemplate = (template) => {
  selectedTemplate.value = template
  isEditing.value = true
}

const deleteTemplate = (id) => {
  templates.value = templates.value.filter(t => t.id !== id)
}

const previewTemplate = (template) => {
  selectedTemplate.value = template
  isPreviewing.value = true
}

const saveTemplate = (updatedTemplate) => {
  const index = templates.value.findIndex(t => t.id === updatedTemplate.id)
  if (index !== -1) {
    templates.value[index] = updatedTemplate
  }
  isEditing.value = false
}

const cancelEdit = () => {
  isEditing.value = false
}

const closePreview = () => {
  isPreviewing.value = false
}
</script>

<template>
  <div class="dashboard">
    <header class="dashboard-header">
      <h2>Welcome, {{ username }}</h2>
      <button @click="handleLogout" class="logout-button">Logout</button>
    </header>

    <div class="dashboard-content">
      <div class="sidebar">
        <button @click="addTemplate" class="add-button">Add Template</button>
        <TemplateList 
          :templates="templates"
          @edit="editTemplate"
          @delete="deleteTemplate"
          @preview="previewTemplate"
        />
      </div>

      <div class="main-content">
        <div v-if="!isEditing && !isPreviewing" class="welcome-message">
          <h3>Template Management System</h3>
          <p>Select a template to edit or preview, or create a new one.</p>
        </div>

        <TemplateEditor 
          v-if="isEditing"
          :template="selectedTemplate"
          @save="saveTemplate"
          @cancel="cancelEdit"
        />

        <TemplatePreview 
          v-if="isPreviewing"
          :template="selectedTemplate"
          @close="closePreview"
        />
      </div>
    </div>
  </div>
</template>

