<script setup lang="ts">
import { ref } from 'vue'

const inventory = ref([
  { id: 1, name: 'Steel', quantity: 500, unit: 'kg', location: 'A1' },
  { id: 2, name: 'Wood', quantity: 200, unit: 'pieces', location: 'B2' },
  { id: 3, name: 'Plastic', quantity: 300, unit: 'kg', location: 'C3' },
  { id: 4, name: 'Chair', quantity: 45, unit: 'pieces', location: 'D4' },
  { id: 5, name: 'Table', quantity: 18, unit: 'pieces', location: 'E5' }
])

const newItem = ref({
  name: '',
  quantity: 0,
  unit: '',
  location: ''
})

const addItem = () => {
  if (newItem.value.name && newItem.value.quantity >= 0 && newItem.value.unit && newItem.value.location) {
    inventory.value.push({
      id: inventory.value.length + 1,
      name: newItem.value.name,
      quantity: newItem.value.quantity,
      unit: newItem.value.unit,
      location: newItem.value.location
    })
    newItem.value = {
      name: '',
      quantity: 0,
      unit: '',
      location: ''
    }
  }
}

const updateInventory = (id: number, change: number) => {
  const item = inventory.value.find(item => item.id === id)
  if (item) {
    item.quantity += change
    if (item.quantity < 0) item.quantity = 0
  }
}
</script>

