<script setup lang="ts">
import { ref, computed } from 'vue'

// Sample data for demonstration
const productionData = ref([
  { month: 'Jan', chairs: 120, tables: 45, cabinets: 20 },
  { month: 'Feb', chairs: 150, tables: 50, cabinets: 25 },
  { month: 'Mar', chairs: 180, tables: 60, cabinets: 30 },
  { month: 'Apr', chairs: 200, tables: 70, cabinets: 35 },
  { month: 'May', chairs: 220, tables: 80, cabinets: 40 }
])

const inventoryData = ref([
  { name: 'Steel', current: 500, min: 300 },
  { name: 'Wood', current: 200, min: 150 },
  { name: 'Plastic', current: 300, min: 200 }
])

const procurementData = ref([
  { month: 'Jan', orders: 15, delivered: 12 },
  { month: 'Feb', orders: 18, delivered: 15 },
  { month: 'Mar', orders: 20, delivered: 18 },
  { month: 'Apr', orders: 22, delivered: 20 },
  { month: 'May', orders: 25, delivered: 22 }
])

const totalProduction = computed(() => {
  return productionData.value.reduce((acc, curr) => {
    return acc + curr.chairs + curr.tables + curr.cabinets
  }, 0)
})

const inventoryStatus = computed(() => {
  return inventoryData.value.map(item => {
    return {
      name: item.name,
      status: item.current >= item.min ? 'OK' : 'Low',
      percentage: Math.round((item.current / item.min) * 100)
    }
  })
})

const deliveryRate = computed(() => {
  const totalOrders = procurementData.value.reduce((acc, curr) => acc + curr.orders, 0)
  const totalDelivered = procurementData.value.reduce((acc, curr) => acc + curr.delivered, 0)
  return Math.round((totalDelivered / totalOrders) * 100)
})
</script>

