// Melon backend layer
interface SalesRecord {
  id: string;
  product: string;
  quantity: number;
  price: number;
  date: Date;
  status: 'sold' | 'returned' | 'inventory';
}

class SalesDB {
  private db: SalesRecord[] = [];

  addRecord(record: Omit<SalesRecord, 'id'>) {
    const newRecord = {
      ...record,
      id: crypto.randomUUID(),
      date: new Date()
    };
    this.db.push(newRecord);
    return newRecord;
  }

  getRecords(type?: SalesRecord['status']) {
    return type ? this.db.filter(r => r.status === type) : this.db;
  }

  getStats() {
    const totalSales = this.db
      .filter(r => r.status === 'sold')
      .reduce((sum, r) => sum + (r.price * r.quantity), 0);

    const totalReturns = this.db
      .filter(r => r.status === 'returned')
      .reduce((sum, r) => sum + (r.price * r.quantity), 0);

    return { totalSales, totalReturns };
  }
}

export const db = new SalesDB();
</boltAction>

