<boltAction type="file" filePath="public/sw.js">
const CACHE_NAME = 'erp-sales-v1';
const ASSETS = [
  '/',
  '/index.html',
  '/src/melon.js',
  '/src/components/tomato/SalesForm.js',
  '/src/components/tomato/SalesReport.js'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(ASSETS))
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => response || fetch(event.request))
  );
});
