<script setup lang="ts">
import { ref } from 'vue'

const notes = ref([
  {
    id: 1,
    content: 'Looking for someone to study with',
    contact: 'email@example.com',
    approved: true,
    price: 5
  },
  {
    id: 2,
    content: 'Want to meet new friends',
    contact: 'phone: 123-456-7890',
    approved: true,
    price: 3
  }
])

const newNote = ref({
  content: '',
  contact: ''
})

const drawnNote = ref(null)
const balance = ref(20)

function submitNote() {
  notes.value.push({
    id: notes.value.length + 1,
    content: newNote.value.content,
    contact: newNote.value.contact,
    approved: false,
    price: 0
  })
  newNote.value.content = ''
  newNote.value.contact = ''
}

function drawNote() {
  if (balance.value < 5) {
    alert('Not enough balance')
    return
  }

  const availableNotes = notes.value.filter(n => n.approved)
  if (availableNotes.length === 0) {
    alert('No notes available')
    return
  }

  const randomIndex = Math.floor(Math.random() * availableNotes.length)
  drawnNote.value = availableNotes[randomIndex]
  balance.value -= drawnNote.value.price
}
</script>

<template>
