<script setup lang="ts">
import { ref, onMounted } from 'vue'

const prayerTimes = ref({
  fajr: '05:30 AM',
  dhuhr: '01:15 PM',
  asr: '04:45 PM',
  maghrib: '07:30 PM',
  isha: '09:00 PM'
})

const currentPrayer = ref('')
const nextPrayer = ref('')

function updatePrayerTimes() {
  const now = new Date()
  const hours = now.getHours()
  const minutes = now.getMinutes()

  // Simple logic to determine current/next prayer
  if (hours < 5 || (hours === 5 && minutes < 30)) {
    currentPrayer.value = 'Isha'
    nextPrayer.value = 'Fajr'
  } else if (hours < 13 || (hours === 13 && minutes < 15)) {
    currentPrayer.value = 'Fajr'
    nextPrayer.value = 'Dhuhr'
  } else if (hours < 16 || (hours === 16 && minutes < 45)) {
    currentPrayer.value = 'Dhuhr'
    nextPrayer.value = 'Asr'
  } else if (hours < 19 || (hours === 19 && minutes < 30)) {
    currentPrayer.value = 'Asr'
    nextPrayer.value = 'Maghrib'
  } else if (hours < 21) {
    currentPrayer.value = 'Maghrib'
    nextPrayer.value = 'Isha'
  } else {
    currentPrayer.value = 'Isha'
    nextPrayer.value = 'Fajr'
  }
}

onMounted(() => {
  updatePrayerTimes()
  setInterval(updatePrayerTimes, 60000) // Update every minute
})
</script>

