    uploadDate: '2023-06-20T18:45:00',
    comments: []
  }
])

const selectedPhoto = ref<typeof photos.value[0] | null>(null)
const newComment = ref('')

function selectPhoto(photo: typeof photos.value[0]) {
  selectedPhoto.value = photo
}

function addComment() {
  if (selectedPhoto.value && newComment.value.trim()) {
    selectedPhoto.value.comments.push({
      id: Date.now(),
      author: 'You',
      text: newComment.value,
      date: new Date().toISOString().split('T')[0]
    })
    newComment.value = ''
  }
}

function sharePhoto() {
  if (selectedPhoto.value) {
    alert(`Sharing photo: ${selectedPhoto.value.title}\nURL: ${selectedPhoto.value.imageUrl}`)
  }
}
</script>

