I'll create an elegant handwriting-style resume generator with animations. Here's the implementation:

<boltArtifact id="handwriting-resume" title="Animated Handwriting Resume Generator">
<boltAction type="file" filePath="src/App.tsx">
import React, { useState, useEffect, useRef } from 'react';
import { PenLine, User, Briefcase, GraduationCap, Mail, Phone, Loader2 } from 'lucide-react';

const HandwritingResume = () => {
  const [resume, setResume] = useState({
    name: '',
    email: '',
    phone: '',
    education: '',
    experience: '',
    skills: ''
  });
  const [isAnimating, setIsAnimating] = useState(false);
  const [displayText, setDisplayText] = useState('');
  const [currentField, setCurrentField] = useState('');
  const [showThankYou, setShowThankYou] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setResume(prev => ({ ...prev, [name]: value }));
  };

  const simulateHandwriting = (text: string, field: string) => {
    setIsAnimating(true);
    setCurrentField(field);
    setDisplayText('');
    let i = 0;

    const interval = setInterval(() => {
      if (i < text.length) {
        setDisplayText(prev => prev + text.charAt(i));
        i++;
      } else {
        clearInterval(interval);
        setIsAnimating(false);
        if (field === 'skills') {
          setTimeout(() => setShowThankYou(true), 1000);
        }
      }
    }, 50);
  };

  const generateResume = () => {
    setShowThankYou(false);
    const fields = ['name', 'email', 'phone', 'education', 'experience', 'skills'];
    let delay = 0;

    fields.forEach(field => {
      setTimeout(() => {
        simulateHandwriting(resume[field as keyof typeof resume], field);
      }, delay);
      delay += (resume[field as keyof typeof resume].length * 50) + 1000;
    });
  };

  useEffect(() => {
    if (canvasRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.font = '24px "Caveat", cursive';
        ctx.fillStyle = 'cornflowerblue';
        ctx.fillText(displayText, 20, 40);
      }
    }
  }, [displayText]);

  return (
    <div className="min-h-screen bg-aliceblue p-8">
      <div className="max-w-4xl mx-auto">
        <h1 className="text-4xl font-bold text-cornflowerblue mb-8 flex items-center">
          <PenLine className="mr-2" /> Handwritten Resume Generator
        </h1>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Input Form */}
          <div className="bg-white p-6 rounded-lg shadow-lg">
            <h2 className="text-2xl font-semibold text-cornflowerblue mb-4">Your Information</h2>

            <div className="space-y-4">
              <div className="flex items-center">
                <User className="text-cornflowerblue mr-2" />
                <input
                  type="text"
                  name="name"
                  value={resume.name}
                  onChange={handleChange}
                  placeholder="Full Name"
                  className="w-full p-2 border-b-2 border-cornflowerblue focus:outline-none"
                />
              </div>

              <div className="flex items-center">
                <Mail className="text-cornflowerblue mr-2" />
                <input
                  type="email"
                  name="email"
                  value={resume.email}
                  onChange={handleChange}
                  placeholder="Email"
                  className="w-full p-2 border-b-2 border-cornflowerblue focus:outline-none"
                />
              </div>

              <div className="flex items-center">
                <Phone className="text-cornflowerblue mr-2" />
                <input
                  type="tel"
                  name="phone"
                  value={resume.phone}
                  onChange={handleChange}
                  placeholder="Phone"
                  className="w-full p-2 border-b-2 border-cornflowerblue focus:outline-none"
                />
              </div>

              <div className="flex items-start">
                <GraduationCap className="text-cornflowerblue mr-2 mt-1" />
                <textarea
                  name="education"
                  value={resume.education}
                  onChange={handleChange}
                  placeholder="Education (one per line)"
                  className="w-full p-2 border-b-2 border-cornflowerblue focus:outline-none min-h-[100px]"
                />
              </div>

              <div className="flex items-start">
                <Briefcase className="text-cornflowerblue mr-2 mt-1" />
                <textarea
                  name="experience"
                  value={resume.experience}
                  onChange={handleChange}
                  placeholder="Work Experience (one per line)"
                  className="w-full p-2 border-b-2 border-cornflowerblue focus:outline-none min-h-[100px]"
                />
              </div>

              <div className="flex items-start">
                <PenLine className="text-cornflowerblue mr-2 mt-1" />
                <textarea
                  name="skills"
                  value={resume.skills}
                  onChange={handleChange}
                  placeholder="Skills (comma separated)"
                  className="w-full p-2 border-b-2 border-cornflowerblue focus:outline-none min-h-[60px]"
                />
              </div>
            </div>

            <button
              onClick={generateResume}
              disabled={isAnimating}
              className="mt-6 bg-cornflowerblue text-white px-6 py-2 rounded-lg hover:bg-blue-600 transition-colors flex items-center justify-center w-full"
            >
              {isAnimating ? (
                <>
                  <Loader2 className="animate-spin mr-2" /> Generating...
                </>
              ) : (
                'Generate Handwritten Resume'
              )}
            </button>
          </div>

          {/* Output Display */}
          <div className="bg-white p-6 rounded-lg shadow-lg">
            <h2 className="text-2xl font-semibold text-cornflowerblue mb-4">Your Handwritten Resume</h2>

            <div className="relative min-h-[400px] bg-[url('https://images.unsplash.com/photo-1497633762265-9d179a990aa6?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=800&q=80')] bg-cover bg-center">
              <canvas
                ref={canvasRef}
                width="100%"
                height="400"
                className="absolute inset-0 w-full h-full"
              />

              {showThankYou && (
                <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-70">
                  <div className="text-white text-4xl font-bold animate-bounce">
                    Thank You!
                  </div>
                </div>
              )}
            </div>

            {currentField && (
              <div className="mt-4 text-sm text-gray-600">
                Currently writing: <span className="font-semibold text-cornflowerblue capitalize">{currentField}</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default HandwritingResume;
</boltAction>

