<script setup lang="ts">
import { computed } from 'vue'

const props = defineProps<{
  photos: Array<{id: string, src: string, name: string, date: Date}>,
  sortMode: 'name' | 'date' | 'custom'
}>()

const emit = defineEmits(['delete'])

const sortedPhotos = computed(() => {
  if (props.sortMode === 'name') {
    return [...props.photos].sort((a, b) => a.name.localeCompare(b.name))
  } else if (props.sortMode === 'date') {
    return [...props.photos].sort((a, b) => b.date.getTime() - a.date.getTime())
  }
  return props.photos
})
</script>

