import { ref, computed } from 'vue'

interface Job {
  id: number
  title: string
  skills: string[]
  city: string
  salary: string
  company: string
  description: string
}

const jobs = ref<Job[]>([
  {
    id: 1,
    title: 'Frontend Developer',
    skills: ['Vue.js', 'TypeScript', 'CSS'],
    city: 'Shanghai',
    salary: '¥25,000 - ¥35,000',
    company: 'Ctrip International',
    description: 'Develop and maintain Ctrip web applications using Vue.js.'
  },
  {
    id: 2,
    title: 'Backend Engineer',
    skills: ['Java', 'Spring Boot', 'MySQL'],
    city: 'Beijing',
    salary: '¥30,000 - ¥40,000',
    company: 'Ctrip Technology',
    description: 'Build scalable backend services for our travel platform.'
  },
  {
    id: 3,
    title: 'UX Designer',
    skills: ['Figma', 'User Research', 'Prototyping'],
    city: 'Guangzhou',
    salary: '¥20,000 - ¥30,000',
    company: 'Ctrip Design',
    description: 'Create intuitive user experiences for our travel products.'
  },
  {
    id: 4,
    title: 'Data Analyst',
    skills: ['Python', 'SQL', 'Tableau'],
    city: 'Shanghai',
    salary: '¥22,000 - ¥32,000',
    company: 'Ctrip Analytics',
    description: 'Analyze travel data to provide business insights.'
  }
])

const searchTerm = ref('')
const selectedCity = ref('')
const selectedSkill = ref('')

const filteredJobs = computed(() => {
  return jobs.value.filter(job => {
    const matchesSearch = job.title.toLowerCase().includes(searchTerm.value.toLowerCase()) ||
                         job.company.toLowerCase().includes(searchTerm.value.toLowerCase())
    const matchesCity = selectedCity.value ? job.city === selectedCity.value : true
    const matchesSkill = selectedSkill.value ? job.skills.includes(selectedSkill.value) : true

    return matchesSearch && matchesCity && matchesSkill
  })
})

const cities = computed(() => {
  return [...new Set(jobs.value.map(job => job.city))]
})

const skills = computed(() => {
  const allSkills = jobs.value.flatMap(job => job.skills)
  return [...new Set(allSkills)]
})

const selectedJob = ref<Job | null>(null)

const selectJob = (job: Job) => {
  selectedJob.value = job
}

const closeDetails = () => {
  selectedJob.value = null
}
</script>

