<script setup lang="ts">
import { ref, computed } from 'vue'
import RSSFeedItem from './RSSFeedItem.vue'

type Feed = {
  id: string
  url: string
  title: string
  displayTitle: boolean
  displaySummary: boolean
  displayDate: boolean
}

type DisplayMode = 'list' | 'grid' | 'card'

const feeds = ref<Feed[]>([
  {
    id: '1',
    url: 'https://example.com/feed1.xml',
    title: 'Tech News',
    displayTitle: true,
    displaySummary: true,
    displayDate: true
  },
  {
    id: '2',
    url: 'https://example.com/feed2.xml',
    title: 'Sports Updates',
    displayTitle: true,
    displaySummary: false,
    displayDate: true
  }
])

const newFeed = ref<Omit<Feed, 'id'>>({
  url: '',
  title: '',
  displayTitle: true,
  displaySummary: true,
  displayDate: true
})

const displayMode = ref<DisplayMode>('card')
const editingFeedId = ref<string | null>(null)

const addFeed = () => {
  if (!newFeed.value.url || !newFeed.value.title) return

  feeds.value.push({
    id: Date.now().toString(),
    ...newFeed.value
  })

  newFeed.value = {
    url: '',
    title: '',
    displayTitle: true,
    displaySummary: true,
    displayDate: true
  }
}

const deleteFeed = (id: string) => {
  feeds.value = feeds.value.filter(feed => feed.id !== id)
}

const startEdit = (feed: Feed) => {
  editingFeedId.value = feed.id
}

const saveEdit = () => {
  editingFeedId.value = null
}

const containerClasses = computed(() => {
  return {
    'list-view': displayMode.value === 'list',
    'grid-view': displayMode.value === 'grid',
    'card-view': displayMode.value === 'card'
  }
})
</script>

<template>
  <div class="rss-manager">
    <h1>RSS Feed Manager</h1>

    <div class="controls">
      <div class="display-options">
        <button @click="displayMode = 'list'" :class="{ active: displayMode === 'list' }">List</button>
        <button @click="displayMode = 'grid'" :class="{ active: displayMode === 'grid' }">Grid</button>
        <button @click="displayMode = 'card'" :class="{ active: displayMode === 'card' }">Card</button>
      </div>

      <div class="add-feed">
        <input v-model="newFeed.url" placeholder="RSS Feed URL">
        <input v-model="newFeed.title" placeholder="Feed Title">
        <button @click="addFeed">Add Feed</button>
      </div>
    </div>

    <div class="feeds-container" :class="containerClasses">
      <div v-for="feed in feeds" :key="feed.id" class="feed-item">
        <RSSFeedItem 
          :feed="feed" 
          :display-mode="displayMode"
          :is-editing="editingFeedId === feed.id"
          @delete="deleteFeed(feed.id)"
          @edit="startEdit(feed)"
          @save="saveEdit"
        />
      </div>
    </div>
  </div>
</template>

