const props = defineProps(['user'])
const emit = defineEmits(['logout'])

const feeds = ref([])
const categories = ref(['News', 'Technology', 'Sports', 'Entertainment'])
const selectedCategory = ref('')
const priorityFilter = ref('all')
const searchQuery = ref('')

const filteredFeeds = computed(() => {
  return feeds.value.filter(feed => {
    const matchesCategory = !selectedCategory.value || feed.category === selectedCategory.value
    const matchesPriority = priorityFilter.value === 'all' || 
                          (priorityFilter.value === 'high' && feed.priority === 'high') ||
                          (priorityFilter.value === 'medium' && feed.priority === 'medium') ||
                          (priorityFilter.value === 'low' && feed.priority === 'low')
    const matchesSearch = !searchQuery.value || 
                         feed.title.toLowerCase().includes(searchQuery.value.toLowerCase()) ||
                         feed.description.toLowerCase().includes(searchQuery.value.toLowerCase())
    return matchesCategory && matchesPriority && matchesSearch
  })
})

