import { useState, useEffect, useRef } from 'react'
import { Loader2, RefreshCw, ChevronDown, MessageSquare, Repeat2, Heart, Share2 } from 'lucide-react'

type Tweet = {
  id: string
  username: string
  name: string
  avatar: string
  content: string
  timestamp: string
  likes: number
  retweets: number
  replies: number
  hashtags: string[]
}

const hashtags = ['technology', 'programming', 'reactjs', 'javascript', 'webdev']

export default function App() {
  const [tweets, setTweets] = useState<Tweet[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedHashtag, setSelectedHashtag] = useState(hashtags[0])
  const [isRefreshing, setIsRefreshing] = useState(false)
  const feedRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    fetchTweets()
    const interval = setInterval(fetchTweets, 30000)
    return () => clearInterval(interval)
  }, [selectedHashtag])

  const fetchTweets = async () => {
    setIsRefreshing(true)
    try {
      // Simulate API call with mock data
      const mockTweets = generateMockTweets(selectedHashtag)
      setTweets(prev => [...mockTweets, ...prev].slice(0, 50))
    } catch (error) {
      console.error('Error fetching tweets:', error)
    } finally {
      setLoading(false)
      setIsRefreshing(false)
    }
  }

  const generateMockTweets = (hashtag: string): Tweet[] => {
    const mockAvatars = [
      'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200',
      'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200',
      'https://images.unsplash.com/photo-1531123897727-8f129e1688ce?w=200',
      'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=200',
      'https://images.unsplash.com/photo-1529626455594-4ff0802cfb7e?w=200',
    ]

    const mockNames = ['Alex Johnson', 'Taylor Swift', 'Chris Evans', 'Emma Watson', 'John Doe']
    const mockUsernames = ['alexj', 'tswift', 'cevans', 'ewatson', 'johndoe']

    return Array.from({ length: 5 }, (_, i) => ({
      id: `tweet-${Date.now()}-${i}`,
      username: mockUsernames[i % 5],
      name: mockNames[i % 5],
      avatar: mockAvatars[i % 5],
      content: `This is a mock tweet about #${hashtag}. Lorem ipsum dolor sit amet, consectetur adipiscing elit. ${i % 3 === 0 ? 'Check out this cool feature!' : ''}`,
      timestamp: `${Math.floor(Math.random() * 60)}m ago`,
      likes: Math.floor(Math.random() * 1000),
      retweets: Math.floor(Math.random() * 500),
      replies: Math.floor(Math.random() * 200),
      hashtags: [hashtag, ...hashtags.filter(h => h !== hashtag).slice(0, 2)],
    }))
  }

  const loadMoreTweets = () => {
    fetchTweets()
  }

  const handleHashtagChange = (hashtag: string) => {
    setSelectedHashtag(hashtag)
    setTweets([])
    setLoading(true)
  }

  return (
    <div className="min-h-screen bg-[#afeeee] p-4">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-3xl font-bold text-[#008b8b] mb-6">Twitter Feed Viewer</h1>

        <div className="mb-6 flex flex-wrap gap-2">
          {hashtags.map(hashtag => (
            <button
              key={hashtag}
              onClick={() => handleHashtagChange(hashtag)}
              className={`px-4 py-2 rounded-full font-medium ${selectedHashtag === hashtag ? 'bg-[#008b8b] text-white' : 'bg-white text-[#008b8b]'}`}
            >
              #{hashtag}
            </button>
          ))}
        </div>

        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-semibold text-[#008b8b]">#{selectedHashtag}</h2>
          <button 
            onClick={fetchTweets}
            disabled={isRefreshing}
            className="flex items-center gap-2 text-[#008b8b] hover:text-[#006666]"
          >
            {isRefreshing ? <Loader2 className="animate-spin" /> : <RefreshCw />}
            Refresh
          </button>
        </div>

        <div 
          ref={feedRef}
          className="space-y-4 overflow-y-auto max-h-[70vh] pr-2"
          onScroll={(e) => {
            const { scrollTop, scrollHeight, clientHeight } = e.currentTarget
            if (scrollHeight - scrollTop === clientHeight) {
              loadMoreTweets()
            }
          }}
        >
          {loading ? (
            <div className="flex justify-center items-center h-40">
              <Loader2 className="animate-spin text-[#008b8b] h-8 w-8" />
            </div>
          ) : (
            tweets.map(tweet => (
              <TweetCard key={tweet.id} tweet={tweet} />
            ))
          )}

          {!loading && (
            <button 
              onClick={loadMoreTweets}
              className="w-full py-3 bg-[#008b8b] text-white rounded-lg flex items-center justify-center gap-2 hover:bg-[#006666]"
            >
              <ChevronDown />
              Load More Tweets
            </button>
          )}
        </div>
      </div>
    </div>
  )
}

function TweetCard({ tweet }: { tweet: Tweet }) {
  return (
    <div className="bg-white rounded-xl shadow-md p-4 border border-[#008b8b]">
      <div className="flex gap-3">
        <img 
          src={tweet.avatar} 
          alt={`${tweet.username}'s avatar`} 
          className="w-12 h-12 rounded-full object-cover"
        />
        <div className="flex-1">
          <div className="flex items-center gap-1">
            <span className="font-bold text-[#008b8b]">{tweet.name}</span>
            <span className="text-gray-500">@{tweet.username}</span>
            <span className="text-gray-500">·</span>
            <span className="text-gray-500">{tweet.timestamp}</span>
          </div>
          <p className="mt-1 mb-2">
            {tweet.content.split(' ').map((word, i) => 
              word.startsWith('#') ? (
                <span key={i} className="text-[#008b8b] hover:underline cursor-pointer"> {word} </span>
              ) : (
                <span key={i}> {word} </span>
              )
            )}
          </p>
          <div className="flex justify-between mt-3 text-gray-500">
            <button className="flex items-center gap-1 hover:text-[#008b8b]">
              <MessageSquare size={16} />
              <span>{tweet.replies}</span>
            </button>
            <button className="flex items-center gap-1 hover:text-[#008b8b]">
              <Repeat2 size={16} />
              <span>{tweet.retweets}</span>
            </button>
            <button className="flex items-center gap-1 hover:text-[#008b8b]">
              <Heart size={16} />
              <span>{tweet.likes}</span>
            </button>
            <button className="flex items-center gap-1 hover:text-[#008b8b]">
              <Share2 size={16} />
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}
