<boltAction type="file" filePath="src/stores/userStore.ts">
import { defineStore } from 'pinia'
import { useNewsStore } from './newsStore'

interface UserShare {
  id: number
  title: string
  shares: number
  clicks: number
  earnings: number
}

export const useUserStore = defineStore('user', {
  state: () => ({
    userShares: [] as UserShare[],
  }),

  getters: {
    totalShares: (state) => state.userShares.reduce((sum, item) => sum + item.shares, 0),
    totalClicks: (state) => state.userShares.reduce((sum, item) => sum + item.clicks, 0),
    totalEarnings: (state) => state.userShares.reduce((sum, item) => sum + item.earnings, 0),
  },

  actions: {
    trackShare(newsId: number) {
      const newsStore = useNewsStore()
      const newsItem = newsStore.news.find(item => item.id === newsId)

      if (!newsItem) return

      const existingShare = this.userShares.find(item => item.id === newsId)

      if (existingShare) {
        existingShare.shares++
      } else {
        this.userShares.push({
          id: newsId,
          title: newsItem.title,
          shares: 1,
          clicks: 0,
          earnings: 0
        })
      }
    },

    trackClick(shareId: string) {
      // In a real app, this would be called when someone clicks a shared link
      const share = this.userShares.find(item => item.id === parseInt(shareId))
      if (share) {
        share.clicks++
        const newsStore = useNewsStore()
        const newsItem = newsStore.news.find(item => item.id === share.id)
        if (newsItem) {
          share.earnings = share.clicks * newsItem.reward
        }
      }
    }
  }
})
</boltAction>

