<script setup lang="ts">
import { ref } from 'vue'

const emit = defineEmits(['booking-submitted'])

const formData = ref({
  name: '',
  roomType: 'single',
  checkInDate: '',
  checkOutDate: '',
  guests: 1,
  specialRequests: ''
})

const roomTypes = [
  { value: 'single', label: 'Single Room' },
  { value: 'double', label: 'Double Room' },
  { value: 'suite', label: 'Suite' },
  { value: 'deluxe', label: 'Deluxe Room' }
]

const submitBooking = () => {
  if (!formData.value.name || !formData.value.checkInDate || !formData.value.checkOutDate) {
    alert('Please fill in all required fields')
    return
  }

  const booking = {
    ...formData.value,
    id: Date.now(),
    status: 'confirmed',
    createdAt: new Date().toISOString()
  }

  emit('booking-submitted', booking)
  formData.value = {
    name: '',
    roomType: 'single',
    checkInDate: '',
    checkOutDate: '',
    guests: 1,
    specialRequests: ''
  }

  alert('Booking submitted successfully!')
}
</script>

