<script setup lang="ts">
const tickets = [
  {
    id: 1,
    name: 'Museum Entrance',
    price: 15,
    description: 'Access to all museum exhibits',
    date: '2023-11-10',
    time: '10:00-18:00'
  },
  {
    id: 2,
    name: 'City Tour',
    price: 25,
    description: 'Guided tour of historic sites',
    date: '2023-11-11',
    time: '09:00-12:00'
  },
  {
    id: 3,
    name: 'Boat Cruise',
    price: 35,
    description: 'Evening cruise with dinner',
    date: '2023-11-12',
    time: '19:00-22:00'
  }
]

const selectedTickets = ref<number[]>([])

function toggleTicket(id: number) {
  const index = selectedTickets.value.indexOf(id)
  if (index === -1) {
    selectedTickets.value.push(id)
  } else {
    selectedTickets.value.splice(index, 1)
  }
}

function bookTickets() {
  if (selectedTickets.value.length > 0) {
    alert(`Successfully booked ${selectedTickets.value.length} tickets!`)
    selectedTickets.value = []
  } else {
    alert('Please select at least one ticket')
  }
}
</script>

<template>
