<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps({
  park: {
    type: Object,
    required: true
  }
})

const comments = ref([
  { id: 1, user: 'NatureLover', text: 'Amazing views!', likes: 24, replies: [], date: '2023-05-15' },
  { id: 2, user: 'Hiker123', text: 'Great trails for all levels', likes: 15, replies: [], date: '2023-06-02' }
])

const newComment = ref('')
const replyTo = ref(null)
const replyText = ref('')

function addComment() {
  if (newComment.value.trim()) {
    comments.value.push({
      id: Date.now(),
      user: 'You',
      text: newComment.value,
      likes: 0,
      replies: [],
      date: new Date().toISOString().split('T')[0]
    })
    newComment.value = ''
  }
}

function likeComment(commentId: number) {
  const comment = comments.value.find(c => c.id === commentId)
  if (comment) comment.likes++
}

function startReply(commentId: number) {
  replyTo.value = commentId
}

function addReply() {
  if (replyText.value.trim() && replyTo.value) {
    const comment = comments.value.find(c => c.id === replyTo.value)
    if (comment) {
      comment.replies.push({
        id: Date.now(),
        user: 'You',
        text: replyText.value,
        date: new Date().toISOString().split('T')[0]
      })
      replyText.value = ''
      replyTo.value = null
    }
  }
}
</script>

<template>
  <div class="comments-container">
    <h3>Comments</h3>

    <div class="comment-form">
      <textarea v-model="newComment" placeholder="Add your comment..."></textarea>
      <button @click="addComment">Post</button>
    </div>

    <div v-for="comment in comments" :key="comment.id" class="comment">
      <div class="comment-header">
        <strong>{{ comment.user }}</strong>
        <span>{{ comment.date }}</span>
      </div>
      <p>{{ comment.text }}</p>
      <div class="comment-actions">
        <button @click="likeComment(comment.id)">👍 {{ comment.likes }}</button>
        <button @click="startReply(comment.id)">Reply</button>
      </div>

      <div v-if="replyTo === comment.id" class="reply-form">
        <textarea v-model="replyText" placeholder="Write your reply..."></textarea>
        <button @click="addReply">Post Reply</button>
      </div>

      <div v-for="reply in comment.replies" :key="reply.id" class="reply">
        <div class="comment-header">
