  <boltAction type="file" filePath="src/components/BookingCalendar.vue">
<script setup lang="ts">
import { ref, computed } from 'vue'

const checkInDate = ref<Date | null>(null)
const checkOutDate = ref<Date | null>(null)
const selectedMonth = ref(new Date().getMonth())
const selectedYear = ref(new Date().getFullYear())

const rooms = ref([
  { id: 1, name: 'Deluxe Room', price: 200, available: true },
  { id: 2, name: 'Suite', price: 350, available: true },
  { id: 3, name: 'Standard Room', price: 150, available: false }
])

const sortBy = ref<'price' | 'name'>('price')
const filterAvailable = ref(true)

const daysInMonth = computed(() => {
  return new Date(selectedYear.value, selectedMonth.value + 1, 0).getDate()
})

const firstDayOfMonth = computed(() => {
  return new Date(selectedYear.value, selectedMonth.value, 1).getDay()
})

const monthName = computed(() => {
  return new Date(selectedYear.value, selectedMonth.value).toLocaleString('default', { month: 'long' })
})

const availableRooms = computed(() => {
  let result = [...rooms.value]
  if (filterAvailable.value) {
    result = result.filter(room => room.available)
  }
  return result.sort((a, b) => {
    if (sortBy.value === 'price') return a.price - b.price
    return a.name.localeCompare(b.name)
  })
})

function selectDate(date: number) {
  const selectedDate = new Date(selectedYear.value, selectedMonth.value, date)

  if (!checkInDate.value || (checkInDate.value && checkOutDate.value)) {
    checkInDate.value = selectedDate
    checkOutDate.value = null
  } else if (selectedDate > checkInDate.value) {
    checkOutDate.value = selectedDate
  } else {
    checkOutDate.value = checkInDate.value
    checkInDate.value = selectedDate
  }
}

function isSelected(date: number) {
  const currentDate = new Date(selectedYear.value, selectedMonth.value, date)
  if (!checkInDate.value) return false
  if (!checkOutDate.value) return currentDate.getTime() === checkInDate.value.getTime()

  return currentDate >= checkInDate.value && currentDate <= checkOutDate.value
}

function changeMonth(offset: number) {
  const newDate = new Date(selectedYear.value, selectedMonth.value + offset, 1)
  selectedMonth.value = newDate.getMonth()
  selectedYear.value = newDate.getFullYear()
}
</script>

<template>
  <div class="booking-widget">
    <div class="calendar-container">
      <div class="calendar-header">
        <button @click="changeMonth(-1)">←</button>
        <h2>{{ monthName }} {{ selectedYear }}</h2>
        <button @click="changeMonth(1)">→</button>
      </div>

      <div class="calendar-grid">
        <div v-for="day in ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']" 
             :key="day" class="day-header">
          {{ day }}
        </div>

        <div v-for="i in firstDayOfMonth" :key="'empty-' + i" class="empty-day"></div>

        <button 
          v-for="date in daysInMonth" 
          :key="date"
          @click="selectDate(date)"
          :class="{
            'calendar-day': true,
            'selected': isSelected(date),
            'check-in': checkInDate?.getDate() === date && checkInDate?.getMonth() === selectedMonth,
            'check-out': checkOutDate?.getDate() === date && checkOutDate?.getMonth() === selectedMonth
          }"
        >
          {{ date }}
        </button>
      </div>

      <div class="date-selection">
        <div>
          <strong>Check-in:</strong> {{ checkInDate?.toLocaleDateString() || 'Not selected' }}
        </div>
        <div>
          <strong>Check-out:</strong> {{ checkOutDate?.toLocaleDateString() || 'Not selected' }}
        </div>
      </div>
    </div>

    <div class="rooms-container">
      <div class="filters">
        <label>
          <input type="checkbox" v-model="filterAvailable" />
          Show only available rooms
        </label>
        <select v-model="sortBy">
          <option value="price">Sort by price</option>
          <option value="name">Sort by name</option>
        </select>
      </div>

      <div class="room-list">
        <div v-for="room in availableRooms" :key="room.id" class="room-card">
          <h3>{{ room.name }}</h3>
          <p>Price: ${{ room.price }}/night</p>
          <p :class="{ 'available': room.available, 'unavailable': !room.available }">
            {{ room.available ? 'Available' : 'Booked' }}
          </p>
          <button :disabled="!room.available">Book Now</button>
        </div>
      </div>
    </div>
  </div>
</template>

