    capacity: 4,
    amenities: ['Pool', 'WiFi', 'AC', 'Kitchen', 'Mountain View'],
    image: 'https://example.com/villa3.jpg'
  }
])

const filteredVillas = ref([...villas.value])

watch(() => props.searchParams, () => {
  // In a real app, this would be an API call
