import React, { useState, useEffect, useRef } from 'react';
import { Play, Pause, RotateCcw, Trophy } from 'lucide-react';

const App = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [gameState, setGameState] = useState<'ready' | 'playing' | 'paused' | 'gameOver'>('ready');
  const [score, setScore] = useState(0);
  const [highScore, setHighScore] = useState(0);
  const [level, setLevel] = useState(1);

  // Game elements
  const [player, setPlayer] = useState({
    x: 50,
    y: 300,
    width: 40,
    height: 60,
    velocityY: 0,
    jumping: false
  });

  const [rocks, setRocks] = useState<Array<{
    x: number,
    y: number,
    width: number,
    height: number
  }>>([]);

  const [obstacles, setObstacles] = useState<Array<{
    x: number,
    y: number,
    width: number,
    height: number
  }>>([]);

  const [collectibles, setCollectibles] = useState<Array<{
    x: number,
    y: number,
    width: number,
    height: number,
    collected: boolean
  }>>([]);

  const gameLoopRef = useRef<number>();
  const canvasWidth = 800;
  const canvasHeight = 600;
  const gravity = 0.5;
  const jumpForce = -12;

  // Initialize game
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Initial setup
    canvas.width = canvasWidth;
    canvas.height = canvasHeight;

    // Generate initial rocks
    generateRocks();
    generateObstacles();
    generateCollectibles();

    return () => {
      if (gameLoopRef.current) {
        cancelAnimationFrame(gameLoopRef.current);
      }
    };
  }, []);

  // Game loop
  useEffect(() => {
    if (gameState !== 'playing') return;

    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const gameLoop = () => {
      // Clear canvas
      ctx.fillStyle = '#f8e5e5'; // Pale rose
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Update player
      let newPlayer = {...player};
      newPlayer.velocityY += gravity;
      newPlayer.y += newPlayer.velocityY;

      // Ground collision
      if (newPlayer.y + newPlayer.height > canvas.height) {
        newPlayer.y = canvas.height - newPlayer.height;
        newPlayer.velocityY = 0;
        newPlayer.jumping = false;
      }

      // Rock collision (climbing)
      let onRock = false;
      rocks.forEach(rock => {
        if (
          newPlayer.x + newPlayer.width > rock.x &&
          newPlayer.x < rock.x + rock.width &&
          newPlayer.y + newPlayer.height >= rock.y &&
          newPlayer.y + newPlayer.height <= rock.y + 10
        ) {
          onRock = true;
          newPlayer.y = rock.y - newPlayer.height;
          newPlayer.velocityY = 0;
          newPlayer.jumping = false;
        }
      });

      // Obstacle collision (game over)
      obstacles.forEach(obstacle => {
        if (
          newPlayer.x + newPlayer.width > obstacle.x &&
          newPlayer.x < obstacle.x + obstacle.width &&
          newPlayer.y + newPlayer.height > obstacle.y &&
          newPlayer.y < obstacle.y + obstacle.height
        ) {
          setGameState('gameOver');
          if (score > highScore) {
            setHighScore(score);
          }
        }
      });

      // Collectible collision
      setCollectibles(prevCollectibles => 
        prevCollectibles.map(collectible => {
          if (
            !collectible.collected &&
            newPlayer.x + newPlayer.width > collectible.x &&
            newPlayer.x < collectible.x + collectible.width &&
            newPlayer.y + newPlayer.height > collectible.y &&
            newPlayer.y < collectible.y + collectible.height
          ) {
            setScore(s => s + 10);
            return {...collectible, collected: true};
          }
          return collectible;
        })
      );

      // Level progression
      if (score >= level * 50) {
        setLevel(l => l + 1);
        generateObstacles();
        generateCollectibles();
      }

      // Update rocks position (scrolling)
      setRocks(prevRocks => 
        prevRocks.map(rock => ({
          ...rock,
          x: rock.x - 2
        })).filter(rock => rock.x + rock.width > 0)
      );

      // Update obstacles position
      setObstacles(prevObstacles => 
        prevObstacles.map(obstacle => ({
          ...obstacle,
          x: obstacle.x - 3
        })).filter(obstacle => obstacle.x + obstacle.width > 0)
      );

      // Update collectibles position
      setCollectibles(prevCollectibles => 
        prevCollectibles.map(collectible => ({
          ...collectible,
          x: collectible.x - 2
        })).filter(collectible => collectible.x + collectible.width > 0)
      );

      // Generate new rocks when needed
      if (rocks.length < 5 || rocks[rocks.length - 1].x < canvas.width - 300) {
        generateRocks();
      }

      setPlayer(newPlayer);

      // Draw player
      ctx.fillStyle = '#800000'; // Maroon
      ctx.fillRect(newPlayer.x, newPlayer.y, newPlayer.width, newPlayer.height);

      // Draw rocks
      rocks.forEach(rock => {
        ctx.fillStyle = '#800000';
        ctx.fillRect(rock.x, rock.y, rock.width, rock.height);
      });

      // Draw obstacles
      obstacles.forEach(obstacle => {
        ctx.fillStyle = '#800000';
        ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
      });

      // Draw collectibles
      collectibles.forEach(collectible => {
        if (!collectible.collected) {
          ctx.fillStyle = '#800000';
          ctx.beginPath();
          ctx.arc(
            collectible.x + collectible.width / 2,
            collectible.y + collectible.height / 2,
            collectible.width / 2,
            0,
            Math.PI * 2
          );
          ctx.fill();
        }
      });

      // Draw UI
      ctx.fillStyle = '#800000';
      ctx.font = '20px Arial';
      ctx.fillText(`Score: ${score}`, 20, 30);
      ctx.fillText(`High Score: ${highScore}`, 20, 60);
      ctx.fillText(`Level: ${level}`, 20, 90);

      gameLoopRef.current = requestAnimationFrame(gameLoop);
    };

    gameLoopRef.current = requestAnimationFrame(gameLoop);

    return () => {
      if (gameLoopRef.current) {
        cancelAnimationFrame(gameLoopRef.current);
      }
    };
  }, [gameState, player, rocks, obstacles, collectibles, score, highScore, level]);

  // Generate rocks
  const generateRocks = () => {
    const newRocks = [...rocks];
    const lastRock = newRocks[newRocks.length - 1];
    const startX = lastRock ? lastRock.x + lastRock.width + Math.random() * 200 + 100 : 0;

    for (let i = 0; i < 3; i++) {
      const width = Math.random() * 100 + 50;
      const height = Math.random() * 30 + 20;
      const y = canvasHeight - height - (Math.random() * 100);

      newRocks.push({
        x: startX + (i * (width + 50)),
        y,
        width,
        height
      });
    }

    setRocks(newRocks);
  };

  // Generate obstacles
  const generateObstacles = () => {
    const newObstacles = [...obstacles];
    const lastObstacle = newObstacles[newObstacles.length - 1];
    const startX = lastObstacle ? lastObstacle.x + lastObstacle.width + Math.random() * 300 + 200 : 400;

    for (let i = 0; i < 2; i++) {
      const width = Math.random() * 40 + 20;
      const height = Math.random() * 100 + 50;
      const y = canvasHeight - height - (Math.random() * 200);

      newObstacles.push({
        x: startX + (i * (width + 150)),
        y,
        width,
        height
      });
    }

    setObstacles(newObstacles);
  };

  // Generate collectibles
  const generateCollectibles = () => {
    const newCollectibles = [...collectibles];
    const lastCollectible = newCollectibles[newCollectibles.length - 1];
    const startX = lastCollectible ? lastCollectible.x + lastCollectible.width + Math.random() * 200 + 100 : 300;

    for (let i = 0; i < 3; i++) {
      const size = 15;
      const y = Math.random() * (canvasHeight - 200) + 50;

      newCollectibles.push({
        x: startX + (i * 150),
        y,
        width: size,
        height: size,
        collected: false
      });
    }

    setCollectibles(newCollectibles);
  };

  // Handle keyboard input
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (gameState === 'playing') {
        if ((e.key === ' ' || e.key === 'ArrowUp') && !player.jumping) {
          setPlayer(p => ({
