<script setup lang="ts">
import { ref } from 'vue'

const sets = ref([
  { id: 1, name: 'Ocean Collection', price: 50, image: '🌊' },
  { id: 2, name: 'Forest Collection', price: 50, image: '🌲' },
  { id: 3, name: 'Space Collection', price: 75, image: '🚀' }
])

const selectedSet = ref<number | null>(null)
const luckyCoins = ref(200)
const result = ref<string | null>(null)

const openBlindBox = () => {
  if (selectedSet.value === null) {
    result.value = 'Please select a set first!'
    return
  }

  const set = sets.value.find(s => s.id === selectedSet.value)
  if (!set) return

  if (luckyCoins.value < set.price) {
    result.value = 'Not enough lucky coins!'
    return
  }

  luckyCoins.value -= set.price

  // Simulate getting a random fragment
  const fragments = ['A', 'B', 'C', 'D', 'E']
  const randomFragment = fragments[Math.floor(Math.random() * fragments.length)]

  result.value = `You got fragment ${randomFragment} from ${set.name}!`
}
</script>

