import React, { useState, useEffect } from 'react';
import { Clock, Trophy, Info, Play } from 'lucide-react';

type Difference = {
  x: number;
  y: number;
  found: boolean;
};

const Game: React.FC = () => {
  const [gameStarted, setGameStarted] = useState(false);
  const [timeLeft, setTimeLeft] = useState(120);
  const [differences, setDifferences] = useState<Difference[]>([
    { x: 15, y: 30, found: false },
    { x: 70, y: 45, found: false },
    { x: 25, y: 65, found: false },
    { x: 80, y: 25, found: false },
    { x: 50, y: 75, found: false },
    { x: 30, y: 20, found: false },
    { x: 65, y: 60, found: false },
  ]);
  const [showRules, setShowRules] = useState(false);
  const [gameOver, setGameOver] = useState(false);
  const [score, setScore] = useState(0);

  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (gameStarted && timeLeft > 0 && !gameOver) {
      timer = setInterval(() => {
        setTimeLeft(prev => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      setGameOver(true);
    }
    return () => clearInterval(timer);
  }, [gameStarted, timeLeft, gameOver]);

  const handleImageClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!gameStarted || gameOver) return;

    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    const updatedDifferences = differences.map(diff => {
      if (
        !diff.found &&
        Math.abs(diff.x - x) < 5 &&
        Math.abs(diff.y - y) < 5
      ) {
        setScore(prev => prev + 1);
        return { ...diff, found: true };
      }
      return diff;
    });

    setDifferences(updatedDifferences);

    if (updatedDifferences.every(diff => diff.found)) {
      setGameOver(true);
    }
  };

  const startGame = () => {
    setGameStarted(true);
    setTimeLeft(120);
    setDifferences(differences.map(d => ({ ...d, found: false })));
    setGameOver(false);
    setScore(0);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-yellow-100 to-yellow-300 flex flex-col items-center justify-center p-4">
      <h1 className="text-4xl font-bold text-yellow-800 mb-6">Mr. Bean Spot the Difference</h1>

      {!gameStarted ? (
        <div className="bg-yellow-50 p-8 rounded-lg shadow-lg max-w-md w-full text-center">
          <h2 className="text-2xl font-semibold text-yellow-700 mb-4">Welcome!</h2>
          <p className="text-yellow-800 mb-6">
            Find all 7 differences between the two Mr. Bean images before time runs out!
          </p>
          <button
            onClick={startGame}
            className="bg-yellow-500 hover:bg-yellow-600 text-white font-bold py-3 px-6 rounded-full flex items-center justify-center mx-auto transition-all"
          >
            <Play className="mr-2" /> Start Game
          </button>
          <button
            onClick={() => setShowRules(true)}
            className="mt-4 text-yellow-700 hover:text-yellow-900 flex items-center justify-center mx-auto"
          >
            <Info className="mr-1" /> How to Play
          </button>
        </div>
      ) : (
        <div className="w-full max-w-4xl">
          <div className="flex justify-between items-center mb-4">
            <div className="flex items-center bg-yellow-100 px-4 py-2 rounded-full">
              <Clock className="text-yellow-700 mr-2" />
