<script setup lang="ts">
import { ref, computed } from 'vue'
import NavBar from '../components/NavBar.vue'
import ChickenPen from '../components/ChickenPen.vue'
import TaskList from '../components/TaskList.vue'
import Marketplace from '../components/Marketplace.vue'

const props = defineProps({
  user: {
    type: Object,
    required: true
  }
})

const emit = defineEmits(['logout'])

const activeTab = ref('chickens')
const feed = ref(10)
const eggs = ref(0)
const chickens = ref([
  { id: 1, name: 'Clucky', fed: false },
  { id: 2, name: 'Henrietta', fed: false }
])

const feedChicken = (id: number) => {
  if (feed.value > 0) {
    const chicken = chickens.value.find(c => c.id === id)
    if (chicken) {
      chicken.fed = true
      feed.value--
    }
  }
}

const collectEggs = () => {
  const fedChickens = chickens.value.filter(c => c.fed).length
  eggs.value += fedChickens
  chickens.value.forEach(c => c.fed = false)
}
</script>

<template>
  <div class="farm-view">
    <NavBar 
      :user="props.user" 
      :activeTab="activeTab"
      @logout="emit('logout')"
      @tab-change="activeTab = $event"
    />

