      <div>Feed: {{ feed }}</div>
      <div>Eggs: {{ eggs }}</div>
    </div>

    <ChickenPen 
      v-if="activeTab === 'chickens'"
      :chickens="chickens"
      @feed="feedChicken"
      @collect="collectEggs"
    />

    <TaskList 
      v-if="activeTab === 'tasks'"
      @complete="feed += $event"
    />

