<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue'

const emit = defineEmits(['whack'])

const moles = ref(Array(9).fill(false))
const gameActive = ref(false)
const timer = ref<NodeJS.Timeout | null>(null)
const score = ref(0)

const startGame = () => {
  gameActive.value = true
  activateRandomMole()
}

const stopGame = () => {
  gameActive.value = false
  if (timer.value) clearTimeout(timer.value)
  moles.value = moles.value.map(() => false)
}

const activateRandomMole = () => {
  if (!gameActive.value) return

  // Deactivate all moles first
  moles.value = moles.value.map(() => false)

  // Activate a random mole
  const randomIndex = Math.floor(Math.random() * moles.value.length)
  moles.value[randomIndex] = true

  // Set timeout for mole to disappear
  timer.value = setTimeout(() => {
    moles.value[randomIndex] = false
    activateRandomMole()
  }, 1000 + Math.random() * 2000)
}

const whackMole = (index: number) => {
  if (moles.value[index]) {
    moles.value[index] = false
    emit('whack')
  }
}

onMounted(() => {
  startGame()
})

onUnmounted(() => {
  stopGame()
})
</script>

<template>
