import React, { useState, useEffect } from 'react';
import { Zap, Trophy, Shield, Sword, Skull, Gem, Coins } from 'lucide-react';

type Symbol = {
  id: number;
  name: string;
  icon: JSX.Element;
  multiplier: number;
  color: string;
};

type Payline = {
  id: number;
  pattern: number[];
  payout: number;
};

type GameHistory = {
  id: number;
  timestamp: string;
  result: string;
  winAmount: number;
};

const OlympusSlotGame: React.FC = () => {
  // Game configuration
  const REELS = 5;
  const ROWS = 3;
  const SYMBOLS: Symbol[] = [
    { id: 1, name: 'Zeus', icon: <Zap size={40} />, multiplier: 10, color: 'text-yellow-400' },
    { id: 2, name: 'Athena', icon: <Shield size={40} />, multiplier: 8, color: 'text-blue-400' },
    { id: 3, name: 'Ares', icon: <Sword size={40} />, multiplier: 6, color: 'text-red-400' },
    { id: 4, name: 'Hades', icon: <Skull size={40} />, multiplier: 5, color: 'text-purple-400' },
    { id: 5, name: 'Artemis', icon: <Gem size={40} />, multiplier: 4, color: 'text-green-400' },
    { id: 6, name: 'Coin', icon: <Coins size={40} />, multiplier: 2, color: 'text-amber-500' },
  ];

  const PAYLINES: Payline[] = [
    { id: 1, pattern: [1, 1, 1, 1, 1], payout: 50 }, // Top line
    { id: 2, pattern: [2, 2, 2, 2, 2], payout: 25 }, // Middle line
    { id: 3, pattern: [3, 3, 3, 3, 3], payout: 25 }, // Bottom line
    { id: 4, pattern: [1, 2, 3, 2, 1], payout: 30 }, // V shape
    { id: 5, pattern: [3, 2, 1, 2, 3], payout: 30 }, // Inverted V
  ];

  // Game state
  const [reels, setReels] = useState<Symbol[][]>([]);
  const [balance, setBalance] = useState<number>(1000);
  const [bet, setBet] = useState<number>(10);
  const [winAmount, setWinAmount] = useState<number>(0);
  const [isSpinning, setIsSpinning] = useState<boolean>(false);
  const [showPaylines, setShowPaylines] = useState<boolean>(false);
  const [gameHistory, setGameHistory] = useState<GameHistory[]>([]);
  const [winningPaylines, setWinningPaylines] = useState<Payline[]>([]);

  // Initialize reels
  useEffect(() => {
    initializeReels();
  }, []);

  const initializeReels = () => {
    const newReels: Symbol[][] = [];
    for (let i = 0; i < REELS; i++) {
      const reel: Symbol[] = [];
      for (let j = 0; j < ROWS; j++) {
        reel.push(SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)]);
      }
      newReels.push(reel);
    }
    setReels(newReels);
  };

  const spin = () => {
    if (isSpinning || balance < bet) return;

    setIsSpinning(true);
    setWinAmount(0);
    setWinningPaylines([]);
    setBalance(prev => prev - bet);

    // Simulate spinning animation
    let spinCount = 0;
    const spinInterval = setInterval(() => {
      const newReels = reels.map(reel => {
        const newReel = [...reel];
        newReel.shift();
        newReel.push(SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)]);
        return newReel;
      });
      setReels(newReels);
      spinCount++;

      if (spinCount >= 10) {
        clearInterval(spinInterval);
        setTimeout(() => {
          checkWins();
          setIsSpinning(false);
        }, 300);
      }
    }, 100);
  };

  const checkWins = () => {
    let totalWin = 0;
    const newWinningPaylines: Payline[] = [];

    PAYLINES.forEach(payline => {
      const symbols: Symbol[] = [];
      for (let i = 0; i < REELS; i++) {
        symbols.push(reels[i][payline.pattern[i] - 1]);
      }

      // Check if all symbols are the same
      const firstSymbol = symbols[0];
      const isWin = symbols.every(sym => sym.id === firstSymbol.id);

      if (isWin) {
        const win = bet * firstSymbol.multiplier;
        totalWin += win;
        newWinningPaylines.push(payline);
      }
    });

    setWinAmount(totalWin);
    setWinningPaylines(newWinningPaylines);
    if (totalWin > 0) {
      setBalance(prev => prev + totalWin);
      addToHistory(totalWin);
    }
  };

  const addToHistory = (win: number) => {
    const newHistory: GameHistory = {
      id: Date.now(),
      timestamp: new Date().toLocaleTimeString(),
      result: win > 0 ? 'Win' : 'Loss',
      winAmount: win,
    };
    setGameHistory(prev => [newHistory, ...prev.slice(0, 9)]);
  };

  const changeBet = (amount: number) => {
    const newBet = bet + amount;
    if (newBet >= 1 && newBet <= balance) {
      setBet(newBet);
    }
  };

  return (
    <div className="min-h-screen bg-gainsboro flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-4xl bg-darkSlateBlue rounded-xl shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="bg-darkSlateBlue-800 p-4 text-white text-center">
          <h1 className="text-3xl font-bold">Olympus Slots</h1>
          <p className="text-sm">Spin to win the favor of the gods!</p>
        </div>

        {/* Game Area */}
        <div className="p-6">
          {/* Reels */}
          <div className="relative bg-darkSlateBlue-700 rounded-lg p-4 mb-6">
            <div className="grid grid-cols-5 gap-2">
              {reels.map((reel, reelIndex) => (
                <div key={reelIndex} className="flex flex-col items-center">
                  {reel.map((symbol, rowIndex) => {
                    const isWinning = winningPaylines.some(payline => 
                      payline.pattern[reelIndex] === rowIndex + 1
                    );
                    return (
                      <div
                        key={`${reelIndex}-${rowIndex}`}
                        className={`w-20 h-20 flex items-center justify-center border-2 rounded-lg mb-2 transition-all duration-200 ${
                          isWinning 
                            ? 'bg-yellow-500 border-yellow-300 transform scale-105 shadow-lg' 
                            : 'bg-darkSlateBlue-600 border-darkSlateBlue-500'
                        }`}
                      >
                        <span className={`${symbol.color} ${isWinning ? 'text-white' : ''}`}>
                          {symbol.icon}
                        </span>
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>

            {/* Payline indicators */}
            {showPaylines && (
              <div className="absolute inset-0 pointer-events-none">
                {PAYLINES.map(payline => (
                  <div key={payline.id} className="absolute left-0 right-0 h-1 bg-white opacity-30" 
                    style={{ top: `${(payline.pattern[0] - 0.5) * (100 / ROWS)}%` }}></div>
                ))}
              </div>
            )}
          </div>

          {/* Controls */}
          <div className="flex flex-col md:flex-row gap-4 mb-6">
            <div className="bg-darkSlateBlue-700 p-4 rounded-lg flex-1">
              <div className="flex justify-between items-center mb-2">
                <span className="text-white">Balance:</span>
                <span className="text-yellow-400 font-bold">{balance}</span>
              </div>
              <div className="flex justify-between items-center mb-4">
                <span className="text-white">Bet:</span>
                <div className="flex items-center gap-2">
                  <button 
                    onClick={() => changeBet(-1)}
                    className="bg-darkSlateBlue-600 text-white px-3 py-1 rounded hover:bg-darkSlateBlue-500 disabled:opacity-50"
                    disabled={bet <= 1}
                  >
                    -
                  </button>
                  <span className="text-yellow-400 font-bold">{bet}</span>
                  <button 
                    onClick={() => changeBet(1)}
                    className="bg-darkSlateBlue-600 text-white px-3 py-1 rounded hover:bg-darkSlateBlue-500 disabled:opacity-50"
                    disabled={bet >= balance}
                  >
                    +
                  </button>
                </div>
              </div>
              <button
                onClick={spin}
                disabled={isSpinning || balance < bet}
                className={`w-full py-3 rounded-lg font-bold text-white transition-all ${
                  isSpinning 
                    ? 'bg-gray-500' 
                    : 'bg-gradient-to-r from-yellow-500 to-yellow-600 hover:from-yellow-600 hover:to-yellow-700'
                }`}
              >
                {isSpinning ? 'Spinning...' : 'SPIN'}
              </button>
            </div>

            <div className="bg-darkSlateBlue-700 p-4 rounded-lg flex-1">
              <div className="flex justify-between items-center mb-4">
                <span className="text-white">Last Win:</span>
                <span className="text-green-400 font-bold">{winAmount}</span>
              </div>
              <button
                onClick={() => setShowPaylines(!showPaylines)}
                className="w-full py-2 bg-darkSlateBlue-600 text-white rounded hover:bg-darkSlateBlue-500"
              >
                {showPaylines ? 'Hide Paylines' : 'Show Paylines'}
              </button>
            </div>
          </div>

          {/* Game History */}
          <div className="bg-darkSlateBlue-700 p-4 rounded-lg">
            <h3 className="text-white font-bold mb-2">Recent Games</h3>
            <div className="max-h-40 overflow-y-auto">
              {gameHistory.length > 0 ? (
                <table className="w-full text-white">
                  <thead>
                    <tr className="border-b border-darkSlateBlue-600">
                      <th className="text-left py-2">Time</th>
                      <th className="text-left">Result</th>
                      <th className="text-right">Amount</th>
                    </tr>
                  </thead>
                  <tbody>
                    {gameHistory.map(game => (
                      <tr key={game.id} className="border-b border-darkSlateBlue-600">
                        <td className="py-2">{game.timestamp}</td>
                        <td className={game.result === 'Win' ? 'text-green-400' : 'text-red-400'}>
                          {game.result}
                        </td>
                        <td className="text-right">
                          {game.result === 'Win' ? '+' : ''}{game.winAmount}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p className="text-gray-400 text-center py-4">No games played yet</p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default OlympusSlotGame;
</boltAction>

