import { useState } from 'react'
import { useAuth } from '../context/AuthContext'
import { Sword, Shield, Zap, Flame, Droplets } from 'lucide-react'

export default function Battle() {
  const { user } = useAuth()
  const [selectedPokemon, setSelectedPokemon] = useState<string | null>(null)
  const [battleLog, setBattleLog] = useState<string[]>([])
  const [opponentPokemon, setOpponentPokemon] = useState<Pokemon | null>(null)

  if (!user) return <div>Please login to access battles</div>

  const startBattle = () => {
    if (!selectedPokemon) return

    // Generate random opponent
    const opponent = generateRandomPokemon()
    setOpponentPokemon(opponent)
    setBattleLog([`A wild ${opponent.name} appeared!`])

    // Start battle sequence
    simulateBattle(selectedPokemon, opponent)
  }

  const simulateBattle = (playerPokemonId: string, opponent: Pokemon) => {
    const playerPokemon = user.pokemons.find(p => p.id === playerPokemonId)
    if (!playerPokemon) return

    // Simple battle simulation
    const turns = 5
    let playerHp = playerPokemon.hp
    let opponentHp = opponent.hp

    for (let i = 0; i < turns; i++) {
      // Player attacks
      const playerDamage = Math.max(1, playerPokemon.attack - opponent.defense / 2)
      opponentHp = Math.max(0, opponentHp - playerDamage)
      setBattleLog(prev => [...prev, 
        `${playerPokemon.name} attacks ${opponent.name} for ${playerDamage} damage!`])

      if (opponentHp <= 0) {
        setBattleLog(prev => [...prev, `${opponent.name} fainted! You win!`])
        return
      }

      // Opponent attacks
      const opponentDamage = Math.max(1, opponent.attack - playerPokemon.defense / 2)
      playerHp = Math.max(0, playerHp - opponentDamage)
      setBattleLog(prev => [...prev, 
        `${opponent.name} attacks ${playerPokemon.name} for ${opponentDamage} damage!`])

      if (playerHp <= 0) {
        setBattleLog(prev => [...prev, `${playerPokemon.name} fainted! You lose!`])
        return
      }
    }

    setBattleLog(prev => [...prev, "Battle ended in a draw!"])
  }

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'Electric': return <Zap className="text-yellow-500" />
      case 'Fire': return <Flame className="text-red-500" />
      case 'Water': return <Droplets className="text-blue-500" />
      default: return <Shield />
    }
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <h2 className="text-3xl font-bold text-amber-900 mb-6">Battle Arena</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="bg-amber-100 p-6 rounded-xl border border-amber-200">
          <h3 className="text-xl font-semibold text-amber-800 mb-4">Your Pokémon</h3>
          <div className="space-y-4">
            {user.pokemons.map(pokemon => (
              <div 
                key={pokemon.id}
                onClick={() => setSelectedPokemon(pokemon.id)}
                className={`p-4 rounded-lg cursor-pointer transition ${selectedPokemon === pokemon.id ? 'bg-amber-300' : 'bg-amber-50 hover:bg-amber-200'}`}
              >
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-white rounded-full">
                    {getTypeIcon(pokemon.type)}
                  </div>
                  <div>
                    <h4 className="font-medium">{pokemon.name}</h4>
                    <div className="flex gap-4 text-sm text-amber-700">
                      <span>Lv: {pokemon.level}</span>
                      <span>HP: {pokemon.hp}</span>
                      <span>ATK: {pokemon.attack}</span>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          <button
            onClick={startBattle}
            disabled={!selectedPokemon}
            className={`mt-6 w-full py-3 rounded-lg font-medium ${selectedPokemon ? 'bg-amber-600 hover:bg-amber-700 text-white' : 'bg-amber-200 text-amber-600 cursor-not-allowed'}`}
          >
            Start Battle
          </button>
        </div>

        <div className="bg-amber-100 p-6 rounded-xl border border-amber-200">
          <h3 className="text-xl font-semibold text-amber-800 mb-4">Battle Log</h3>
          <div className="h-96 overflow-y-auto bg-amber-50 p-4 rounded-lg">
            {battleLog.length > 0 ? (
              <ul className="space-y-2">
                {battleLog.map((log, i) => (
                  <li key={i} className="text-amber-800">{log}</li>
                ))}
              </ul>
            ) : (
              <p className="text-amber-600">Select a Pokémon and start a battle!</p>
            )}
          </div>

          {opponentPokemon && (
            <div className="mt-6 p-4 bg-amber-200 rounded-lg">
              <h4 className="font-medium mb-2">Opponent</h4>
              <div className="flex items-center gap-3">
                <div className="p-2 bg-white rounded-full">
                  {getTypeIcon(opponentPokemon.type)}
                </div>
                <div>
                  <h4 className="font-medium">{opponentPokemon.name}</h4>
                  <div className="flex gap-4 text-sm text-amber-700">
                    <span>Lv: {opponentPokemon.level}</span>
                    <span>HP: {opponentPokemon.hp}</span>
                    <span>ATK: {opponentPokemon.attack}</span>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

