import { useState } from 'react'
import { useAuth } from '../context/AuthContext'
import { HeartPulse, Zap, Flame, Droplets } from 'lucide-react'

export default function Breeding() {
  const { user } = useAuth()
  const [parent1, setParent1] = useState<string | null>(null)
  const [parent2, setParent2] = useState<string | null>(null)
  const [offspring, setOffspring] = useState<Pokemon | null>(null)
  const [message, setMessage] = useState<string>('')

  if (!user) return <div>Please login to access breeding</div>

  const breedPokemon = () => {
    if (!parent1 || !parent2) return

    const pokemon1 = user.pokemons.find(p => p.id === parent1)
    const pokemon2 = user.pokemons.find(p => p.id === parent2)
    if (!pokemon1 || !pokemon2) return

    // Simple breeding logic
    if (pokemon1.id === pokemon2.id) {
      setMessage("Cannot breed the same Pokémon!")
      return
    }

    const newPokemon = createOffspring(pokemon1, pokemon2)
    setOffspring(newPokemon)
    setMessage(`Successfully bred ${pokemon1.name} and ${pokemon2.name}!`)
  }

  const createOffspring = (p1: Pokemon, p2: Pokemon): Pokemon => {
    // Determine type (50% chance for either parent's type)
    const type = Math.random() > 0.5 ? p1.type : p2.type

    // Average stats with some randomness
    const level = Math.max(1, Math.floor((p1.level + p2.level) / 2))
    const hp = Math.floor((p1.hp + p2.hp) / 2 * (0.9 + Math.random() * 0.2))
    const attack = Math.floor((p1.attack + p2.attack) / 2 * (0.9 + Math.random() * 0.2))
    const defense = Math.floor((p1.defense + p2.defense) / 2 * (0.9 + Math.random() * 0.2))
    const speed = Math.floor((p1.speed + p2.speed) / 2 * (0.9 + Math.random() * 0.2))

    // Generate name based on parents
    const name = generateOffspringName(p1.name, p2.name)

    return {
      id: Date.now().toString(),
      name,
      type,
      level,
      hp,
      attack,
      defense,
      speed
    }
  }

  const generateOffspringName = (name1: string, name2: string): string => {
    // Simple name combination logic
    const part1 = name1.slice(0, Math.ceil(name1.length / 2))
    const part2 = name2.slice(Math.floor(name2.length / 2))
    return part1 + part2
  }

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'Electric': return <Zap className="text-yellow-500" />
      case 'Fire': return <Flame className="text-red-500" />
      case 'Water': return <Droplets className="text-blue-500" />
      default: return <HeartPulse className="text-green-500" />
    }
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <h2 className="text-3xl font-bold text-amber-900 mb-6">Breeding Center</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="bg-amber-100 p-6 rounded-xl border border-amber-200">
          <h3 className="text-xl font-semibold text-amber-800 mb-4">Select Parents</h3>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <h4 className="font-medium mb-2">Parent 1</h4>
              <div className="space-y-2">
                {user.pokemons.map(pokemon => (
                  <div 
                    key={`parent1-${pokemon.id}`}
                    onClick={() => setParent1(pokemon.id)}
                    className={`p-3 rounded-lg cursor-pointer transition ${parent1 === pokemon.id ? 'bg-amber-300' : 'bg-amber-50 hover:bg-amber-200'}`}
                  >
                    <div className="flex items-center gap-2">
                      {getTypeIcon(pokemon.type)}
                      <span>{pokemon.name}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div>
              <h4 className="font-medium mb-2">Parent 2</h4>
              <div className="space-y-2">
                {user.pokemons.map(pokemon => (
                  <div 
                    key={`parent2-${pokemon.id}`}
                    onClick={() => setParent2(pokemon.id)}
                    className={`p-3 rounded-lg cursor-pointer transition ${parent2 === pokemon.id ? 'bg-amber-300' : 'bg-amber-50 hover:bg-amber-200'}`}
                  >
                    <div className="flex items-center gap-2">
                      {getTypeIcon(pokemon.type)}
                      <span>{pokemon.name}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <button
            onClick={breedPokemon}
            disabled={!parent1 || !parent2}
            className={`mt-6 w-full py-3 rounded-lg font-medium ${parent1 && parent2 ? 'bg-amber-600 hover:bg-amber-700 text-white' : 'bg-amber-200 text-amber-600 cursor-not-allowed'}`}
          >
            Breed Pokémon
          </button>

          {message && (
            <p className={`mt-4 p-2 rounded ${message.includes('Success') ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
              {message}
            </p>
          )}
        </div>

        <div className="bg-amber-100 p-6 rounded-xl border border-amber-200">
          <h3 className="text-xl font-semibold text-amber-800 mb-4">Offspring</h3>

          {offspring ? (
            <div className="bg-amber-50 p-4 rounded-lg">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-white rounded-full">
                  {getTypeIcon(offspring.type)}
                </div>
                <div>
                  <h4 className="text-xl font-medium">{offspring.name}</h4>
                  <div className="text-sm text-amber-700">
                    <p>Type: {offspring.type}</p>
                    <p>Level: {offspring.level}</p>
                    <p>HP: {offspring.hp}</p>
                    <p>Attack: {offspring.attack}</p>
                    <p>Defense: {offspring.defense}</p>
                    <p>Speed: {offspring.speed}</p>
                  </div>
                </div>
              </div>

              <button className="mt-4 w-full py-2 bg-amber-500 hover:bg-amber-600 text-white rounded-lg">
                Add to Collection
              </button>
            </div>
          ) : (
            <div className="bg-amber-50 p-4 rounded-lg text-center">
              <p className="text-amber-600">Breed two Pokémon to see their offspring!</p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
