<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps({
  isLoggedIn: Boolean
})

const activities = ref([
  {
    id: 1,
    name: 'Daily Login',
    description: 'Log in to the game to receive your daily reward',
    completed: false,
    reward: '100 coins',
    rules: 'Must log in between 12:00 AM and 11:59 PM'
  },
  {
    id: 2,
    name: 'Complete 3 Matches',
    description: 'Play and complete 3 matches in any game mode',
    completed: false,
    reward: '200 coins + XP Boost',
    rules: 'Matches must be completed (win or lose)'
  },
  {
    id: 3,
    name: 'Defeat 10 Enemies',
    description: 'Defeat a total of 10 enemies across all matches',
    completed: false,
    reward: 'Special Skin',
    rules: 'Enemies must be defeated in PvP modes only'
  }
])

const selectedActivity = ref(null)

const toggleComplete = (activityId) => {
  if (!props.isLoggedIn) return

  const activity = activities.value.find(a => a.id === activityId)
  if (activity) {
    activity.completed = !activity.completed
  }
}

const selectActivity = (activity) => {
  selectedActivity.value = activity
}
</script>

<template>
  <div class="daily-activities">
    <div class="activity-list">
      <h2>Today's Activities</h2>
      <div 
        v-for="activity in activities" 
        :key="activity.id"
        class="activity-card"
        :class="{ selected: selectedActivity?.id === activity.id }"
        @click="selectActivity(activity)"
      >
        <h3>{{ activity.name }}</h3>
        <p>{{ activity.description }}</p>
        <div class="activity-footer">
          <span class="reward">Reward: {{ activity.reward }}</span>
          <button 
            v-if="isLoggedIn"
            @click.stop="toggleComplete(activity.id)"
            :class="{ completed: activity.completed }"
          >
            {{ activity.completed ? 'Completed' : 'Mark Complete' }}
          </button>
          <span v-else class="login-notice">Login to complete</span>
        </div>
      </div>
