      <h2>{{ selectedActivity.name }}</h2>
      <p>{{ selectedActivity.description }}</p>

      <div class="details-section">
        <h3>Rules:</h3>
        <p>{{ selectedActivity.rules }}</p>
      </div>

      <div class="details-section">
        <h3>Reward:</h3>
        <p>{{ selectedActivity.reward }}</p>
      </div>

      <div class="details-section" v-if="isLoggedIn">
