<script setup lang="ts">
import { ref, computed } from 'vue'

const categories = [
  { id: 1, name: 'Technology' },
  { id: 2, name: 'Science' },
  { id: 3, name: 'Business' },
  { id: 4, name: 'Health' }
]

const sampleData = [
  { id: 1, title: 'Vue 3 Composition API', category: 'Technology', content: 'Guide to using Vue 3 Composition API' },
  { id: 2, title: 'Quantum Computing', category: 'Science', content: 'Introduction to quantum computing principles' },
  { id: 3, title: 'Market Trends 2023', category: 'Business', content: 'Analysis of current market trends' },
  { id: 4, title: 'Mental Wellness', category: 'Health', content: 'Tips for maintaining mental health' }
]

const selectedCategory = ref('')
const searchQuery = ref('')
const livenessInput = ref('')
const isLive = ref(false)

const filteredResults = computed(() => {
  let results = sampleData

  if (selectedCategory.value) {
    results = results.filter(item => item.category === selectedCategory.value)
  }

  if (searchQuery.value) {
    const query = searchQuery.value.toLowerCase()
    results = results.filter(item => 
      item.title.toLowerCase().includes(query) || 
      item.content.toLowerCase().includes(query)
    )
  }

  return results
})

const checkLiveness = () => {
  isLive.value = livenessInput.value.length > 3
}
</script>

