<script setup lang="ts">
import { ref, computed } from 'vue'
import SearchTool from './components/SearchTool.vue'
import Checklist from './components/Checklist.vue'
import AnalyticalReport from './components/AnalyticalReport.vue'
import ReportGenerator from './components/ReportGenerator.vue'

const currentStage = ref(0)
const searchTerm = ref('')
const checklist1Items = ref([
  { id: 'opt1', label: 'Option 1', checked: false },
  { id: 'opt2', label: 'Option 2', checked: false },
  { id: 'opt3', label: 'Option 3', checked: false }
])
const checklist2Items = ref([
  { id: 'detail1', label: 'Detail Analysis 1', checked: false },
  { id: 'detail2', label: 'Detail Analysis 2', checked: false }
])

const selectedItems1 = computed(() => 
  checklist1Items.value.filter(item => item.checked).map(item => item.label)
)

const selectedItems2 = computed(() => 
  checklist2Items.value.filter(item => item.checked).map(item => item.label)
)

const reportData = computed(() => ({
  searchTerm: searchTerm.value,
  primarySelections: selectedItems1.value,
  secondarySelections: selectedItems2.value,
  analysis: {
    score: Math.floor(Math.random() * 100),
    timestamp: new Date().toISOString()
  }
}))

function nextStage() {
  currentStage.value++
}

function generateReport() {
  alert('Report generated! Check console for data')
  console.log('Final Report:', reportData.value)
}
</script>

<template>
  <div class="app-container">
    <h1>Analytical Tool</h1>

    <SearchTool 
      v-if="currentStage === 0"
      v-model="searchTerm"
      @next="nextStage"
    />

    <Checklist 
      v-if="currentStage === 1"
      :items="checklist1Items"
      title="Primary Checklist"
      @update:items="checklist1Items = $event"
      @next="nextStage"
    />

    <AnalyticalReport 
      v-if="currentStage === 2"
      :selected-items="selectedItems1"
      @next="nextStage"
    />

    <Checklist 
      v-if="currentStage === 3"
      :items="checklist2Items"
      title="Secondary Checklist"
      @update:items="checklist2Items = $event"
      @next="nextStage"
    />

    <ReportGenerator 
      v-if="currentStage === 4"
      :report-data="reportData"
      @generate="generateReport"
    />
  </div>
</template>

