<script setup lang="ts">
import { computed } from 'vue'

const props = defineProps({
  search: String
})

const activities = [
  { id: 1, item: 'Widget A', type: 'Inbound', quantity: 50, timestamp: '2023-06-15 09:30' },
  { id: 2, item: 'Gadget B', type: 'Outbound', quantity: 25, timestamp: '2023-06-15 10:15' },
  { id: 3, item: 'Tool C', type: 'Inbound', quantity: 100, timestamp: '2023-06-14 14:45' },
  { id: 4, item: 'Part D', type: 'Outbound', quantity: 15, timestamp: '2023-06-14 16:20' },
  { id: 5, item: 'Material E', type: 'Inbound', quantity: 75, timestamp: '2023-06-13 11:10' }
]

const filteredActivities = computed(() => {
  if (!props.search) return activities
  return activities.filter(activity => 
    activity.item.toLowerCase().includes(props.search.toLowerCase()) ||
    activity.type.toLowerCase().includes(props.search.toLowerCase())
  )
})
</script>

