<script setup lang="ts">
import { ref, watch } from 'vue'

const props = defineProps<{
  dataset: any[]
}>()

const emit = defineEmits(['cleaned'])

const cleanedData = ref<any[]>([])
const cleaningOptions = ref({
  removeDuplicates: true,
  fillEmpty: true,
  emptyValue: 'N/A',
  trimStrings: true
})

watch(() => props.dataset, () => {
  cleanedData.value = [...props.dataset]
}, { immediate: true })

const applyCleaning = () => {
  let result = [...props.dataset]

  if (cleaningOptions.value.removeDuplicates) {
    const unique = new Set()
    result = result.filter(item => {
      const key = JSON.stringify(item)
      if (unique.has(key)) return false
      unique.add(key)
      return true
    })
  }

  if (cleaningOptions.value.fillEmpty) {
    result = result.map(item => {
      const newItem = {...item}
      for (const key in newItem) {
        if (newItem[key] === '' || newItem[key] == null) {
          newItem[key] = cleaningOptions.value.emptyValue
        }
      }
      return newItem
    })
  }

  if (cleaningOptions.value.trimStrings) {
    result = result.map(item => {
      const newItem = {...item}
      for (const key in newItem) {
        if (typeof newItem[key] === 'string') {
          newItem[key] = newItem[key].trim()
        }
      }
      return newItem
    })
  }

  cleanedData.value = result
  emit('cleaned', result)
}

const downloadCleanedData = () => {
  const dataStr = JSON.stringify(cleanedData.value, null, 2)
  const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr)

  const exportFileDefaultName = 'cleaned-data.json'

  const linkElement = document.createElement('a')
  linkElement.setAttribute('href', dataUri)
  linkElement.setAttribute('download', exportFileDefaultName)
  linkElement.click()
}
</script>

