<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import * as d3 from 'd3'

const props = defineProps<{
  dataset: any[]
}>()

const chartType = ref('bar')
const selectedColumn = ref<string>('')
const chartContainer = ref<HTMLElement | null>(null)

const columns = computed(() => {
  if (!props.dataset.length) return []
  return Object.keys(props.dataset[0])
})

onMounted(() => {
  if (columns.value.length) {
    selectedColumn.value = columns.value[0]
  }
})

const renderChart = () => {
  if (!chartContainer.value || !selectedColumn.value) return

  // Clear previous chart
  chartContainer.value.innerHTML = ''

  // Get data for selected column
  const data = props.dataset.map(item => item[selectedColumn.value])

  // Create SVG
  const svg = d3.select(chartContainer.value)
    .append('svg')
    .attr('width', '100%')
    .attr('height', '400')

  // Create scales
  const xScale = d3.scaleBand()
    .domain(data.map((_, i) => i.toString()))
    .range([50, 750])
    .padding(0.2)

  const yScale = d3.scaleLinear()
    .domain([0, d3.max(data) || 1])
    .range([350, 50])

  // Draw bars
  svg.selectAll('rect')
    .data(data)
    .enter()
    .append('rect')
    .attr('x', (_, i) => xScale(i.toString()) || 0)
    .attr('y', d => yScale(Number(d)))
    .attr('width', xScale.bandwidth())
    .attr('height', d => 350 - yScale(Number(d)))
    .attr('fill', 'firebrick')

  // Add axes
  svg.append('g')
    .attr('transform', 'translate(0, 350)')
    .call(d3.axisBottom(xScale))

  svg.append('g')
    .attr('transform', 'translate(50, 0)')
    .call(d3.axisLeft(yScale))

  // Add title
  svg.append('text')
    .attr('x', 400)
    .attr('y', 30)
    .attr('text-anchor', 'middle')
    .text(`Distribution of ${selectedColumn.value}`)
}
</script>

