<script setup lang="ts">
import { computed } from 'vue'

const props = defineProps<{
  dataset: any[]
}>()

const stats = computed(() => {
  if (!props.dataset.length) return {}

  const firstItem = props.dataset[0]
  const result: Record<string, any> = {}

  Object.keys(firstItem).forEach(key => {
    const values = props.dataset.map(item => item[key])
    const numericValues = values.filter(v => !isNaN(Number(v))).map(Number)

    if (numericValues.length) {
      result[key] = {
        count: values.length,
        numericCount: numericValues.length,
        min: d3.min(numericValues),
        max: d3.max(numericValues),
        mean: d3.mean(numericValues),
        median: d3.median(numericValues),
        stdDev: d3.deviation(numericValues)
      }
    } else {
      // For non-numeric data
      const uniqueValues = new Set(values)
      result[key] = {
        count: values.length,
        uniqueCount: uniqueValues.size,
        sampleValues: Array.from(uniqueValues).slice(0, 5)
      }
    }
  })

  return result
})
</script>

