<script setup lang="ts">
const messages = ref([
  { id: 1, sender: 'lawyer', text: 'Hello, how can I help you today?', time: '10:30 AM' },
  { id: 2, sender: 'user', text: 'I have a question about my rental agreement', time: '10:31 AM' }
])

const newMessage = ref('')

function sendMessage() {
  if (newMessage.value.trim()) {
    messages.value.push({
      id: messages.value.length + 1,
      sender: 'user',
      text: newMessage.value,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    })
    newMessage.value = ''

    // In a real app, this would send to a server
    setTimeout(() => {
      messages.value.push({
        id: messages.value.length + 1,
        sender: 'lawyer',
        text: 'I can help with that. Could you share more details?',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      })
    }, 1000)
  }
}
</script>

