<script setup lang="ts">
import { ref } from 'vue'

const messages = ref<Array<{text: string, sender: 'user' | 'ai'}>>([])
const userInput = ref('')
const isListening = ref(false)

const sendMessage = () => {
  if (userInput.value.trim()) {
    messages.value.push({
      text: userInput.value,
      sender: 'user'
    })
    getAIResponse(userInput.value)
    userInput.value = ''
  }
}

const getAIResponse = (message: string) => {
  // Simulate AI response
  setTimeout(() => {
    const responses = [
      "That's a great sentence! Did you know 'hello' comes from 'hallo' in German?",
      "Your English is improving! Try using more descriptive words.",
      "Good job! Here's a grammar tip: remember to use 'a' before consonant sounds."
    ]
    messages.value.push({
      text: responses[Math.floor(Math.random() * responses.length)],
      sender: 'ai'
    })
  }, 1000)
}

const toggleVoiceInput = () => {
  if (!('webkitSpeechRecognition' in window)) {
    alert("Speech recognition not supported in your browser")
    return
  }

  const recognition = new webkitSpeechRecognition()
  recognition.continuous = false
  recognition.interimResults = false

  recognition.onstart = () => {
    isListening.value = true
  }

  recognition.onresult = (event) => {
    const transcript = event.results[0][0].transcript
    userInput.value = transcript
    isListening.value = false
  }

  recognition.onerror = () => {
    isListening.value = false
  }

  recognition.onend = () => {
    isListening.value = false
  }

  if (isListening.value) {
    recognition.stop()
  } else {
    recognition.start()
  }
}
</script>

<template>
  <div class="chat-container">
    <div class="messages">
      <div 
        v-for="(message, index) in messages" 
        :key="index" 
        :class="['message', message.sender]"
      >
        {{ message.text }}
      </div>
    </div>

    <div class="input-area">
      <input 
        v-model="userInput" 
        @keyup.enter="sendMessage" 
        placeholder="Type your message..."
      />
      <button @click="sendMessage">Send</button>
      <button 
        @click="toggleVoiceInput" 
        :class="{ active: isListening }"
      >
        {{ isListening ? 'Listening...' : 'Voice' }}
      </button>
    </div>
  </div>
</template>

