<script setup lang="ts">
import { ref } from 'vue'

const emit = defineEmits(['verification-required', 'verification-not-required'])

const questions = ref([
  {
    id: 1,
    text: 'Are you purchasing age-restricted products?',
    options: ['Yes', 'No'],
    verificationTrigger: 'Yes'
  },
  {
    id: 2,
    text: 'Is this your first purchase with us?',
    options: ['Yes', 'No'],
    verificationTrigger: 'Yes'
  },
  {
    id: 3,
    text: 'Is the purchase amount over $1000?',
    options: ['Yes', 'No'],
    verificationTrigger: 'Yes'
  }
])

const answers = ref<Record<number, string>>({})
const currentQuestionIndex = ref(0)

const handleAnswer = (answer: string) => {
  answers.value[questions.value[currentQuestionIndex.value].id] = answer

  if (questions.value[currentQuestionIndex.value].verificationTrigger === answer) {
    emit('verification-required', `cust-${Date.now()}`)
    return
  }

  if (currentQuestionIndex.value < questions.value.length - 1) {
    currentQuestionIndex.value++
  } else {
    emit('verification-not-required')
  }
}
</script>

<template>
  <div class="questionnaire-container">
    <div class="question-card">
      <h2>{{ questions[currentQuestionIndex].text }}</h2>
      <div class="options">
        <button 
          v-for="option in questions[currentQuestionIndex].options" 
          :key="option" 
          @click="handleAnswer(option)"
          class="option-btn"
        >
          {{ option }}
        </button>
      </div>
    </div>
  </div>
</template>

<style>
