<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps({
  status: {
    type: String,
    required: true
  },
  customerId: {
    type: String,
    required: true
  }
})

const emit = defineEmits(['complete'])

const idFront = ref<File | null>(null)
const idBack = ref<File | null>(null)
const selfie = ref<File | null>(null)

const handleFileUpload = (event: Event, field: string) => {
  const target = event.target as HTMLInputElement
  if (target.files && target.files[0]) {
    if (field === 'front') idFront.value = target.files[0]
    if (field === 'back') idBack.value = target.files[0]
    if (field === 'selfie') selfie.value = target.files[0]
  }
}

const submitVerification = () => {
  // In a real app, this would upload to a server
  emit('complete')
}
</script>

