<script setup lang="ts">
import { ref } from 'vue'

const customers = ref([
  { id: 'cust-123', name: 'John Doe', status: 'approved', verificationDate: '2023-05-15' },
  { id: 'cust-456', name: 'Jane Smith', status: 'pending', verificationDate: '2023-05-16' },
  { id: 'cust-789', name: 'Bob Johnson', status: 'rejected', verificationDate: '2023-05-14' }
])

const newQuestion = ref('')
const newOptions = ref('')
const newTrigger = ref('')

const questions = ref([
  {
    id: 1,
    text: 'Are you purchasing age-restricted products?',
    options: ['Yes', 'No'],
    verificationTrigger: 'Yes'
  },
  {
    id: 2,
    text: 'Is this your first purchase with us?',
    options: ['Yes', 'No'],
    verificationTrigger: 'Yes'
  }
])

const addQuestion = () => {
  if (newQuestion.value && newOptions.value) {
    questions.value.push({
      id: questions.value.length + 1,
      text: newQuestion.value,
      options: newOptions.value.split(',').map(opt => opt.trim()),
      verificationTrigger: newTrigger.value
    })
    newQuestion.value = ''
    newOptions.value = ''
    newTrigger.value = ''
  }
}

const updateStatus = (customerId: string, newStatus: string) => {
  const customer = customers.value.find(c => c.id === customerId)
  if (customer) {
    customer.status = newStatus
  }
}
</script>

