import { useCustomers } from '../stores/customers'

const customerStore = useCustomers()

const selectedCustomerId = ref('')
const paymentAmount = ref('')
const paymentDescription = ref('')

const qrCodeData = computed(() => {
  if (!selectedCustomerId.value || !paymentAmount.value) return ''

  return JSON.stringify({
    customerId: selectedCustomerId.value,
    amount: parseFloat(paymentAmount.value),
    description: paymentDescription.value,
    timestamp: new Date().toISOString()
  })
})

const processPayment = () => {
  if (!selectedCustomerId.value || !paymentAmount.value) return

  const customer = customerStore.customers.find(c => c.id === selectedCustomerId.value)
  if (customer) {
    customer.totalPayments += parseFloat(paymentAmount.value)
    // In a real app, you would call your payment API here
    alert(`Payment of $${paymentAmount.value} processed for ${customer.name}`)
    paymentAmount.value = ''
    paymentDescription.value = ''
  }
}
