<script setup lang="ts">
import { ref } from 'vue'
import QRCode from 'qrcode'

const productInfo = ref({
  title: '',
  description: '',
  files: [] as File[]
})
const generatedUrl = ref('')
const qrCodeImage = ref('')

const handleFileUpload = (e: Event) => {
  const input = e.target as HTMLInputElement
  if (input.files) {
    productInfo.value.files = Array.from(input.files)
  }
}

const generateQRCode = async () => {
  const randomId = Math.random().toString(36).substring(2, 8)
  generatedUrl.value = `${window.location.origin}/customer/${randomId}`

  try {
    qrCodeImage.value = await QRCode.toDataURL(generatedUrl.value)
  } catch (err) {
    console.error(err)
  }
}
</script>

<template>
  <div class="admin-dashboard">
    <h2>Product Information Upload</h2>

    <div class="form-group">
      <label>Product Title:</label>
      <input v-model="productInfo.title" placeholder="Enter product title">
    </div>

    <div class="form-group">
      <label>Description:</label>
      <textarea v-model="productInfo.description" placeholder="Enter product description"></textarea>
    </div>

    <div class="form-group">
      <label>Upload Files (PDF/Images/Videos):</label>
      <input type="file" multiple @change="handleFileUpload">
    </div>

    <button @click="generateQRCode" class="generate-btn">Generate QR Code</button>

