<script setup lang="ts">
import { ref } from 'vue'

const cart = ref<Array<{id: number, name: string, price: number, quantity: number}>>([])
const paymentMethod = ref('cash')
const customerId = ref('')

const products = [
  { id: 1, name: 'Product A', price: 19.99 },
  { id: 2, name: 'Product B', price: 29.99 },
  { id: 3, name: 'Product C', price: 9.99 }
]

const addToCart = (product: {id: number, name: string, price: number}) => {
  const existingItem = cart.value.find(item => item.id === product.id)
  if (existingItem) {
    existingItem.quantity++
  } else {
    cart.value.push({ ...product, quantity: 1 })
  }
}

const removeFromCart = (productId: number) => {
  const index = cart.value.findIndex(item => item.id === productId)
  if (index !== -1) {
    if (cart.value[index].quantity > 1) {
      cart.value[index].quantity--
    } else {
      cart.value.splice(index, 1)
    }
  }
}

const totalAmount = () => {
  return cart.value.reduce((sum, item) => sum + (item.price * item.quantity), 0)
}

const processTransaction = () => {
  alert(`Transaction processed for $${totalAmount().toFixed(2)} via ${paymentMethod.value}`)
  cart.value = []
}
</script>

<template>
  <div class="cashier">
    <h2>Cashier System</h2>

    <div class="customer-id">
      <label>Customer ID:</label>
      <input v-model="customerId" placeholder="Enter customer ID" />
    </div>

