      <div 
        v-for="product in products" 
        :key="product.id" 
        class="product-card"
        @click="addToCart(product)"
      >
        <h3>{{ product.name }}</h3>
        <p>${{ product.price.toFixed(2) }}</p>
      </div>
    </div>

    <div class="cart-section">
      <h3>Shopping Cart</h3>
      <div v-if="cart.length === 0" class="empty-cart">
        Cart is empty
      </div>
      <div v-else>
        <div v-for="item in cart" :key="item.id" class="cart-item">
          <span>{{ item.name }} (x{{ item.quantity }})</span>
          <span>${{ (item.price * item.quantity).toFixed(2) }}</span>
          <button @click.stop="removeFromCart(item.id)">Remove</button>
        </div>
      </div>
      <div class="total">
        <strong>Total:</strong> ${{ totalAmount().toFixed(2) }}
      </div>
    </div>

    <div class="payment-methods">
      <label>
        <input type="radio" v-model="paymentMethod" value="cash" />
        Cash
      </label>
      <label>
        <input type="radio" v-model="paymentMethod" value="card" />
        Card
      </label>
      <label>
        <input type="radio" v-model="paymentMethod" value="gift" />
        Gift
      </label>
    </div>

    <div class="actions">
      <button class="purchase" @click="processTransaction">Purchase</button>
      <button class="refund">Refund</button>
      <button class="card-replace">Card Replacement</button>
    </div>
  </div>
