<script setup lang="ts">
import { ref } from 'vue'
import RefundRequestForm from './RefundRequestForm.vue'
import RefundStatus from './RefundStatus.vue'
import RefundHistory from './RefundHistory.vue'

const props = defineProps({
  user: {
    type: Object,
    required: true
  }
})

const emit = defineEmits(['logout'])

const activeTab = ref('request')
const refunds = ref([
  { id: '1', amount: 50, status: 'Pending', date: '2023-05-15' },
  { id: '2', amount: 100, status: 'Approved', date: '2023-04-10' },
  { id: '3', amount: 75, status: 'Rejected', date: '2023-03-05' }
])

const handleNewRefund = (refund: any) => {
  refunds.value.unshift({
    id: Math.random().toString(36).substring(7),
    amount: refund.amount,
    status: 'Pending',
    date: new Date().toISOString().split('T')[0]
  })
  activeTab.value = 'status'
}
</script>

<template>
  <div class="dashboard">
    <div class="header">
      <h2>Welcome, {{ user.name }}</h2>
      <button @click="emit('logout')" class="tomato-button">Logout</button>
    </div>

    <div class="tabs">
      <button 
        @click="activeTab = 'request'" 
        :class="{ active: activeTab === 'request' }"
      >
        New Refund
      </button>
      <button 
        @click="activeTab = 'status'" 
        :class="{ active: activeTab === 'status' }"
      >
        Check Status
      </button>
      <button 
        @click="activeTab = 'history'" 
        :class="{ active: activeTab === 'history' }"
      >
        Refund History
      </button>
    </div>

    <div class="tab-content">
      <RefundRequestForm 
        v-if="activeTab === 'request'" 
        @submit="handleNewRefund" 
      />
      <RefundStatus 
        v-else-if="activeTab === 'status'" 
        :refunds="refunds" 
      />
      <RefundHistory 
        v-else 
        :refunds="refunds" 
      />
    </div>
  </div>
</template>

