<script setup lang="ts">
import { computed } from 'vue'

const props = defineProps({
  refunds: {
    type: Array,
    required: true
  }
})

const sortedRefunds = computed(() => {
  return [...props.refunds].sort((a, b) => 
    new Date(b.date).getTime() - new Date(a.date).getTime()
  )
})
</script>

<template>
  <div class="history-container">
    <h3>Refund History</h3>
    <div v-if="sortedRefunds.length === 0" class="empty-state">
      No refund history
    </div>
    <table v-else class="refund-table">
      <thead>
        <tr>
          <th>Date</th>
          <th>Amount</th>
          <th>Status</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="refund in sortedRefunds" :key="refund.id">
          <td>{{ refund.date }}</td>
          <td class="amount">${{ refund.amount }}</td>
          <td>
            <span :class="['status', refund.status.toLowerCase()]">
              {{ refund.status }}
            </span>
          </td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

